package com.chartplotter.collision;

import com.chartplotter.collision.ChartPlotterCollisionData.Chunk;
import com.chartplotter.util.ChartPlotterVersions;
import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.RuneLite;

import javax.inject.Singleton;
import java.io.File;
import java.io.InputStream;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;

@Singleton
public class ChartPlotterCollisionCache {
	private static final String KEY = "collision";
	public static final int UNKNOWN = ChartPlotterCollisionData.UNKNOWN;
	public static final int OPEN = ChartPlotterCollisionData.OPEN;
	public static final int BLOCKED = ChartPlotterCollisionData.BLOCKED;
	public static final int VOID = ChartPlotterCollisionData.VOID;
	public static final int MOVE = ChartPlotterCollisionData.MOVE;
	private final File dir;
	private final Object fileLock = new Object();
	private final Map<Long, Chunk> chunks = new HashMap<>();
	private volatile ChartPlotterCollisionData view = new ChartPlotterCollisionData(new HashMap<>());
	volatile boolean loaded;
	volatile ScheduledExecutorService io;
	ScheduledFuture<?> flushTask;
	private volatile long rev;
	private long savedRev;
	private volatile ChartPlotterCollisionData published = view;
	private final Map<Long, Chunk> live = new HashMap<>();
	private long liveScene = Long.MIN_VALUE;
	private final Map<Long, Long> pending = new HashMap<>();
	private final Set<Long> dirty = new HashSet<>();
	private final ChartPlotterCollisionObjects objects = new ChartPlotterCollisionObjects();
	private WorldView sceneView;
	private boolean capturePending;
	private int baseX;
	private int baseY;
	private volatile long generation;
	private long publication;
	private String seedVersion;
	public ChartPlotterCollisionCache() {this(new File(RuneLite.RUNELITE_DIR, "chart-plotter"));}
	ChartPlotterCollisionCache(File dir) {this.dir = dir;}
	public synchronized void start() {
		if (io != null) return;
		ScheduledThreadPoolExecutor next = new ScheduledThreadPoolExecutor(1, r -> {
			Thread t = new Thread(r, "chart-plotter-collision");
			t.setDaemon(true);
			return t;
		});
		next.setKeepAliveTime(35, TimeUnit.SECONDS);
		next.allowCoreThreadTimeOut(true);
		next.setExecuteExistingDelayedTasksAfterShutdownPolicy(false);
		io = next;
		ScheduledExecutorService ex = io;
		if (!loaded) ex.execute(() -> loadQuiet(ex));
		else if (savedRev != rev) scheduleFlush(ex, 0);
	}
	public void stop() {
		ScheduledExecutorService ex;
		ScheduledFuture<?> task;
		synchronized (this) {
			ex = io;
			io = null;
			task = flushTask;
			flushTask = null;
			invalidateScene();
		}
		if (ex == null) return;
		if (task != null) task.cancel(false);
		ex.shutdownNow();
	}
	public synchronized void invalidateScene() {
		generation++;
		sceneView = null;
		capturePending = true;
		objects.blockers.clear();
		dirty.clear();
		pending.clear();
		view = new ChartPlotterCollisionData(Map.of(), ++publication, generation);
		published = view;
	}
	public void capture(WorldView wv) {
		if (io == null || wv == null) return;
		if (wv != sceneView || baseX != wv.getBaseX() || baseY != wv.getBaseY()) {
			invalidateScene();
			sceneView = wv;
			baseX = wv.getBaseX();
			baseY = wv.getBaseY();
		}
		if (!capturePending || !ChartPlotterCollisionScan.ready(wv)) return;
		objects.seed(wv);
		ChartPlotterCollisionScan scan = ChartPlotterCollisionScan.capture(wv, 0, 0, Integer.MAX_VALUE, Integer.MAX_VALUE, objects.blockers);
		if (scan == null) return;
		capturePending = false;
		mark(scan.baseX, scan.baseY, scan.baseX + scan.width - 1, scan.baseY + scan.height - 1);
		submit(List.of(scan));
	}
	public void changed(TileObject object, boolean spawned) {
		if (io == null || sceneView == null || object == null || object.getWorldView() != sceneView || object.getPlane() != 0 || sceneView.isInstance()) return;
		objects.changed(object, spawned);
		LocalPoint location = object.getLocalLocation();
		Point min = object instanceof GameObject ? ((GameObject) object).getSceneMinLocation() : new Point(location.getSceneX(), location.getSceneY());
		Point max = object instanceof GameObject ? ((GameObject) object).getSceneMaxLocation() : min;
		if (min == null || max == null) return;
		int minX = Math.max(ChartPlotterCollisionScan.EDGE, min.getX() - 1);
		int minY = Math.max(ChartPlotterCollisionScan.EDGE, min.getY() - 1);
		int maxX = Math.min(sceneView.getSizeX() - ChartPlotterCollisionScan.EDGE - 1, max.getX() + 1);
		int maxY = Math.min(sceneView.getSizeY() - ChartPlotterCollisionScan.EDGE - 1, max.getY() + 1);
		if (minX <= maxX && minY <= maxY) mark(baseX + minX, baseY + minY, baseX + maxX, baseY + maxY);
	}
	synchronized void mark(int minX, int minY, int maxX, int maxY) {
		long revision = publication + 1;
		boolean changed = false;
		for (int x = minX >> 3; x <= maxX >> 3; x++) for (int y = minY >> 3; y <= maxY >> 3; y++) {
			long key = ChartPlotterCollisionData.key(x, y);
			if (!dirty.add(key)) continue;
			changed = true;
			pending.put(key, revision);
		}
		if (!changed) return;
		publication = revision;
		published = new ChartPlotterCollisionData(view, pending.keySet(), publication, generation);
	}
	public void refresh(WorldView wv) {
		if (io == null || wv == null) return;
		if (wv != sceneView || baseX != wv.getBaseX() || baseY != wv.getBaseY() || capturePending) {capture(wv); return;}
		if (dirty.isEmpty()) return;
		List<ChartPlotterCollisionScan> scans = new ArrayList<>();
		for (long key : dirty) {
			int x = (int) (key >> 32) * 8 - baseX;
			int y = (int) key * 8 - baseY;
			ChartPlotterCollisionScan scan = ChartPlotterCollisionScan.capture(wv, x, y, x + 8, y + 8, objects.blockers);
			if (scan != null) scans.add(scan);
		}
		if (!scans.isEmpty()) submit(scans);
	}
	synchronized void submit(List<ChartPlotterCollisionScan> scans) {
		ScheduledExecutorService ex = io;
		if (ex == null) return;
		long scene = generation;
		Map<Long, Long> versions = new HashMap<>();
		for (ChartPlotterCollisionScan scan : scans) for (int x = scan.baseX >> 3; x <= (scan.baseX + scan.width - 1) >> 3; x++) for (int y = scan.baseY >> 3; y <= (scan.baseY + scan.height - 1) >> 3; y++) {
			long key = ChartPlotterCollisionData.key(x, y);
			if (dirty.remove(key)) versions.put(key, pending.get(key));
		}
		try {ex.execute(() -> merge(ex, scene, versions, scans));} catch (RuntimeException ignored) {}
	}
	public ChartPlotterCollisionData snapshot() {return published;}
	public boolean refreshing() {return capturePending || published.pending();}
	public long rev() {return published.rev;}
	public synchronized boolean publish(ChartPlotterCollisionData expected, BooleanSupplier update) {return snapshot() == expected && update.getAsBoolean();}
	void merge(ScheduledExecutorService ex, long scene, Map<Long, Long> versions, List<ChartPlotterCollisionScan> scans) {
		synchronized (fileLock) {
			if (!loaded || io != ex || generation != scene) return;
			Map<Long, Builder> recorded = new HashMap<>();
			Map<Long, Builder> current = new HashMap<>();
			for (ChartPlotterCollisionScan scan : scans) {
				if (io != ex || generation != scene) return;
				for (int sx = 0; sx < scan.width; sx++) for (int sy = 0; sy < scan.height; sy++) {
					int f = scan.flags[sx * scan.height + sy];
					int x = scan.baseX + sx;
					int y = scan.baseY + sy;
					if (f != VOID) put(recorded, x, y, f);
					put(current, x, y, f);
				}
				for (int i = 0; i < scan.objects.length; i += 4) putObject(current, scan, i);
			}
			if (io != ex || generation != scene) return;
			if (merge(recorded)) {
				rev++;
				scheduleFlush(ex, 30);
			}
			boolean changedScene = liveScene != scene;
			if (changedScene) {live.clear(); liveScene = scene;}
			ChartPlotterCollisionData previousView = view;
			Map<Long, Chunk> changes = new HashMap<>();
			for (Map.Entry<Long, Builder> entry : current.entrySet()) {
				long key = entry.getKey();
				Chunk previous = live.getOrDefault(key, chunks.get(key));
				Chunk next = entry.getValue().chunk(previous);
				live.put(key, next);
				if (!changedScene && previousView.chunk((int) (key >> 32), (int) key) != (next.empty() ? null : next)) changes.put(key, next);
			}
			if (changedScene) publish(ex, scene, versions);
			else publish(ex, scene, versions, changes.isEmpty() ? previousView : new ChartPlotterCollisionData(previousView, changes));
		}
	}
	private void publish(ScheduledExecutorService ex, long scene, Map<Long, Long> versions) {
		Map<Long, Chunk> combined = new HashMap<>(chunks);
		if (liveScene == scene) combined.putAll(live);
		ChartPlotterCollisionData next = new ChartPlotterCollisionData(combined);
		publish(ex, scene, versions, next);
	}
	private synchronized void publish(ScheduledExecutorService ex, long scene, Map<Long, Long> versions, ChartPlotterCollisionData next) {
		if (io != ex || generation != scene) return;
		for (Map.Entry<Long, Long> entry : versions.entrySet()) pending.remove(entry.getKey(), entry.getValue());
		view = new ChartPlotterCollisionData(next, Set.of(), ++publication, scene);
		published = pending.isEmpty() ? view : new ChartPlotterCollisionData(view, pending.keySet(), publication, scene);
	}
	private static void putObject(Map<Long, Builder> data, ChartPlotterCollisionScan scan, int i) {
		for (int sx = scan.objects[i]; sx <= scan.objects[i + 2]; sx++) {
			for (int sy = scan.objects[i + 1]; sy <= scan.objects[i + 3]; sy++) {
				put(data, scan.baseX + sx, scan.baseY + sy, BLOCKED);
			}
		}
	}
	private static void put(Map<Long, Builder> data, int wx, int wy, int f) {
		f = clean(f);
		int cx = wx >> 3;
		int cy = wy >> 3;
		long k = ChartPlotterCollisionData.key(cx, cy);
		int i = (wx & 7) + ((wy & 7) << 3);
		Builder b = data.computeIfAbsent(k, k1 -> new Builder());
		b.put(i, f);
	}
	private boolean merge(Map<Long, Builder> data) {
		boolean changed = false;
		for (Map.Entry<Long, Builder> e : data.entrySet()) {
			Chunk old = chunks.get(e.getKey());
			Chunk c = e.getValue().chunk(old);
			if (same(old, c)) continue;
			chunks.put(e.getKey(), c);
			changed = true;
		}
		return changed;
	}
	private static boolean same(Chunk a, Chunk b) {
		return a == b || a != null && b != null && a.known == b.known && a.blocked == b.blocked;
	}
	private void loadQuiet(ScheduledExecutorService ex) {
		synchronized (fileLock) {
			if (io != ex) return;
			try {
				load(ex);
			} catch (Exception ignored) {
			}
		}
	}
	private void load(ScheduledExecutorService ex) {
		BooleanSupplier cancel = () -> io != ex;
		File f = file();
		String defaultVersion = defaultVersion(cancel);
		if (cancel.getAsBoolean()) return;
		boolean replace = defaultVersion != null && (!f.isFile() || ChartPlotterVersions.newer(defaultVersion, ChartPlotterVersions.read(dir, KEY)));
		ChartPlotterCollisionCodec.Text seed = replace ? defaults(cancel) : null;
		Map<Long, Chunk> data = seed == null ? ChartPlotterCollisionCodec.read(f, cancel) : seed.data;
		if (cancel.getAsBoolean()) return;
		if (data.isEmpty() && defaultVersion != null && !replace) {
			seed = defaults(cancel);
			if (seed != null) {
				replace = true;
				data = seed.data;
			}
		}
		if (io != ex || loaded) return;
		chunks.clear();
		chunks.putAll(data);
		synchronized (this) {
			if (io != ex || loaded) return;
			long r = ++rev;
			savedRev = replace ? r - 1 : r;
			seedVersion = replace && seed != null ? seed.version : null;
			loaded = true;
		}
		publish(ex, generation, Map.of());
		if (replace && seed != null && !flush(ex)) synchronized (this) {if (io == ex) scheduleFlush(ex, 30);}
	}
	private String defaultVersion(BooleanSupplier cancel) {
		try (InputStream in = ChartPlotterCollisionCache.class.getResourceAsStream("/com/chartplotter/collision.txt")) {
			return in == null ? null : ChartPlotterCollisionCodec.readVersion(in, cancel);
		} catch (Exception ignored) {
			return null;
		}
	}
	private ChartPlotterCollisionCodec.Text defaults(BooleanSupplier cancel) {
		try (InputStream in = ChartPlotterCollisionCache.class.getResourceAsStream("/com/chartplotter/collision.txt")) {
			return in == null ? null : ChartPlotterCollisionCodec.readText(in, cancel);
		} catch (Exception ignored) {
			return null;
		}
	}
	private synchronized void scheduleFlush(ScheduledExecutorService ex, int delay) {
		if (io != ex || flushTask != null && !flushTask.isDone()) return;
		try {flushTask = ex.schedule(() -> flushQuiet(ex), delay, TimeUnit.SECONDS);} catch (RuntimeException ignored) {flushTask = null;}
	}
	private void flushQuiet(ScheduledExecutorService ex) {
		try {
			flush(ex);
		} catch (Exception ignored) {
		}
		synchronized (this) {
			if (io != ex) return;
			flushTask = null;
			if (savedRev != rev) scheduleFlush(ex, 30);
		}
	}
	private boolean flush(ScheduledExecutorService ex) {
		synchronized (fileLock) {
			if (io != ex) return false;
			long save = rev;
			if (save == savedRev) return true;
			ChartPlotterCollisionData out = new ChartPlotterCollisionData(chunks, save);
			if (ChartPlotterCollisionCodec.write(dir, file(), out, () -> io != ex)) {
				if (io != ex || seedVersion != null && !ChartPlotterVersions.write(dir, KEY, seedVersion)) return false;
				synchronized (this) {
					if (io != ex) return false;
					if (savedRev < save) savedRev = save;
					seedVersion = null;
				}
				return true;
			}
			return false;
		}
	}
	private File file() {return new File(dir, "collision.bin");}
	private static int clean(int f) {
		return f == VOID || f == UNKNOWN ? UNKNOWN : (f & MOVE) == 0 ? OPEN : BLOCKED;
	}
	private static final class Builder {
		long present;
		long known;
		long blocked;
		private Builder() {}
		void put(int i, int f) {
			long bit = 1L << i;
			present |= bit;
			if (f == UNKNOWN) known &= ~bit;
			else known |= bit;
			if (f == BLOCKED) blocked |= bit;
			else blocked &= ~bit;
		}
		Chunk chunk(Chunk base) {
			long nextKnown = base == null ? known : base.known & ~present | known;
			long nextBlocked = (base == null ? blocked : base.blocked & ~present | blocked) & nextKnown;
			return base != null && base.known == nextKnown && base.blocked == nextBlocked ? base : new Chunk(nextKnown, nextBlocked);
		}
	}
}

package com.chartplotter.collision;

import com.chartplotter.collision.ChartPlotterCollisionData.Chunk;
import com.chartplotter.util.ChartPlotterFiles;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;
import java.util.function.BooleanSupplier;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;

public final class ChartPlotterCollisionCodec {
	private static final byte VERSION = 1;
	private static final int USHORT = 0xffff;
	private ChartPlotterCollisionCodec() {}
	public static Map<Long, Chunk> read(File file, BooleanSupplier cancel) {
		Map<Long, Chunk> data = new HashMap<>();
		if (cancel.getAsBoolean() || !file.isFile()) return data;
		try (DataInputStream in = new DataInputStream(new GZIPInputStream(new BufferedInputStream(new FileInputStream(file))))) {
			if (in.readByte() != VERSION) return data;
			int n = in.readInt();
			if (n < 0) return data;
			for (int i = 0; i < n; i++) {
				if ((i & 1023) == 0 && cancel.getAsBoolean()) return new HashMap<>();
				int cx = in.readUnsignedShort();
				int cy = in.readUnsignedShort();
				long mask = in.readLong();
				long blocked = in.readLong();
				if (mask != 0 && data.put(ChartPlotterCollisionData.key(cx, cy), new Chunk(mask, blocked & mask)) != null) return new HashMap<>();
			}
			if (in.read() != -1) return new HashMap<>();
		} catch (Exception ignored) {
			return new HashMap<>();
		}
		return cancel.getAsBoolean() ? new HashMap<>() : data;
	}
	public static Text readText(InputStream src, BooleanSupplier cancel) {
		Map<Long, Chunk> data = new HashMap<>();
		String version = null;
		try (BufferedReader in = new BufferedReader(new InputStreamReader(src, StandardCharsets.UTF_8))) {
			if (cancel.getAsBoolean()) return null;
			String s;
			while ((s = in.readLine()) != null) {
				if (cancel.getAsBoolean()) return null;
				StringTokenizer p = new StringTokenizer(s);
				int n = p.countTokens();
				if (n == 0) continue;
				if (version == null) {
					if (n != 2 || !"data".equals(p.nextToken())) return null;
					version = p.nextToken();
					continue;
				}
				if (n != 3 && n != 4) return null;
				int cx = Integer.parseInt(p.nextToken());
				int cy = Integer.parseInt(p.nextToken());
				if (cx < 0 || cx > USHORT || cy < 0 || cy > USHORT) return null;
				long known = n == 3 ? -1L : Long.parseUnsignedLong(p.nextToken(), 16);
				long blocked = Long.parseUnsignedLong(p.nextToken(), 16);
				if (known == 0L) continue;
				if (data.put(ChartPlotterCollisionData.key(cx, cy), new Chunk(known, blocked & known)) != null) return null;
			}
		} catch (Exception ignored) {
			return null;
		}
		return version == null || cancel.getAsBoolean() ? null : new Text(data, version);
	}
	public static String readVersion(InputStream src, BooleanSupplier cancel) {
		try (BufferedReader in = new BufferedReader(new InputStreamReader(src, StandardCharsets.UTF_8))) {
			if (cancel.getAsBoolean()) return null;
			String s;
			while ((s = in.readLine()) != null) {
				if (cancel.getAsBoolean()) return null;
				StringTokenizer p = new StringTokenizer(s);
				if (p.countTokens() == 2 && "data".equals(p.nextToken())) return p.nextToken();
			}
		} catch (Exception ignored) {
		}
		return null;
	}
	public static boolean write(File dir, File file, ChartPlotterCollisionData data, BooleanSupplier cancel) {
		if (cancel.getAsBoolean()) return false;
		File tmp = new File(dir, "collision.bin.tmp");
		try {
			Files.createDirectories(dir.toPath());
			try (DataOutputStream out = new DataOutputStream(new GZIPOutputStream(new BufferedOutputStream(new FileOutputStream(tmp))))) {
				out.writeByte(VERSION);
				out.writeInt(data.size());
				for (int i = 0; i < data.capacity(); i++) {
					if (cancel.getAsBoolean()) return false;
					Chunk c = data.chunkAt(i);
					if (c == null) continue;
					long key = data.keyAt(i);
					int cx = (int) (key >> 32);
					int cy = (int) key;
					if (cx < 0 || cx > USHORT || cy < 0 || cy > USHORT) return false;
					out.writeShort(cx);
					out.writeShort(cy);
					out.writeLong(c.known);
					out.writeLong(c.blocked);
				}
			}
			return !cancel.getAsBoolean() && ChartPlotterFiles.replace(tmp, file);
		} catch (Exception ignored) {
			return false;
		} finally {
			try {Files.deleteIfExists(tmp.toPath());} catch (IOException ignored) {}
		}
	}
	public static final class Text {
		public final Map<Long, Chunk> data;
		public final String version;
		private Text(Map<Long, Chunk> data, String version) {
			this.data = data;
			this.version = version;
		}
	}
}

package com.chartplotter.collision;

import net.runelite.api.CollisionDataFlag;

import java.util.Map;
import java.util.Set;

public final class ChartPlotterCollisionData {
	public static final int UNKNOWN = -1;
	public static final int OPEN = 0;
	public static final int BLOCKED = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
	public static final int VOID = 0xffffff;
	public static final int MOVE = CollisionDataFlag.BLOCK_MOVEMENT_FULL | CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST | CollisionDataFlag.BLOCK_MOVEMENT_NORTH | CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST | CollisionDataFlag.BLOCK_MOVEMENT_EAST | CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST | CollisionDataFlag.BLOCK_MOVEMENT_SOUTH | CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST | CollisionDataFlag.BLOCK_MOVEMENT_WEST | CollisionDataFlag.BLOCK_MOVEMENT_OBJECT | CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION | CollisionDataFlag.BLOCK_MOVEMENT_FLOOR;
	private final long[] keys;
	private final Chunk[] chunks;
	private final int mask;
	private final int size;
	public final long rev;
	public final long scene;
	private final Set<Long> pending;
	public ChartPlotterCollisionData(Map<Long, Chunk> base) {
		this(base, 0);
	}
	public ChartPlotterCollisionData(Map<Long, Chunk> base, long rev) {
		this(base, rev, 0);
	}
	public ChartPlotterCollisionData(Map<Long, Chunk> base, long rev, long scene) {
		int capacity = 1;
		while (capacity < base.size() * 2) capacity <<= 1;
		keys = new long[capacity];
		chunks = new Chunk[capacity];
		mask = capacity - 1;
		int size = 0;
		for (Map.Entry<Long, Chunk> entry : base.entrySet()) {
			if (entry.getValue() == null || entry.getValue().empty()) continue;
			put(entry.getKey(), entry.getValue());
			size++;
		}
		this.size = size;
		this.rev = rev;
		this.scene = scene;
		pending = Set.of();
	}
	ChartPlotterCollisionData(ChartPlotterCollisionData base, Set<Long> pending, long rev, long scene) {
		keys = base.keys;
		chunks = base.chunks;
		mask = base.mask;
		size = base.size;
		this.pending = Set.copyOf(pending);
		this.rev = rev;
		this.scene = scene;
	}
	ChartPlotterCollisionData(ChartPlotterCollisionData base, Map<Long, Chunk> changes) {
		int size = base.size;
		for (Map.Entry<Long, Chunk> entry : changes.entrySet()) {
			long key = entry.getKey();
			if (base.chunks[base.index(key)] != null) size--;
			if (entry.getValue() != null && !entry.getValue().empty()) size++;
		}
		int capacity = base.chunks.length;
		while (capacity < size * 2) capacity <<= 1;
		mask = capacity - 1;
		keys = capacity == base.keys.length ? base.keys.clone() : new long[capacity];
		chunks = capacity == base.chunks.length ? base.chunks.clone() : new Chunk[capacity];
		if (capacity != base.chunks.length) for (int i = 0; i < base.chunks.length; i++) if (base.chunks[i] != null) put(base.keys[i], base.chunks[i]);
		for (Map.Entry<Long, Chunk> entry : changes.entrySet()) {
			if (entry.getValue() != null && !entry.getValue().empty()) continue;
			int i = index(entry.getKey());
			if (chunks[i] == null) continue;
			chunks[i] = null;
			for (i = i + 1 & mask; chunks[i] != null; i = i + 1 & mask) {
				Chunk chunk = chunks[i];
				chunks[i] = null;
				put(keys[i], chunk);
			}
		}
		for (Map.Entry<Long, Chunk> entry : changes.entrySet()) if (entry.getValue() != null && !entry.getValue().empty()) put(entry.getKey(), entry.getValue());
		this.size = size;
		rev = base.rev;
		scene = base.scene;
		pending = Set.of();
	}
	public Chunk chunk(int x, int y) {
		long key = key(x, y);
		if (!pending.isEmpty() && pending.contains(key)) return null;
		return chunks[index(key)];
	}
	public int flagAt(int x, int y) {
		Chunk c = chunk(x >> 3, y >> 3);
		return c == null ? UNKNOWN : c.flag((x & 7) + ((y & 7) << 3));
	}
	public boolean clear(double ax, double ay, double bx, double by) {
		int x = (int) Math.floor(ax);
		int y = (int) Math.floor(ay);
		if (ax == x && flagAt(x - 1, y) != OPEN || ay == y && flagAt(x, y - 1) != OPEN || ax == x && ay == y && flagAt(x - 1, y - 1) != OPEN) return false;
		int dx = Double.compare(bx, ax);
		int dy = Double.compare(by, ay);
		double stepX = dx == 0 ? Double.POSITIVE_INFINITY : 1 / Math.abs(bx - ax);
		double stepY = dy == 0 ? Double.POSITIVE_INFINITY : 1 / Math.abs(by - ay);
		double nextX = dx == 0 ? Double.POSITIVE_INFINITY : (dx > 0 ? x + 1 - ax : ax - x) * stepX;
		double nextY = dy == 0 ? Double.POSITIVE_INFINITY : (dy > 0 ? y + 1 - ay : ay - y) * stepY;
		while (true) {
			if (flagAt(x, y) != OPEN) return false;
			if (dx == 0 && ax == x && flagAt(x - 1, y) != OPEN || dy == 0 && ay == y && flagAt(x, y - 1) != OPEN) return false;
			if (Math.min(nextX, nextY) > 1) {
				x = (int) Math.floor(bx);
				y = (int) Math.floor(by);
				return flagAt(x, y) == OPEN && (bx != x || flagAt(x - 1, y) == OPEN) && (by != y || flagAt(x, y - 1) == OPEN) && (bx != x || by != y || flagAt(x - 1, y - 1) == OPEN);
			}
			if (Math.abs(nextX - nextY) <= 1e-12) {
				if (flagAt(x + dx, y) != OPEN || flagAt(x, y + dy) != OPEN) return false;
				x += dx;
				y += dy;
				nextX += stepX;
				nextY += stepY;
			} else if (nextX < nextY) {
				x += dx;
				nextX += stepX;
			} else {
				y += dy;
				nextY += stepY;
			}
		}
	}
	public boolean uncached(int x, int y) {
		Chunk c = chunk(x, y);
		return c == null || c.empty();
	}
	public int size() {return size;}
	public boolean pending() {return !pending.isEmpty();}
	public int capacity() {return chunks.length;}
	public long keyAt(int i) {return keys[i];}
	public Chunk chunkAt(int i) {return !pending.isEmpty() && pending.contains(keys[i]) ? null : chunks[i];}
	public static long key(int x, int y) {return (long) x << 32 ^ y & 0xffffffffL;}
	private void put(long key, Chunk chunk) {
		int i = index(key);
		keys[i] = key;
		chunks[i] = chunk;
	}
	private int index(long key) {
		int i = hash(key) & mask;
		while (chunks[i] != null && keys[i] != key) i = i + 1 & mask;
		return i;
	}
	private static int hash(long x) {
		x += 0x9e3779b97f4a7c15L;
		x = (x ^ x >>> 30) * -4658895280553007687L;
		x = (x ^ x >>> 27) * -7723592293110705685L;
		return (int) (x ^ x >>> 31);
	}
	public static final class Chunk {
		public final long known;
		public final long blocked;
		public Chunk(long known, long blocked) {
			this.known = known;
			this.blocked = blocked;
		}
		public int flag(int i) {
			long b = 1L << i;
			return (known & b) == 0 ? UNKNOWN : (blocked & b) == 0 ? OPEN : BLOCKED;
		}
		public boolean empty() {return known == 0;}
	}
}

package com.chartplotter.collision;

import net.runelite.api.*;
import net.runelite.api.gameval.ObjectID;

import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;

public final class ChartPlotterCollisionObjects {
	private static final int[] BLOCKED_IDS = {
		ObjectID.SAILING_FETID_POOL,
		ObjectID.SAILING_FETID_POOL_2X2,
		ObjectID.SAILING_FETID_POOL_3X3A,
		ObjectID.SAILING_FETID_POOL_3X3B,
		ObjectID.SAILING_FETID_POOL_3X3C
	};
	final Set<GameObject> blockers = Collections.newSetFromMap(new IdentityHashMap<>());
	void seed(WorldView view) {
		blockers.clear();
		Scene scene = view.getScene();
		Tile[][][] tiles = scene == null ? null : scene.getExtendedTiles();
		int plane = view.getPlane();
		if (tiles == null || plane < 0 || plane >= tiles.length || tiles[plane] == null) return;
		for (Tile[] row : tiles[plane]) {
			if (row == null) continue;
			for (Tile tile : row) {
				if (tile == null || tile.getGameObjects() == null) continue;
				for (GameObject object : tile.getGameObjects()) changed(object, true);
			}
		}
	}
	void changed(TileObject object, boolean spawned) {
		if (!(object instanceof GameObject) || !blocked(object.getId())) return;
		if (spawned) blockers.add((GameObject) object);
		else blockers.remove(object);
	}
	private static boolean blocked(int id) {
		for (int block : BLOCKED_IDS) if (block == id) return true;
		return false;
	}
}

package com.chartplotter.collision;

import net.runelite.api.CollisionData;
import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.api.WorldView;

import java.util.Arrays;
import java.util.Collection;

public final class ChartPlotterCollisionScan {
	static final int EDGE = 8;
	private static final int[] EMPTY_OBJECTS = new int[0];
	static boolean ready(WorldView view) {
		if (view == null || view.isInstance() || view.getPlane() != 0) return false;
		CollisionData[] maps = view.getCollisionMaps();
		if (maps == null || maps.length == 0 || maps[0] == null) return false;
		int[][] flags = maps[0].getFlags();
		return flags != null && flags.length > EDGE * 2 && flags[0] != null && flags[0].length > EDGE * 2;
	}
	final int baseX;
	final int baseY;
	final int width;
	final int height;
	final int[] flags;
	final int[] objects;
	ChartPlotterCollisionScan(int baseX, int baseY, int width, int height, int[] flags, int[] objects) {
		this.baseX = baseX;
		this.baseY = baseY;
		this.width = width;
		this.height = height;
		this.flags = flags;
		this.objects = objects;
	}
	static ChartPlotterCollisionScan capture(WorldView wv, int minX, int minY, int maxX, int maxY, Collection<GameObject> blockers) {
		if (wv == null || wv.isInstance() || wv.getPlane() != 0) return null;
		CollisionData[] maps = wv.getCollisionMaps();
		if (maps == null || maps.length == 0 || maps[0] == null) return null;
		int[][] flags = maps[0].getFlags();
		if (flags == null || flags.length == 0 || flags[0] == null) return null;
		minX = Math.max(EDGE, minX);
		minY = Math.max(EDGE, minY);
		maxX = Math.min(flags.length - EDGE, maxX);
		maxY = Math.min(flags[0].length - EDGE, maxY);
		int width = maxX - minX;
		int height = maxY - minY;
		if (width <= 0 || height <= 0) return null;
		int[] copy = new int[width * height];
		for (int x = minX; x < maxX; x++) for (int y = minY; y < maxY; y++) copy[(x - minX) * height + y - minY] = flags[x] == null || y >= flags[x].length ? ChartPlotterCollisionData.VOID : flags[x][y];
		int[] objects = blockers.isEmpty() ? EMPTY_OBJECTS : new int[blockers.size() * 4];
		int n = 0;
		for (GameObject object : blockers) {
			Point min = object.getSceneMinLocation();
			Point max = object.getSceneMaxLocation();
			if (min == null || max == null || max.getX() < minX || max.getY() < minY || min.getX() >= maxX || min.getY() >= maxY) continue;
			objects[n++] = Math.max(minX, min.getX()) - minX;
			objects[n++] = Math.max(minY, min.getY()) - minY;
			objects[n++] = Math.min(maxX - 1, max.getX()) - minX;
			objects[n++] = Math.min(maxY - 1, max.getY()) - minY;
		}
		return new ChartPlotterCollisionScan(wv.getBaseX() + minX, wv.getBaseY() + minY, width, height, copy, n == 0 ? EMPTY_OBJECTS : n == objects.length ? objects : Arrays.copyOf(objects, n));
	}
}

package com.chartplotter.collision;
import net.runelite.api.WorldEntityConfig;
import java.util.function.IntBinaryOperator;
public final class ChartPlotterHull {
	public final double ox;
	public final double oy;
	public final double hw;
	public final double hh;
	public final double reach;
	public final double margin;
	public final double rotationPadding;
	public final double turnRadius;
	public ChartPlotterHull(WorldEntityConfig config) {
		ox = config == null ? 0 : config.getBoundsX() / 128.0;
		oy = config == null ? 0 : config.getBoundsY() / 128.0;
		hw = config == null ? 0 : config.getBoundsWidth() / 256.0;
		hh = config == null ? 0 : config.getBoundsHeight() / 256.0;
		reach = Math.hypot(Math.abs(ox) + hw, Math.abs(oy) + hh);
		margin = config == null ? 1e-5 : 2 / 128.0 + 2 * reach / 65536;
		rotationPadding = 2 * reach * Math.sin(Math.PI / 256) + 1e-5;
		turnRadius = reach + Math.sqrt(2) * (margin + rotationPadding);
		if (hw < 0 || hh < 0 || reach > 64) throw new IllegalArgumentException("Unsupported boat footprint");
	}
	public boolean matches(WorldEntityConfig config) {return config == null ? hw == 0 && hh == 0 : ox == config.getBoundsX() / 128.0 && oy == config.getBoundsY() / 128.0 && hw == config.getBoundsWidth() / 256.0 && hh == config.getBoundsHeight() / 256.0;}
	public int pose(ChartPlotterCollisionData data, double x, double y, int orientation) {return tiles(orientation, x, y, 0, 0, 0, data::flagAt);}
	public boolean recedes(double ax, double ay, int from, double bx, double by, int to, int tx, int ty) {
		double angle = (from & 2047) * Math.PI / 1024;
		double cos = Math.cos(angle);
		double sin = Math.sin(angle);
		double rx = tx + 0.5 - ax - cos * ox - sin * oy;
		double ry = ty + 0.5 - ay - cos * oy + sin * ox;
		double w = hw + margin;
		double h = hh + margin;
		double ex = Math.abs(cos) * w + Math.abs(sin) * h + 0.5;
		double ey = Math.abs(sin) * w + Math.abs(cos) * h + 0.5;
		double tileExtent = (Math.abs(cos) + Math.abs(sin)) / 2;
		double depth = Math.min(Math.min(ex - Math.abs(rx), ey - Math.abs(ry)), Math.min(w + tileExtent - Math.abs(rx * cos - ry * sin), h + tileExtent - Math.abs(rx * sin + ry * cos)));
		if (depth <= 0) return false;
		double turn = ((to - from + 1024 & 2047) - 1024) * Math.PI / 1024;
		for (int axis = 0; axis < 4; axis++) {
			double nx = axis == 0 ? 1 : axis == 1 ? 0 : axis == 2 ? cos : sin;
			double ny = axis == 0 ? 0 : axis == 1 ? 1 : axis == 2 ? -sin : cos;
			double distance = nx * rx + ny * ry;
			double extent = axis == 0 ? ex : axis == 1 ? ey : axis == 2 ? w + tileExtent : h + tileExtent;
			if (extent - Math.abs(distance) > depth + 1e-9) continue;
			for (int sign = -1; sign <= 1; sign += 2) if (sign * distance >= 0 && recedes(angle, turn, nx * sign, ny * sign, bx - ax, by - ay)) return true;
		}
		return false;
	}
	private boolean recedes(double angle, double turn, double nx, double ny, double dx, double dy) {
		double move = nx * dx + ny * dy;
		if (turn == 0) return move <= 1e-9;
		double cos = Math.cos(angle);
		double sin = Math.sin(angle);
		double u = nx * cos - ny * sin;
		double v = nx * sin + ny * cos;
		double limit = u * ox + v * oy + Math.abs(u) * (hw + margin) + Math.abs(v) * (hh + margin) + 1e-9;
		double endCos = Math.cos(angle + turn);
		double endSin = Math.sin(angle + turn);
		for (int i = 0; i < 4; i++) {
			double x = ox + (i < 2 ? hw + margin : -hw - margin);
			double y = oy + ((i & 1) == 0 ? hh + margin : -hh - margin);
			double a = nx * x + ny * y;
			double b = nx * y - ny * x;
			if (move + a * endCos + b * endSin > limit) return false;
			double rate = move / (turn * Math.hypot(a, b));
			if (Math.abs(rate) > 1) continue;
			double phase = Math.atan2(b, a);
			double root = Math.asin(rate);
			for (int j = 0; j < 2; j++) {
				double t = Math.IEEEremainder(phase + (j == 0 ? root : Math.PI - root) - angle, Math.PI * 2) / turn;
				if (t > 0 && t < 1 && move * t + a * Math.cos(angle + turn * t) + b * Math.sin(angle + turn * t) > limit) return false;
			}
		}
		return true;
	}
	public int sweep(ChartPlotterCollisionData data, double ax, double ay, int from, double bx, double by, int to) {return sweep(ax, ay, from, bx, by, to, data::flagAt);}
	public int sweep(double ax, double ay, int from, double bx, double by, int to, IntBinaryOperator flags) {
		int delta = (to - from + 1024 & 2047) - 1024;
		if (delta == 0) return tiles(from, ax, ay, bx - ax, by - ay, 0, flags);
		if (delta == -1024 && ax == bx && ay == by) return circle(ax, ay, flags);
		if (delta == -1024) delta = 2048;
		int steps = (Math.abs(delta) + 15) / 16;
		boolean unknown = false;
		for (int i = 0; i <= steps; i++) {
			int flag = tiles(from + delta * i / steps, ax, ay, bx - ax, by - ay, rotationPadding, flags);
			if (flag == ChartPlotterCollisionData.BLOCKED) return flag;
			unknown |= flag != ChartPlotterCollisionData.OPEN;
		}
		return unknown ? ChartPlotterCollisionData.UNKNOWN : ChartPlotterCollisionData.OPEN;
	}
	public int circle(double ax, double ay, IntBinaryOperator flags) {
		boolean unknown = false;
		for (int py = (int) Math.floor(ay - turnRadius); py <= (int) Math.floor(ay + turnRadius); py++) for (int px = (int) Math.floor(ax - turnRadius); px <= (int) Math.floor(ax + turnRadius); px++) {
			if (Math.hypot(Math.max(0, Math.max(px - ax, ax - px - 1)), Math.max(0, Math.max(py - ay, ay - py - 1))) > turnRadius) continue;
			int flag = flags.applyAsInt(px, py);
			if (flag == ChartPlotterCollisionData.BLOCKED) return flag;
			unknown |= flag != ChartPlotterCollisionData.OPEN;
		}
		return unknown ? ChartPlotterCollisionData.UNKNOWN : ChartPlotterCollisionData.OPEN;
	}
	public int tiles(int orientation, double ax, double ay, double dx, double dy, double padding, IntBinaryOperator flags) {
		double angle = (orientation & 2047) * Math.PI / 1024;
		double cos = Math.cos(angle);
		double sin = Math.sin(angle);
		double x = ax + cos * ox + sin * oy + dx / 2;
		double y = ay + cos * oy - sin * ox + dy / 2;
		double w = hw + padding + margin;
		double h = hh + padding + margin;
		double ex = Math.abs(cos) * w + Math.abs(sin) * h + Math.abs(dx) / 2;
		double ey = Math.abs(sin) * w + Math.abs(cos) * h + Math.abs(dy) / 2;
		double tileExtent = (Math.abs(cos) + Math.abs(sin)) / 2;
		double eu = w + Math.abs(dx * cos - dy * sin) / 2 + tileExtent;
		double ev = h + Math.abs(dx * sin + dy * cos) / 2 + tileExtent;
		double en = w * Math.abs(-dy * cos - dx * sin) + h * Math.abs(-dy * sin + dx * cos) + (Math.abs(dx) + Math.abs(dy)) / 2;
		boolean unknown = false;
		for (int py = (int) Math.floor(y - ey); py <= (int) Math.floor(y + ey); py++) {
			for (int px = (int) Math.floor(x - ex); px <= (int) Math.floor(x + ex); px++) {
				double rx = px + 0.5 - x;
				double ry = py + 0.5 - y;
				if (Math.abs(rx) >= ex + 0.5 || Math.abs(ry) >= ey + 0.5 || Math.abs(rx * cos - ry * sin) >= eu || Math.abs(rx * sin + ry * cos) >= ev) continue;
				if ((dx != 0 || dy != 0) && Math.abs(-rx * dy + ry * dx) >= en) continue;
				int flag = flags.applyAsInt(px, py);
				if (flag == ChartPlotterCollisionData.BLOCKED) return flag;
				unknown |= flag != ChartPlotterCollisionData.OPEN;
			}
		}
		return unknown ? ChartPlotterCollisionData.UNKNOWN : ChartPlotterCollisionData.OPEN;
	}
}

package com.chartplotter.overlay;

import com.chartplotter.ChartPlotterConfig;
import com.chartplotter.ChartPlotterEtaMode;
import com.chartplotter.ChartPlotterPlugin;
import com.chartplotter.route.ChartPlotterRoute;
import com.chartplotter.route.ChartPlotterRoutes;
import com.chartplotter.route.ChartPlotterTrip;
import com.chartplotter.runtime.ChartPlotterSailing;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.Perspective;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;

import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

public final class ChartPlotterInfoOverlay extends OverlayPanel {
	private final Client client;
	private final ChartPlotterConfig config;
	private final ChartPlotterSailing sailing;
	private final ChartPlotterRoutes routes;
	private Object menuStops;
	private ChartPlotterTrip cachedTrip;
	private long cachedMotion = Long.MIN_VALUE;
	@Inject
	ChartPlotterInfoOverlay(Client client, ChartPlotterPlugin plugin, ChartPlotterConfig config, ChartPlotterSailing sailing, ChartPlotterRoutes routes) {
		super(plugin);
		this.client = client;
		this.config = config;
		this.sailing = sailing;
		this.routes = routes;
		setClearChildren(false);
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
	}
	@Override
	public List<OverlayMenuEntry> getMenuEntries() {
		ChartPlotterTrip trip = routes.trip();
		Object stops = trip.stopKey();
		if (stops != menuStops) {
			menuStops = stops;
			super.getMenuEntries().clear();
			addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "Chart Plotter info");
			if (trip.size() > 1) addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Skip next stop", "Chart Plotter info", e -> {if (routes.trip().stopKey() == stops) routes.remove(0);});
			if (!trip.empty()) addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Clear trip", "Chart Plotter info", e -> routes.clear());
		}
		return super.getMenuEntries();
	}
	@Override
	public Dimension render(Graphics2D g) {
		if (!sailing.boarded() || client.getGameState() != GameState.LOGGED_IN) return null;
		ChartPlotterTrip trip = routes.trip();
		boolean showProgress = config.infoStopProgress() && trip.totalStops() > 1;
		ChartPlotterEtaMode tripMode = config.infoTripEta();
		ChartPlotterEtaMode stopMode = config.infoStopEta();
		ChartPlotterEtaMode turnMode = config.infoTurnEta();
		boolean showTrip = tripMode != ChartPlotterEtaMode.OFF;
		boolean showStop = stopMode != ChartPlotterEtaMode.OFF && (trip.size() > 1 || stopMode != tripMode);
		boolean showTurn = turnMode != ChartPlotterEtaMode.OFF;
		boolean showSpeed = config.infoBoatSpeed();
		if (!showSpeed && (trip.empty() || !showProgress && !showTrip && !showStop && !showTurn)) return null;
		WorldEntity ship = sailing.ship();
		WorldView top = sailing.top();
		LocalPoint loc = ship == null ? null : ship.getLocalLocation();
		if (loc == null || top == null) return null;
		long motion = sailing.motionTime();
		if (trip != cachedTrip || motion != cachedMotion) {
			cachedTrip = trip;
			cachedMotion = motion;
			panelComponent.getChildren().clear();
			panelComponent.getChildren().add(TitleComponent.builder().text("Chart Plotter").build());
			if (!trip.empty()) {
				double bx = top.getBaseX() + loc.getX() / (double) Perspective.LOCAL_TILE_SIZE;
				double by = top.getBaseY() + loc.getY() / (double) Perspective.LOCAL_TILE_SIZE;
				if (showProgress) panelComponent.getChildren().add(LineComponent.builder().left("Stop").right(trip.stopNumber() + " of " + trip.totalStops()).build());
				if (showTrip) panelComponent.getChildren().add(LineComponent.builder().left("Trip ETA").right(eta(trip, bx, by, true, tripMode)).build());
				if (showStop) panelComponent.getChildren().add(LineComponent.builder().left("Next stop").right(eta(trip, bx, by, false, stopMode)).build());
				if (showTurn) {
					ChartPlotterRoutes.Turn turn = ChartPlotterRoutes.turn(trip.active(), bx, by, sailing.reversing() ? -sailing.speed() : sailing.speed(), sailing.accel(), sailing.maxSpeed(), motion);
					panelComponent.getChildren().add(LineComponent.builder().left("Next turn").right(!turn.valid || turn.end ? "-" : sailing.speed() == 0 ? "Stopped" : turnMode.format(turn.ticks)).build());
				}
			}
			if (showSpeed) panelComponent.getChildren().add(LineComponent.builder().left("Speed").right(Double.toString(sailing.speed())).build());
		}
		return super.render(g);
	}
	public void clear() {
		super.getMenuEntries().clear();
		menuStops = null;
		panelComponent.getChildren().clear();
		cachedTrip = null;
		cachedMotion = Long.MIN_VALUE;
	}
	private String eta(ChartPlotterTrip trip, double bx, double by, boolean total, ChartPlotterEtaMode mode) {
		for (int i = 0; i < (total ? trip.size() : 1); i++) {
			ChartPlotterRoute route = trip.route(i);
			if (route == null) return "Charting course";
			if (route.status != ChartPlotterRoute.OK) return route.text();
		}
		if (sailing.speed() == 0) return "Stopped";
		double speed = sailing.averageSpeed();
		if (sailing.reversing() || speed <= 0) return "-";
		return mode.format(trip.distance(bx, by, total ? trip.size() - 1 : 0) / speed);
	}
}

package com.chartplotter.overlay;

import com.chartplotter.ChartPlotterConfig;
import com.chartplotter.ChartPlotterLineMode;
import com.chartplotter.ChartPlotterPlugin;
import com.chartplotter.route.ChartPlotterRoute;
import com.chartplotter.route.ChartPlotterRouteMoves;
import com.chartplotter.route.ChartPlotterTrip;
import com.chartplotter.runtime.ChartPlotterProjection;
import com.chartplotter.util.ChartPlotterMath;
import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;

public class ChartPlotterMinimapOverlay extends Overlay {
	private static final int DIST = 32768;
	private static final float[] DASH = {8, 6};
	private static final int[] ORBS = {InterfaceID.Orbs.HEALTH_BACKING, InterfaceID.Orbs.PRAYER_BACKING, InterfaceID.Orbs.RUNENERGY_BACKING, InterfaceID.Orbs.SPECENERGY_BACKING, InterfaceID.Orbs.ORB_WORLDMAP};
	private final Client client;
	private final ChartPlotterPlugin plugin;
	private final ChartPlotterConfig config;
	private final ChartPlotterProjection projection;
	private final ChartPlotterStrokeCache routeStroke = new ChartPlotterStrokeCache(BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, DASH);
	private volatile Shape clip;
	private ClipKey clipKey;
	private Shape cachedClip;
	private double routeSpeed = Double.NaN;
	private ChartPlotterRouteMoves.Model routeModel;
	private Path2D.Double line;
	private int fadeKey;
	private Color fadeColor;
	@Inject
	ChartPlotterMinimapOverlay(Client client, ChartPlotterPlugin plugin, ChartPlotterConfig config, ChartPlotterProjection projection) {
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.projection = projection;
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
	}
	@Override
	public Dimension render(Graphics2D g) {
		if (!plugin.isSailing()) {
			clip = null;
			return null;
		}
		Widget m = minimap(client);
		if (m == null || m.isHidden()) {
			clip = null;
			return null;
		}
		Shape c = clip(m);
		clip = c;
		WorldView top = plugin.top();
		boolean active = plugin.courseLine(top);
		ChartPlotterLineMode courseMode = config.minimapLineMode();
		ChartPlotterLineMode projectedMode = config.minimapProjectedLineMode();
		boolean showCourse = active && courseMode.on;
		boolean showProjected = active && projectedMode.on;
		boolean showChart = config.minimapChartLine();
		if (!showCourse && !showProjected && !showChart) return null;
		WorldEntity ship = plugin.getShip();
		if (ship == null || top == null) return null;
		LocalPoint anchor = plugin.anchorLoc(ship);
		LocalPoint center = ship.getLocalLocation();
		if (anchor == null || center == null) return null;
		Shape oldClip = g.getClip();
		Stroke oldStroke = g.getStroke();
		g.setClip(c);
		g.setStroke(routeStroke.solid(config.minimapLineWidth()));
		if (showChart) {
			ChartPlotterTrip trip = plugin.trip();
			Color color = config.chartColor();
			ChartPlotterRouteMoves.Model model = routeModel();
			if (trip.size() > 1) drawRoute(g, top, trip.route(1), faded(color), model);
			drawRoute(g, top, trip.active(), color, model);
		}
		if (showCourse || showProjected) {
			int from = plugin.heading(ship);
			int course = plugin.course(ship);
			int mouse = showProjected ? hoverHeading(top, center, m, c) : -1;
			ChartPlotterProjection.Path cur = showCourse ? projection.path(top, ship.getConfig(), anchor, from, course, courseMode.blocked) : null;
			ChartPlotterProjection.Path pot = null;
			if (mouse >= 0) pot = projection.path(top, ship.getConfig(), anchor, from, mouse, projectedMode.blocked);
			int skip = cur != null && pot != null ? ChartPlotterProjection.match(cur, pot) : 0;
			if (cur != null) draw(g, top, cur, config.lineColor(), skip);
			if (pot != null) draw(g, top, pot, config.potentialColor(), 0);
		}
		g.setStroke(oldStroke);
		g.setClip(oldClip);
		return null;
	}
	public boolean overMinimap(Point p) {return p != null && clip != null && clip.contains(p.getX(), p.getY());}
	public void clear() {clip = null;}
	public static int mouseHeading(Client client, LocalPoint anchor, Point mouse) {
		Widget w = minimap(client);
		if (w == null || w.isHidden()) return -1;
		return mouseHeading(client, anchor, mouse, w, clip(client, w));
	}
	private static int mouseHeading(Client client, LocalPoint anchor, Point mouse, Widget w, Shape clip) {
		if (mouse == null || !clip.contains(mouse.getX(), mouse.getY())) return -1;
		Point center = Perspective.localToMinimap(client, anchor, DIST);
		if (center == null) {
			java.awt.Rectangle b = w.getBounds();
			center = new Point((int) b.getCenterX(), (int) b.getCenterY());
		}
		int sx = mouse.getX() - center.getX();
		int sy = mouse.getY() - center.getY();
		if (sx == 0 && sy == 0) return -1;
		int a = client.getCameraYawTarget() & 2047;
		int x = Perspective.COSINE[a] * sx + Perspective.SINE[a] * sy >> 16;
		int y = Perspective.SINE[a] * sx - Perspective.COSINE[a] * sy >> 16;
		double d = Math.toDegrees(Math.atan2(y, x));
		return ChartPlotterMath.norm((int) Math.round((270 - d) / 360 * 16) * 128);
	}
	static Widget minimap(Client client) {
		if (client.isResized()) {
			if (client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1) return client.getWidget(InterfaceID.ToplevelPreEoc.MINIMAP);
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.MINIMAP);
		}
		return client.getWidget(InterfaceID.Toplevel.MINIMAP);
	}
	private void draw(Graphics2D g, WorldView wv, ChartPlotterProjection.Path p, Color color, int skip) {
		if (p.n < 2 || skip >= p.n) return;
		int start = skip > 0 ? skip - 1 : 0;
		int mid = Math.min(p.blockedAt, p.n);
		Stroke old = g.getStroke();
		g.setStroke(routeStroke.solid(config.minimapLineWidth()));
		segment(g, wv, p, color, start, mid);
		if (mid < p.n) segment(g, wv, p, config.blockedColor(), Math.max(start, mid - 1), p.n);
		g.setStroke(old);
	}
	private void segment(Graphics2D g, WorldView wv, ChartPlotterProjection.Path p, Color color, int from, int to) {
		if (line == null) line = new Path2D.Double();
		line.reset();
		boolean have = false;
		for (int i = from; i < to; i++) {
			Point q = Perspective.localToMinimap(client, new LocalPoint(p.x[i], p.y[i], wv), DIST);
			if (q == null) {
				have = false;
				continue;
			}
			if (have) line.lineTo(q.getX(), q.getY());
			else {
				line.moveTo(q.getX(), q.getY());
				have = true;
			}
		}
		g.setColor(color);
		g.draw(line);
	}
	private void drawRoute(Graphics2D g, WorldView wv, ChartPlotterRoute r, Color color, ChartPlotterRouteMoves.Model model) {
		if (r == null || r.status != ChartPlotterRoute.OK || r.n == 0) return;
		Stroke old = g.getStroke();
		Stroke solid = routeStroke.solid(config.minimapLineWidth());
		Stroke dash = routeStroke.dashed(config.minimapLineWidth());
		g.setColor(color);
		for (int i = 1; i < r.n; i++) routeLine(g, wv, r.x[i - 1] + r.offsetX, r.y[i - 1] + r.offsetY, r.x[i] + r.offsetX, r.y[i] + r.offsetY, model, solid, dash);
		for (int i = 1; i < r.departure.length; i++) routeLine(g, wv, r.departureX(i - 1), r.departureY(i - 1), r.departureX(i), r.departureY(i), model, solid, dash);
		for (int i = 1; i < r.connection.length; i++) routeLine(g, wv, r.connectionX(i - 1), r.connectionY(i - 1), r.connectionX(i), r.connectionY(i), model, solid, dash);
		g.setStroke(old);
	}
	private Color faded(Color color) {
		int key = color.getRGB();
		if (fadeColor == null || fadeKey != key) {
			fadeKey = key;
			fadeColor = new Color(color.getRed(), color.getGreen(), color.getBlue(), color.getAlpha() * 3 / 5);
		}
		return fadeColor;
	}
	private void routeLine(Graphics2D g, WorldView wv, double ax, double ay, double bx, double by, ChartPlotterRouteMoves.Model model, Stroke solid, Stroke dash) {
		if (!routeVisible(wv, ax, ay, bx, by)) return;
		Point a = routePoint(wv, ax, ay);
		Point b = routePoint(wv, bx, by);
		if (a == null || b == null) return;
		g.setStroke(ChartPlotterRouteMoves.solid(ax, ay, bx, by, model) ? solid : dash);
		g.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
	}
	private static boolean routeVisible(WorldView wv, double ax, double ay, double bx, double by) {
		int pad = DIST / Perspective.LOCAL_TILE_SIZE + 2;
		int minX = wv.getBaseX() - pad;
		int minY = wv.getBaseY() - pad;
		int maxX = wv.getBaseX() + wv.getSizeX() + pad;
		int maxY = wv.getBaseY() + wv.getSizeY() + pad;
		return Math.max(ax, bx) >= minX && Math.min(ax, bx) <= maxX && Math.max(ay, by) >= minY && Math.min(ay, by) <= maxY;
	}
	private ChartPlotterRouteMoves.Model routeModel() {
		double speed = ChartPlotterRouteMoves.speedBucket(plugin.speed());
		if (Double.doubleToLongBits(speed) != Double.doubleToLongBits(routeSpeed)) {
			routeSpeed = speed;
			routeModel = ChartPlotterRouteMoves.model(speed);
		}
		return routeModel;
	}
	private Point routePoint(WorldView wv, double wx, double wy) {
		int lx = (int) Math.round((wx - wv.getBaseX()) * Perspective.LOCAL_TILE_SIZE);
		int ly = (int) Math.round((wy - wv.getBaseY()) * Perspective.LOCAL_TILE_SIZE);
		return Perspective.localToMinimap(client, new LocalPoint(lx, ly, wv), DIST);
	}
	private int hoverHeading(WorldView wv, LocalPoint anchor, Widget w, Shape clip) {
		Point m = ChartPlotterOverlay.eligibleMouse(client, plugin);
		if (m == null) return -1;
		if (wv.getYellowClickAction() != Constants.CLICK_ACTION_SET_HEADING) return -1;
		return mouseHeading(client, anchor, m, w, clip);
	}
	private Shape clip(Widget minimap) {
		if (clipKey != null && clipKey.same(client, minimap)) return cachedClip;
		ClipKey k = new ClipKey(client, minimap);
		Shape c = clip(client, minimap);
		clipKey = k;
		cachedClip = c;
		return c;
	}
	private static Shape clip(Client client, Widget minimap) {
		java.awt.Rectangle b = minimap.getBounds();
		Area a = ellipse(b, client.isResized() ? 1 : 3);
		for (int id : ORBS) {
			Widget o = client.getWidget(id);
			if (o != null && !o.isHidden()) a.subtract(ellipse(o.getBounds(), 0));
		}
		return a;
	}
	private static Area ellipse(java.awt.Rectangle b, int p) {return new Area(new Ellipse2D.Double(b.getX() - p, b.getY() - p, b.getWidth() + p * 2, b.getHeight() + p * 2));}
	private static final class ClipKey {
		final int[] v;
		private ClipKey(Client client, Widget minimap) {
			v = new int[5 + ORBS.length * 5];
			int i = 0;
			java.awt.Rectangle b = minimap.getBounds();
			v[i++] = b.x;
			v[i++] = b.y;
			v[i++] = b.width;
			v[i++] = b.height;
			v[i++] = client.isResized() ? 1 : 0;
			for (int id : ORBS) {
				Widget w = client.getWidget(id);
				if (w == null || w.isHidden()) {
					v[i++] = 0;
					i += 4;
					continue;
				}
				b = w.getBounds();
				v[i++] = 1;
				v[i++] = b.x;
				v[i++] = b.y;
				v[i++] = b.width;
				v[i++] = b.height;
			}
		}
		boolean same(Client client, Widget minimap) {
			int i = 0;
			java.awt.Rectangle b = minimap.getBounds();
			if (v[i++] != b.x || v[i++] != b.y || v[i++] != b.width || v[i++] != b.height || v[i++] != (client.isResized() ? 1 : 0)) return false;
			for (int id : ORBS) {
				Widget w = client.getWidget(id);
				if (w == null || w.isHidden()) {
					if (v[i] != 0) return false;
					i += 5;
					continue;
				}
				b = w.getBounds();
				if (v[i++] != 1 || v[i++] != b.x || v[i++] != b.y || v[i++] != b.width || v[i++] != b.height) return false;
			}
			return true;
		}
	}
}

package com.chartplotter.overlay;

import com.chartplotter.ChartPlotterCacheOverlay;
import com.chartplotter.ChartPlotterConfig;
