import net.runelite.client.ui.overlay.components.TextComponent;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Stroke;
import java.awt.geom.Path2D;

public class ChartPlotterOverlay extends Overlay {
	private static final int TS = Perspective.LOCAL_TILE_SIZE;
	private static final int TURN = 128;
	private static final double FADE = 0.72;
	private static final double TICK = 0.6;
	private static final float[] DASH = {8, 6};
	private static final Stroke CACHE_STROKE = new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER);
	private static final Color CACHE_EDGE = new Color(0, 210, 120, 150);
	private final Client client;
	private final ChartPlotterPlugin plugin;
	private final ChartPlotterConfig config;
	private final ChartPlotterCollisionCache collisionCache;
	private final ChartPlotterScene scene;
	private final ChartPlotterProjection projection;
	private final ChartPlotterStrokeCache routeStroke = new ChartPlotterStrokeCache(BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, DASH);
	private final float[] z = new float[4];
	private final int[] cx = new int[4];
	private final int[] cy = new int[4];
	private final int[] px = new int[4];
	private final int[] py = new int[4];
	private final Path2D.Double path = new Path2D.Double();
	private final Path2D.Double line = new Path2D.Double();
	private final float[] rx = new float[4];
	private final float[] ry = new float[4];
	private double routeSpeed = Double.NaN;
	private ChartPlotterRouteMoves.Model routeModel;
	private final int[] headingSides = new int[16];
	private final float[] headingX = {0, 0};
	private final float[] headingY = {1000, -1000};
	private final float[] headingZ = {0, 0};
	private final int[] headingCX = new int[2];
	private final int[] headingCY = new int[2];
	private final TextComponent marker = new TextComponent();
	private final java.awt.Point markerPosition = new java.awt.Point();
	private final int[] colorKey = new int[8];
	private final Color[][] colorCache = new Color[colorKey.length][];
	private int colorNext;
	private ChartPlotterRoute turnRoute;
	private long turnBX;
	private long turnBY;
	private long turnSpeed;
	private long turnAccel;
	private long turnMax;
	private long turnMotion = Long.MIN_VALUE;
	private ChartPlotterRoutes.Turn cachedTurn = ChartPlotterRoutes.Turn.NONE;
	private int etaX = Integer.MIN_VALUE;
	private int etaY = Integer.MIN_VALUE;
	private int etaSeconds = -1;
	private boolean etaEnd;
	private long etaTick = Long.MIN_VALUE;
	@Inject
	ChartPlotterOverlay(Client client, ChartPlotterPlugin plugin, ChartPlotterConfig config, ChartPlotterCollisionCache collisionCache, ChartPlotterScene scene, ChartPlotterProjection projection) {
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.collisionCache = collisionCache;
		this.scene = scene;
		this.projection = projection;
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
	}
	@Override
	public Dimension render(Graphics2D g) {
		if (!plugin.isSailing()) return null;
		WorldView top = plugin.top();
		boolean active = plugin.courseLine(top);
		ChartPlotterLineMode courseMode = config.worldLineMode();
		ChartPlotterLineMode projectedMode = config.worldProjectedLineMode();
		boolean showCourse = active && courseMode.on;
		boolean showProjected = active && projectedMode.on;
		boolean showChart = config.worldChartLine();
		boolean showWorld = showCourse || showProjected || showChart;
		ChartPlotterEtaMode turnEta = config.courseTurnEta();
		boolean showTurn = turnEta != ChartPlotterEtaMode.OFF;
		ChartPlotterCacheOverlay cacheOverlay = config.cacheOverlay();
		if (!showWorld && !cacheOverlay.world && !showTurn) return null;
		if (top == null) return null;
		ChartPlotterScene.Area area = scene.cached(top);
		if (cacheOverlay.world) drawCache(g, top, area);
		if (!showWorld && !showTurn) return null;
		WorldEntity ship = plugin.getShip();
		if (ship == null) return null;
		LocalPoint anchor = plugin.anchorLoc(ship);
		LocalPoint center = ship.getLocalLocation();
		if (anchor == null || center == null) return null;
		ChartPlotterTrip trip = showChart || showTurn ? plugin.trip() : null;
		boolean waypointVisible = false;
		if (showWorld) {
			Stroke prev = g.getStroke();
			g.setStroke(routeStroke.solid(config.worldLineWidth()));
			if (showChart) {
				Color color = config.chartColor();
				ChartPlotterRouteMoves.Model model = routeModel();
				if (trip.size() > 1) drawRoute(g, top, trip.route(1), area, faded(color), model);
				drawRoute(g, top, trip.active(), area, color, model);
				if (trip.size() > 1) waypointVisible = drawWaypoint(g, top, area, trip.markerX(0), trip.markerY(0), color);
			}
			if (showCourse || showProjected) {
				WorldEntityConfig wc = ship.getConfig();
				ChartPlotterProjection.rect(wc, rx, ry);
				int from = plugin.heading(ship);
				int course = plugin.course(ship);
				int mouse = showProjected ? hoverHeading(top, center) : -1;
				ChartPlotterProjection.Path cur = showCourse ? projection.path(top, wc, anchor, from, course, courseMode.blocked) : null;
				ChartPlotterProjection.Path pot = mouse >= 0 ? projection.path(top, wc, anchor, from, mouse, projectedMode.blocked) : null;
				int skip = cur != null && pot != null ? ChartPlotterProjection.match(cur, pot) : 0;
				if (cur != null) draw(g, top, area, cur, rx, ry, config.lineColor(), skip);
				if (pot != null) draw(g, top, area, pot, rx, ry, config.potentialColor(), 0);
			}
			g.setStroke(prev);
		}
		if (showTurn) drawNextTurn(g, top, area, center, trip, turnEta, waypointVisible);
		return null;
	}
	public void clear() {
		turnRoute = null;
		cachedTurn = ChartPlotterRoutes.Turn.NONE;
		resetEta();
	}
	private void draw(Graphics2D g, WorldView wv, ChartPlotterScene.Area area, ChartPlotterProjection.Path p, float[] rx, float[] ry, Color color, int skip) {
		int n = p.n;
		if (area != null) for (int i = 0; i < n; i++) if (area.missing(p.x[i], p.y[i])) {n = i; break;}
		if (skip >= n) return;
		Stroke old = g.getStroke();
		g.setStroke(routeStroke.solid(config.worldLineWidth()));
		boolean have = false;
		int sA = color.getAlpha();
		Color blockedColor = config.blockedColor();
		int sBA = blockedColor.getAlpha();
		for (int i = Math.max(0, skip - 1); i < n; i++) {
			if (missing(wv, p, i, rx, ry, z, cx, cy)) {
				have = false;
				continue;
			}
			if (i < skip) {
				copy(cx, cy, px, py);
				have = true;
				continue;
			}
			boolean inBlock = i >= p.blockedAt;
			Color base = inBlock ? blockedColor : color;
			int a = alpha(inBlock ? sBA : sA, i, n);
			if (a > 0) {
				g.setColor(alpha(base, a));
				path.reset();
				outline(path, px, py, cx, cy, have && p.o[i] == p.prev(i), i + 1 < n && p.o[i + 1] == p.o[i], p.reverse);
				g.draw(path);
			}
			copy(cx, cy, px, py);
			have = true;
		}
		g.setStroke(old);
	}
	private void drawNextTurn(Graphics2D g, WorldView wv, ChartPlotterScene.Area area, LocalPoint center, ChartPlotterTrip trip, ChartPlotterEtaMode mode, boolean waypointVisible) {
		if (area == null) return;
		double bx = wv.getBaseX() + center.getX() / (double) TS;
		double by = wv.getBaseY() + center.getY() / (double) TS;
		double speed = plugin.reversing() ? -plugin.speed() : plugin.speed();
		ChartPlotterRoutes.Turn turn = turn(trip.active(), bx, by, speed, plugin.accel(), plugin.maxSpeed(), plugin.motionTime());
		if (!turn.valid) {
			resetEta();
			return;
		}
		if (turn.end && trip.size() > 1 && waypointVisible) return;
		Point at = edge(wv, area, center.getX(), center.getY(), (int) Math.round((turn.x + turn.offsetX - wv.getBaseX()) * TS), (int) Math.round((turn.y + turn.offsetY - wv.getBaseY()) * TS));
		if (at == null) return;
		String p = turn.end ? trip.size() > 1 ? "Waypoint" : "Destination" : "Turn";
		String s;
		if (turn.ticks < 0) {
			resetEta();
			s = p + " ahead";
		} else if (mode == ChartPlotterEtaMode.TICKS) {
			resetEta();
			s = p + " in " + turn.ticks + "t";
		} else s = p + " in " + seconds(turn) + "s";
		drawMarker(g, at, s, config.chartColor());
	}
	private ChartPlotterRoutes.Turn turn(ChartPlotterRoute route, double bx, double by, double speed, double accel, double max, long motion) {
		long x = Double.doubleToLongBits(bx);
		long y = Double.doubleToLongBits(by);
		long s = Double.doubleToLongBits(speed);
		long a = Double.doubleToLongBits(accel);
		long m = Double.doubleToLongBits(max);
		if (route == turnRoute && x == turnBX && y == turnBY && s == turnSpeed && a == turnAccel && m == turnMax && motion == turnMotion) return cachedTurn;
		turnRoute = route;
		turnBX = x;
		turnBY = y;
		turnSpeed = s;
		turnAccel = a;
		turnMax = m;
		turnMotion = motion;
		return cachedTurn = ChartPlotterRoutes.turn(route, bx, by, speed, accel, max, motion);
	}
	private int seconds(ChartPlotterRoutes.Turn turn) {
		if (turn.x != etaX || turn.y != etaY || turn.end != etaEnd || turn.updated != etaTick) {
			etaX = turn.x;
			etaY = turn.y;
			etaSeconds = Math.max(0, (int) Math.ceil(turn.ticks * TICK));
			etaEnd = turn.end;
			etaTick = turn.updated;
		}
		return etaSeconds;
	}
	private void resetEta() {
		etaX = Integer.MIN_VALUE;
		etaY = Integer.MIN_VALUE;
		etaSeconds = -1;
		etaEnd = false;
		etaTick = Long.MIN_VALUE;
	}
	private Point edge(WorldView wv, ChartPlotterScene.Area area, int sx, int sy, int ex, int ey) {
		int ax = ex;
		int ay = ey;
		if (area.missing(ex, ey)) {
			double lo = 0;
			double hi = 1;
			for (int i = 0; i < 16; i++) {
				double mid = (lo + hi) / 2;
				if (area.missing((int) (sx + (ex - sx) * mid), (int) (sy + (ey - sy) * mid))) hi = mid;
				else lo = mid;
			}
			ax = (int) (sx + (ex - sx) * lo);
			ay = (int) (sy + (ey - sy) * lo);
		}
		return Perspective.localToCanvas(client, new LocalPoint(ax, ay, wv), 0);
	}
	private void drawRoute(Graphics2D g, WorldView wv, ChartPlotterRoute r, ChartPlotterScene.Area area, Color color, ChartPlotterRouteMoves.Model model) {
		if (r == null || r.status != ChartPlotterRoute.OK || r.n == 0 || area == null) return;
		Stroke old = g.getStroke();
		Stroke solid = routeStroke.solid(config.worldLineWidth());
		Stroke dash = routeStroke.dashed(config.worldLineWidth());
		g.setColor(color);
		for (int i = 1; i < r.n; i++) routeLine(g, wv, area, r.x[i - 1] + r.offsetX, r.y[i - 1] + r.offsetY, r.x[i] + r.offsetX, r.y[i] + r.offsetY, model, solid, dash);
		for (int i = 1; i < r.departure.length; i++) routeLine(g, wv, area, r.departureX(i - 1), r.departureY(i - 1), r.departureX(i), r.departureY(i), model, solid, dash);
		for (int i = 1; i < r.connection.length; i++) routeLine(g, wv, area, r.connectionX(i - 1), r.connectionY(i - 1), r.connectionX(i), r.connectionY(i), model, solid, dash);
		g.setStroke(old);
	}
	private void routeLine(Graphics2D g, WorldView wv, ChartPlotterScene.Area area, double ax, double ay, double bx, double by, ChartPlotterRouteMoves.Model model, Stroke solid, Stroke dash) {
		line.reset();
		if (!routeSegment(line, wv, area, ax, ay, bx, by)) return;
		g.setStroke(ChartPlotterRouteMoves.solid(ax, ay, bx, by, model) ? solid : dash);
		g.draw(line);
	}
	private ChartPlotterRouteMoves.Model routeModel() {
		double speed = ChartPlotterRouteMoves.speedBucket(plugin.speed());
		if (Double.doubleToLongBits(speed) != Double.doubleToLongBits(routeSpeed)) {
			routeSpeed = speed;
			routeModel = ChartPlotterRouteMoves.model(speed);
		}
		return routeModel;
	}
	private boolean drawWaypoint(Graphics2D g, WorldView wv, ChartPlotterScene.Area area, double wx, double wy, Color color) {
		if (area == null) return false;
		Point point = routeCanvas(wv, area, wx, wy);
		if (point == null) return false;
		drawMarker(g, point, "Waypoint ahead", color);
		return true;
	}
	private void drawMarker(Graphics2D g, Point point, String text, Color color) {
		g.setColor(color);
		g.fillOval(point.getX() - 3, point.getY() - 3, 6, 6);
		marker.setText(text);
		marker.setColor(color);
		markerPosition.setLocation(point.getX() - g.getFontMetrics().stringWidth(text) / 2, point.getY() - 8);
		marker.setPosition(markerPosition);
		marker.render(g);
	}
	private Color faded(Color color) {return alpha(color, color.getAlpha() * 3 / 5);}
	private Color alpha(Color color, int alpha) {
		int key = color.getRGB() & 0xffffff;
		for (int i = 0; i < colorCache.length; i++) {
			Color[] cache = colorCache[i];
			if (cache == null || colorKey[i] != key) continue;
			Color result = cache[alpha];
			if (result == null) cache[alpha] = result = new Color(key | alpha << 24, true);
			return result;
		}
		int i = colorNext++ & colorCache.length - 1;
		colorKey[i] = key;
		Color[] cache = colorCache[i] = new Color[256];
		return cache[alpha] = new Color(key | alpha << 24, true);
	}
	private boolean routeSegment(Path2D.Double line, WorldView wv, ChartPlotterScene.Area area, double ax, double ay, double bx, double by) {
		double dx = bx - ax;
		double dy = by - ay;
		double t0 = 0;
		double t1 = 1;
		double minX = area.minWX();
		double minY = area.minWY();
		double maxX = area.maxWX();
		double maxY = area.maxWY();
		if (dx == 0) {
			if (ax < minX || ax > maxX) return false;
		} else {
			double a = (minX - ax) / dx;
			double b = (maxX - ax) / dx;
			if (a > b) {
				double c = a;
				a = b;
				b = c;
			}
			if (a > t0) t0 = a;
			if (b < t1) t1 = b;
			if (t0 > t1) return false;
		}
		if (dy == 0) {
			if (ay < minY || ay > maxY) return false;
		} else {
			double a = (minY - ay) / dy;
			double b = (maxY - ay) / dy;
			if (a > b) {
				double c = a;
				a = b;
				b = c;
			}
			if (a > t0) t0 = a;
			if (b < t1) t1 = b;
			if (t0 > t1) return false;
		}
		int n = (int) Math.ceil(Math.max(Math.abs(dx), Math.abs(dy)) * (t1 - t0));
		if (n < 1) n = 1;
		boolean have = false;
		boolean drawn = false;
		for (int i = 0; i <= n; i++) {
			double t = t0 + (t1 - t0) * i / n;
			boolean next = routePoint(line, wv, area, ax + dx * t, ay + dy * t, have);
			if (have && next) drawn = true;
			have = next;
		}
		return drawn;
	}
	private boolean routePoint(Path2D.Double line, WorldView wv, ChartPlotterScene.Area area, double wx, double wy, boolean have) {
		Point q = routeCanvas(wv, area, wx, wy);
		if (q == null) return false;
		if (have) line.lineTo(q.getX(), q.getY());
		else {
			line.moveTo(q.getX(), q.getY());
		}
		return true;
	}
	private Point routeCanvas(WorldView wv, ChartPlotterScene.Area area, double wx, double wy) {
		int lx = (int) Math.round((wx - wv.getBaseX()) * TS);
		int ly = (int) Math.round((wy - wv.getBaseY()) * TS);
		if (area.missing(lx, ly)) return null;
		return Perspective.localToCanvas(client, new LocalPoint(lx, ly, wv), 0);
	}
	private void drawCache(Graphics2D g, WorldView wv, ChartPlotterScene.Area area) {
		if (area == null) return;
		Stroke old = g.getStroke();
		ChartPlotterCollisionData data = collisionCache.snapshot();
		g.setStroke(CACHE_STROKE);
		g.setColor(CACHE_EDGE);
		for (int i = 0; i < area.n; i++) {
			int cx = area.cx[i];
			int cy = area.cy[i];
			if (data.uncached(cx, cy)) continue;
			int wx = cx << 3;
			int wy = cy << 3;
			int x0 = Math.max(wx, area.minWX());
			int y0 = Math.max(wy, area.minWY());
			int x1 = Math.min(wx + 8, area.maxWX());
			int y1 = Math.min(wy + 8, area.maxWY());
			if (x0 >= x1 || y0 >= y1) continue;
			drawCacheEdge(g, wv, x0, y0, x0, y1);
			if (area.missingChunk(cx + 1, cy) || data.uncached(cx + 1, cy)) drawCacheEdge(g, wv, x1, y0, x1, y1);
			drawCacheEdge(g, wv, x0, y0, x1, y0);
			if (area.missingChunk(cx, cy + 1) || data.uncached(cx, cy + 1)) drawCacheEdge(g, wv, x0, y1, x1, y1);
		}
		g.setStroke(old);
	}
	private void drawCacheEdge(Graphics2D g, WorldView wv, int ax, int ay, int bx, int by) {
		Point a = cachePoint(wv, ax, ay);
		Point b = cachePoint(wv, bx, by);
		if (a == null || b == null) return;
		g.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
	}
	private Point cachePoint(WorldView wv, int wx, int wy) {
		return Perspective.localToCanvas(client, new LocalPoint((wx - wv.getBaseX()) * TS, (wy - wv.getBaseY()) * TS, wv), 0);
	}
	private boolean missing(WorldView wv, ChartPlotterProjection.Path p, int i, float[] rx, float[] ry, float[] z, int[] cx, int[] cy) {
		Perspective.modelToCanvas(client, wv, 4, p.x[i], p.y[i], 0, p.o[i], rx, ry, z, cx, cy);
		return cx[0] == Integer.MIN_VALUE || cx[1] == Integer.MIN_VALUE || cx[2] == Integer.MIN_VALUE || cx[3] == Integer.MIN_VALUE;
	}
	static void outline(Path2D p, int[] px, int[] py, int[] cx, int[] cy, boolean join, boolean open, boolean reverse) {
		if (!join) {box(p, cx, cy, open, reverse); return;}
		int a = reverse ? 1 : 0;
		int b = reverse ? 2 : 3;
		p.moveTo(px[a], py[a]);
		p.lineTo(cx[a], cy[a]);
		if (open) p.moveTo(cx[b], cy[b]);
		else p.lineTo(cx[b], cy[b]);
		p.lineTo(px[b], py[b]);
	}
	private static void box(Path2D p, int[] x, int[] y, boolean open, boolean reverse) {
		if (open && reverse) {
			p.moveTo(x[0], y[0]);
			p.lineTo(x[1], y[1]);
			p.moveTo(x[2], y[2]);
			p.lineTo(x[3], y[3]);
			p.lineTo(x[0], y[0]);
			return;
		}
		p.moveTo(x[0], y[0]);
		p.lineTo(x[1], y[1]);
		p.lineTo(x[2], y[2]);
		p.lineTo(x[3], y[3]);
		if (!open) p.closePath();
	}
	private static void copy(int[] sx, int[] sy, int[] dx, int[] dy) {
		for (int i = 0; i < 4; i++) {
			dx[i] = sx[i];
			dy[i] = sy[i];
		}
	}
	private static int alpha(int a, int i, int n) {
		double f = (i + 1) / (double) n;
		if (f <= FADE) return a;
		double t = (f - FADE) / (1 - FADE);
		return (int) (a * (1 - t));
	}
	private int hoverHeading(WorldView wv, LocalPoint anchor) {
		Point m = eligibleMouse(client, plugin);
		if (m == null) return -1;
		if (outsideViewport(client, m) || headingInactive(client, wv)) return -1;
		return sceneHeading(client, wv, anchor, m, headingSides, headingX, headingY, headingZ, headingCX, headingCY);
	}
	public static Point eligibleMouse(Client client, ChartPlotterPlugin plugin) {
		Point m = client.getMouseCanvasPosition();
		if (m == null || client.getCanvas().getMousePosition() == null || client.isMenuOpen()) return null;
		return plugin.suppressPotential(m) ? null : m;
	}
	public static boolean headingInactive(Client client, WorldView wv) {
		if (wv.getYellowClickAction() != Constants.CLICK_ACTION_SET_HEADING) return true;
		MenuEntry[] es = client.getMenu().getMenuEntries();
		return es.length == 0 || es[es.length - 1].getType() != MenuAction.SET_HEADING;
	}
	public static boolean outsideViewport(Client client, Point m) {
		int x = client.getViewportXOffset();
		int y = client.getViewportYOffset();
		return m.getX() < x || m.getY() < y || m.getX() >= x + client.getViewportWidth() || m.getY() >= y + client.getViewportHeight();
	}
	public static int mouseHeading(Client client, WorldView wv, LocalPoint anchor, Point mouse) {
		int mini = ChartPlotterMinimapOverlay.mouseHeading(client, anchor, mouse);
		if (mini >= 0) return mini;
		return sceneHeading(client, wv, anchor, mouse);
	}
	private static int sceneHeading(Client client, WorldView wv, LocalPoint anchor, Point mouse) {
		return sceneHeading(client, wv, anchor, mouse, new int[16], new float[]{0, 0}, new float[]{1000, -1000}, new float[]{0, 0}, new int[2], new int[2]);
	}
	private static int sceneHeading(Client client, WorldView wv, LocalPoint anchor, Point mouse, int[] sides, float[] x, float[] y, float[] z, int[] cx, int[] cy) {
		Point center = Perspective.localToCanvas(client, anchor, 0);
		if (center == null || mouse == null) return -1;
		int n = 16;
		for (int i = 0; i < n; i++) {
			cx[0] = 0;
			cx[1] = 0;
			cy[0] = 0;
			cy[1] = 0;
			Perspective.modelToCanvas(client, wv, 2, anchor.getX(), anchor.getY(), 0, 64 + TURN * i, x, y, z, cx, cy);
			sides[i] = headingSide(center, mouse, cx, cy);
			if (sides[i] == Integer.MIN_VALUE) return -1;
		}
		for (int i = 0; i < n - 1; i++) {
			if (sides[i] >= 0 && sides[i + 1] < 0) return TURN + i * TURN;
		}
		return 0;
	}
	static int headingSide(Point center, Point mouse, int[] x, int[] y) {
		int i = x[1] == Integer.MIN_VALUE ? 0 : 1;
		if (x[i] == Integer.MIN_VALUE) return Integer.MIN_VALUE;
		int side = Long.signum(((long) x[i] - center.getX()) * (mouse.getY() - center.getY()) - ((long) y[i] - center.getY()) * (mouse.getX() - center.getX()));
		return i == 0 ? -side : side;
	}
}

package com.chartplotter.overlay;
import java.awt.BasicStroke;
import java.awt.Stroke;
final class ChartPlotterStrokeCache {
	private final int cap;
	private final int join;
	private final float[] dash;
	private int width = Integer.MIN_VALUE;
	private Stroke solid;
	private Stroke dashed;
	ChartPlotterStrokeCache(int cap, int join, float[] dash) {
		this.cap = cap;
		this.join = join;
		this.dash = dash;
	}
	Stroke solid(int w) {
		update(w);
		return solid;
	}
	Stroke dashed(int w) {
		update(w);
		return dashed;
	}
	@SuppressWarnings("MagicConstant")
	private void update(int w) {
		if (w == width) return;
		width = w;
		solid = new BasicStroke(w, cap, join);
		dashed = new BasicStroke(w, cap, join, 10, dash, 0);
	}
}

