	private void draw(Graphics2D g, ChartPlotterWorldMap.State s, int baseX, int baseY, ChartPlotterProjection.Path p, Color color, int skip) {
		if (p.n < 2 || skip >= p.n) return;
		int start = skip > 0 ? skip - 1 : 0;
		int mid = Math.min(p.blockedAt, p.n);
		Stroke old = g.getStroke();
		g.setStroke(routeStroke.solid(config.worldMapLineWidth()));
		segment(g, s, baseX, baseY, p, color, start, mid);
		if (mid < p.n) segment(g, s, baseX, baseY, p, config.blockedColor(), Math.max(start, mid - 1), p.n);
		g.setStroke(old);
	}
	private void segment(Graphics2D g, ChartPlotterWorldMap.State s, int baseX, int baseY, ChartPlotterProjection.Path p, Color color, int from, int to) {
		projectionLine.reset();
		int pad = linePad(s);
		boolean have = false;
		boolean prev = false;
		int plx = 0;
		int ply = 0;
		for (int i = from; i < to; i++) {
			int sx = Math.floorDiv(p.x[i], TS);
			int sy = Math.floorDiv(p.y[i], TS);
			boolean visible = pointVisible(s, baseX + sx, baseY + sy, pad);
			if (!visible && !have) {
				plx = p.x[i];
				ply = p.y[i];
				prev = true;
				continue;
			}
			if (!s.data.surfaceContainsPosition(baseX + sx, baseY + sy)) {
				have = false;
				prev = false;
				continue;
			}
			if (visible) {
				int x = map.mapX(s, baseX, p.x[i]);
				int y = map.mapY(s, baseY, p.y[i]);
				if (have) projectionLine.lineTo(x, y);
				else {
					if (prev && s.data.surfaceContainsPosition(baseX + Math.floorDiv(plx, TS), baseY + Math.floorDiv(ply, TS))) projectionLine.moveTo(map.mapX(s, baseX, plx), map.mapY(s, baseY, ply));
					else projectionLine.moveTo(x, y);
					projectionLine.lineTo(x, y);
					have = true;
				}
			} else {
				projectionLine.lineTo(map.mapX(s, baseX, p.x[i]), map.mapY(s, baseY, p.y[i]));
				have = false;
			}
			plx = p.x[i];
			ply = p.y[i];
			prev = true;
		}
		g.setColor(color);
		g.draw(projectionLine);
	}
	private void drawTrip(Graphics2D g, ChartPlotterWorldMap.State s, Shape clip, ChartPlotterTrip trip, boolean tail) {
		int first = config.infoStopProgress() ? trip.stopNumber() : 1;
		if (stopLabelStart != first) {
			stopLabelStart = first;
			Arrays.fill(stopLabels, null);
		}
		Point mouse = hover(clip);
		int moving = draggedStop >= 0 && draggedStop < trip.size() && trip.x(draggedStop) == draggedX && trip.y(draggedStop) == draggedY ? draggedStop : -1;
		Point drag = draggedPoint;
		int[] moved = moving >= 0 && map.tile(drag, s, tile) ? tile : null;
		boolean movedPoint = moving >= 0 && drag != null;
		int movedPX = !movedPoint ? 0 : moved == null ? drag.getX() : map.pointX(s, moved[0] + 0.5);
		int movedPY = !movedPoint ? 0 : moved == null ? drag.getY() : map.pointY(s, moved[1] + 0.5);
		int remove = moving >= 0 ? -1 : cachedStopIndex(mouse);
		ChartPlotterRouteMoves.Model model = routeModel();
		for (int i = 0; i < trip.size(); i++) {
			ChartPlotterRoute r = trip.route(i);
			if (r == null || r.status != ChartPlotterRoute.OK) continue;
			boolean removing = remove >= 0 && (tail ? i >= remove : i == remove || i == remove + 1);
			drawRoutePath(g, s, r, removing ? REMOVE : routeColor(r, i > 0), model);
		}
		if (movedPoint) {
			Stroke stroke = g.getStroke();
			g.setStroke(routeStroke.dashed(config.worldMapLineWidth()));
			g.setColor(moved == null ? PREVIEW_BAD : PREVIEW_SNAP);
			g.drawLine(map.pointX(s, trip.markerX(moving)), map.pointY(s, trip.markerY(moving)), movedPX, movedPY);
			g.setStroke(stroke);
		}
		long now = System.currentTimeMillis();
		for (int i = 0; i < trip.size(); i++) {
			ChartPlotterRoute r = trip.route(i);
			int px = i == moving && movedPoint ? movedPX : map.pointX(s, trip.markerX(i));
			int py = i == moving && movedPoint ? movedPY : map.pointY(s, trip.markerY(i));
			boolean removing = remove >= 0 && (tail ? i >= remove : i == remove);
			Color c = i == moving ? moved == null ? PREVIEW_BAD : PREVIEW_SNAP : removing ? REMOVE : routeColor(r, i > 0);
			marker(g, px, py, c);
			if (trip.size() > 1 || first > 1) label(g, px, py, i, c);
			if (i != remove && i != moving && r != null && r.text() != null && (r.status == ChartPlotterRoute.PENDING || now - r.time < TIP_MS)) tip(g, s.r, px, py, r.text());
		}
		if (moving >= 0 && movedPoint && config.worldMapTooltips().instructions) tip(g, s.r, movedPX, movedPY, moved == null ? "Release to cancel" : "Release to move stop " + (moving + first));
		else if (remove >= 0) {
			tip(g, s.r, map.pointX(s, trip.markerX(remove)), map.pointY(s, trip.markerY(remove)), tripTip(trip, remove));
		}
	}
	String[] tripTip(ChartPlotterTrip trip, int stop) {
		ChartPlotterMapTooltip mode = config.worldMapTooltips();
		if (mode == ChartPlotterMapTooltip.OFF) {tipTrip = null; return tipLines = null;}
		boolean sailing = plugin.isSailing();
		int first = config.infoStopProgress() ? trip.stopNumber() : 1;
		double bx = Double.NaN;
		double by = Double.NaN;
		double speed = 0;
		if (mode.info && sailing) {
			WorldEntity ship = plugin.getShip();
			WorldView top = plugin.top();
			LocalPoint loc = ship == null ? null : ship.getLocalLocation();
			if (top != null && loc != null) {
				bx = top.getBaseX() + loc.getX() / (double) TS;
				by = top.getBaseY() + loc.getY() / (double) TS;
			}
			speed = plugin.baseSpeed();
		}
		if (tipTrip == trip && tipStop == stop && tipFirst == first && tipMode == mode && tipSailing == sailing && Double.compare(tipX, bx) == 0 && Double.compare(tipY, by) == 0 && Double.compare(tipSpeed, speed) == 0) return tipLines;
		tipTrip = trip;
		tipStop = stop;
		tipFirst = first;
		tipMode = mode;
		tipSailing = sailing;
		tipX = bx;
		tipY = by;
		tipSpeed = speed;
		ChartPlotterRoute route = trip.route(stop);
		String status = route == null ? "Charting course" : route.text();
		if (mode.info) for (int i = 0; i <= stop; i++) {
			ChartPlotterRoute leg = trip.route(i);
			if (leg != null && leg.status == ChartPlotterRoute.OK && !leg.recalculating) continue;
			status = (i < stop ? "Stop " + (i + first) + ": " : "") + (leg == null || leg.recalculating ? "Charting course" : leg.text());
			break;
		}
		int n = stop + first;
		boolean tail = stop + 1 < trip.size();
		boolean append = sailing && !tail && plugin.canAppend();
		int info = status != null ? 1 : mode.info ? 2 : 0;
		String[] lines = new String[info + (mode.instructions ? 1 + (info > 0 ? 1 : 0) + (tail || append ? 1 : 0) + (sailing ? 1 : 0) : 0)];
		int i = 0;
		if (status != null) lines[i++] = status;
		else if (mode.info) {
			double distance = trip.distance(bx, by, stop);
			lines[i++] = "Distance: " + (Double.isFinite(distance) ? (long) Math.ceil(distance) + " tiles" : "-");
			String time = ChartPlotterEtaMode.SECONDS.format(speed > 0 ? distance / speed : Double.NaN);
			lines[i++] = "ETA: " + (time.equals("-") ? time : "~" + time);
		}
		if (mode.instructions) {
			if (i > 0) lines[i++] = "";
			lines[i++] = trip.size() == 1 ? "Click: clear destination" : "Click: remove stop " + n;
			if (tail) lines[i++] = "Shift+click: remove stop " + n + " and later";
			else if (append) lines[i++] = "Shift+click elsewhere: add stop";
			if (sailing) lines[i] = trip.size() == 1 ? "Drag: move destination" : "Drag: move stop " + n;
		}
		return tipLines = lines;
	}
	private Color routeColor(ChartPlotterRoute r, boolean future) {
		Color c = r == null ? STATUS_WARN : r.status == ChartPlotterRoute.OK ? config.chartColor() : r.status == ChartPlotterRoute.UNCHARTED ? STATUS_UNCHARTED : r.status == ChartPlotterRoute.BLOCKED ? STATUS_BLOCKED : STATUS_WARN;
		return future ? faded(c) : c;
	}
	private void label(Graphics2D g, int px, int py, int i, Color c) {
		String text = stopLabels[i];
		if (text == null) stopLabels[i] = text = Integer.toString(stopLabelStart + i);
		int x = px + 10;
		int y = py + g.getFontMetrics().getAscent() / 2;
		g.setColor(alpha(Color.BLACK, c.getAlpha()));
		g.drawString(text, x + 1, y + 1);
		g.setColor(c);
		g.drawString(text, x, y);
	}
	private void drawRoutePath(Graphics2D g, ChartPlotterWorldMap.State s, ChartPlotterRoute r, Color c, ChartPlotterRouteMoves.Model model) {
		if (r.n < 1) return;
		Stroke old = g.getStroke();
		Stroke solid = routeStroke.solid(config.worldMapLineWidth());
		Stroke dash = routeStroke.dashed(config.worldMapLineWidth());
		int pad = linePad(s);
		g.setColor(c);
		for (int i = 1; i < r.n; i++) routeLine(g, s, r.x[i - 1] + r.offsetX, r.y[i - 1] + r.offsetY, r.x[i] + r.offsetX, r.y[i] + r.offsetY, model, solid, dash, pad);
		for (int i = 1; i < r.departure.length; i++) routeLine(g, s, r.departureX(i - 1), r.departureY(i - 1), r.departureX(i), r.departureY(i), model, solid, dash, pad);
		for (int i = 1; i < r.connection.length; i++) routeLine(g, s, r.connectionX(i - 1), r.connectionY(i - 1), r.connectionX(i), r.connectionY(i), model, solid, dash, pad);
		g.setStroke(old);
	}
	private void routeLine(Graphics2D g, ChartPlotterWorldMap.State s, double ax, double ay, double bx, double by, ChartPlotterRouteMoves.Model model, Stroke solid, Stroke dash, int pad) {
		if (!lineVisible(s, ax, ay, bx, by, pad)) return;
		g.setStroke(ChartPlotterRouteMoves.solid(ax, ay, bx, by, model) ? solid : dash);
		g.drawLine(map.pointX(s, ax), map.pointY(s, ay), map.pointX(s, bx), map.pointY(s, by));
	}
	private ChartPlotterRouteMoves.Model routeModel() {
		double speed = ChartPlotterRouteMoves.speedBucket(plugin.speed());
		if (Double.doubleToLongBits(speed) != Double.doubleToLongBits(routeSpeed)) {
			routeSpeed = speed;
			routeModel = ChartPlotterRouteMoves.model(speed);
		}
		return routeModel;
	}
	private int linePad(ChartPlotterWorldMap.State s) {return (int) Math.ceil(config.worldMapLineWidth() / (s.z * 2)) + 1;}
	private Color faded(Color color) {return alpha(color, color.getAlpha() * 3 / 5);}
	private Color alpha(Color color, int alpha) {
		int key = color.getRGB() & 0xffffff;
		for (int i = 0; i < colorCache.length; i++) {
			Color[] cache = colorCache[i];
			if (cache == null || colorKey[i] != key) continue;
			Color result = cache[alpha];
			if (result == null) cache[alpha] = result = new Color(key | alpha << 24, true);
			return result;
		}
		int i = colorNext++ & colorCache.length - 1;
		colorKey[i] = key;
		Color[] cache = colorCache[i] = new Color[256];
		return cache[alpha] = new Color(key | alpha << 24, true);
	}
	void drawCache(Graphics2D g, ChartPlotterWorldMap.State s) {
		Stroke old = g.getStroke();
		ChartPlotterCollisionData data = collisionCache.snapshot();
		int minWX = (int) Math.floor(s.pos.getX() - s.wt / 2.0) - 8;
		int minWY = (int) Math.floor(s.pos.getY() - s.ht / 2.0) - 8;
		int maxWX = (int) Math.ceil(s.pos.getX() + s.wt / 2.0) + 8;
		int maxWY = (int) Math.ceil(s.pos.getY() + s.ht / 2.0) + 8;
		int minCX = Math.floorDiv(minWX, 8);
		int minCY = Math.floorDiv(minWY, 8);
		int maxCX = Math.floorDiv(maxWX, 8);
		int maxCY = Math.floorDiv(maxWY, 8);
		long window = (long) (maxCX - minCX + 1) * (maxCY - minCY + 1);
		g.setStroke(CACHE_STROKE);
		g.setColor(CACHE_EDGE);
		if (window <= data.size()) drawCacheWindow(g, s, data, minCX, minCY, maxCX, maxCY, minWX, minWY, maxWX, maxWY);
		else drawCacheEntries(g, s, data, minWX, minWY, maxWX, maxWY);
		g.setStroke(old);
	}
	private void drawCacheWindow(Graphics2D g, ChartPlotterWorldMap.State s, ChartPlotterCollisionData data, int minCX, int minCY, int maxCX, int maxCY, int minWX, int minWY, int maxWX, int maxWY) {
		for (int cx = minCX; cx <= maxCX; cx++) {
			for (int cy = minCY; cy <= maxCY; cy++) {
				ChartPlotterCollisionData.Chunk c = data.chunk(cx, cy);
				if (c == null || c.empty() || cacheChunkHidden(s, cx, cy, minWX, minWY, maxWX, maxWY)) continue;
				drawCacheChunk(g, s, data, cx, cy);
			}
		}
	}
	private void drawCacheEntries(Graphics2D g, ChartPlotterWorldMap.State s, ChartPlotterCollisionData data, int minWX, int minWY, int maxWX, int maxWY) {
		for (int i = 0; i < data.capacity(); i++) {
			ChartPlotterCollisionData.Chunk chunk = data.chunkAt(i);
			if (chunk == null) continue;
			long key = data.keyAt(i);
			int cx = (int) (key >> 32);
			int cy = (int) key;
			if (cacheChunkHidden(s, cx, cy, minWX, minWY, maxWX, maxWY)) continue;
			drawCacheChunk(g, s, data, cx, cy);
		}
	}
	private void drawCacheChunk(Graphics2D g, ChartPlotterWorldMap.State s, ChartPlotterCollisionData data, int cx, int cy) {
		int wx = cx << 3;
		int wy = cy << 3;
		drawCacheEdge(g, s, wx, wy, 0, 0, wx, wy + 7, 0, 1);
		if (data.uncached(cx + 1, cy)) drawCacheEdge(g, s, wx + 7, wy, 1, 0, wx + 7, wy + 7, 1, 1);
		drawCacheEdge(g, s, wx, wy, 0, 0, wx + 7, wy, 1, 0);
		if (data.uncached(cx, cy + 1)) drawCacheEdge(g, s, wx, wy + 7, 0, 1, wx + 7, wy + 7, 1, 1);
	}
	private boolean cacheChunkHidden(ChartPlotterWorldMap.State s, int cx, int cy, int minWX, int minWY, int maxWX, int maxWY) {
		int wx = cx << 3;
		int wy = cy << 3;
		return wx > maxWX || wx + 7 < minWX || wy > maxWY || wy + 7 < minWY || !s.data.surfaceContainsPosition(wx + 4, wy + 4);
	}
	private void drawCacheEdge(Graphics2D g, ChartPlotterWorldMap.State s, int ax, int ay, double afx, double afy, int bx, int by, double bfx, double bfy) {
		g.drawLine(map.pointX(s, ax + afx), map.pointY(s, ay + afy), map.pointX(s, bx + bfx), map.pointY(s, by + bfy));
	}
	private void tip(Graphics2D g, Rectangle r, int px, int py, String... lines) {
		if (config.worldMapTooltips() == ChartPlotterMapTooltip.OFF || lines == null || lines.length == 0) return;
		FontMetrics fm = g.getFontMetrics();
		int w = 0;
		for (String line : lines) w = Math.max(w, fm.stringWidth(line));
		w += 10;
		int h = fm.getHeight() * lines.length + 6;
		int x = px + 12;
		int y = py - h - 8;
		if (x + w > r.x + r.width) x = px - w - 12;
		if (y < r.y) y = py + 12;
		x = Math.max(r.x + 4, Math.min(x, r.x + r.width - w - 4));
		y = Math.max(r.y + 4, Math.min(y, r.y + r.height - h - 4));
		g.setColor(TIP_BG);
		g.fillRect(x, y, w, h);
		g.setColor(Color.WHITE);
		for (int i = 0; i < lines.length; i++) g.drawString(lines[i], x + 5, y + fm.getAscent() + 3 + i * fm.getHeight());
	}
	private void drawCoursePreview(Graphics2D g, ChartPlotterWorldMap.State s, Shape clip, boolean append) {
		Point m = hover(clip);
		if (m == null || cachedStopIndex(m) >= 0 || !map.tile(m, s, tile)) {plugin.clearCoursePreview(); return;}
		int[] t = tile;
		ChartPlotterRoutes.Preview pv = plugin.coursePreview(t[0], t[1], append);
		if (pv.state == ChartPlotterRoutes.PV_NONE) return;
		Color c = pv.state == ChartPlotterRoutes.PV_OK ? PREVIEW_OK : pv.state == ChartPlotterRoutes.PV_BAD ? PREVIEW_BAD : pv.state == ChartPlotterRoutes.PV_PENDING ? PREVIEW_PENDING : PREVIEW_SNAP;
		int dstX = map.pointX(s, pv.x + 0.5);
		int dstY = map.pointY(s, pv.y + 0.5);
		if (pv.x != t[0] || pv.y != t[1]) {
			int cursorX = map.pointX(s, t[0] + 0.5);
			int cursorY = map.pointY(s, t[1] + 0.5);
			g.setColor(c);
			g.drawLine(cursorX, cursorY, dstX, dstY);
			ellipse.setFrame(cursorX - 2, cursorY - 2, 4, 4);
			g.fill(ellipse);
		}
		marker(g, dstX, dstY, c);
	}
	private void marker(Graphics2D g, int x, int y, Color c) {
		g.setColor(c);
		ellipse.setFrame(x - 3.5, y - 3.5, 7, 7);
		g.fill(ellipse);
		ellipse.setFrame(x - 7.5, y - 7.5, 15, 15);
		g.draw(ellipse);
	}
	void cacheStops(ChartPlotterWorldMap.State s, Shape clip, ChartPlotterTrip trip) {
		StopCache old = stopCache;
		if (old.same(s, clip, trip)) return;
		int[] hits = new int[trip.size() * 5];
		int n = 0;
		for (int i = 0; i < trip.size(); i++) {
			int x = map.pointX(s, trip.markerX(i));
			int y = map.pointY(s, trip.markerY(i));
			if (!clip.contains(x, y)) continue;
			hits[n++] = i;
			hits[n++] = trip.x(i);
			hits[n++] = trip.y(i);
			hits[n++] = x;
			hits[n++] = y;
		}
		stopCache = new StopCache(s, clip, trip, n == hits.length ? hits : Arrays.copyOf(hits, n));
	}
	private int cachedStopIndex(Point m) {
		StopCache cache = stopCache;
		if (m == null || cache.clip == null || !cache.clip.contains(m.getX(), m.getY())) return -1;
		int best = -1;
		int bd = STOP_HIT_RADIUS * STOP_HIT_RADIUS + 1;
		for (int i = cache.hits.length - 5; i >= 0; i -= 5) {
			int dx = cache.hits[i + 3] - m.getX();
			int dy = cache.hits[i + 4] - m.getY();
			int d = dx * dx + dy * dy;
			if (d >= bd) continue;
			best = cache.hits[i];
			bd = d;
		}
		return best;
	}
	private int stop(Point m, ChartPlotterWorldMap.State s, Shape clip, ChartPlotterTrip trip) {
		if (m == null || !clip.contains(m.getX(), m.getY())) return -1;
		int best = -1;
		int bd = STOP_HIT_RADIUS * STOP_HIT_RADIUS + 1;
		for (int i = trip.size() - 1; i >= 0; i--) {
			int dx = map.pointX(s, trip.markerX(i)) - m.getX();
			int dy = map.pointY(s, trip.markerY(i)) - m.getY();
			int d = dx * dx + dy * dy;
			if (d >= bd) continue;
			best = i;
			bd = d;
		}
		return best;
	}
	private Point hover(Shape clip) {
		Point m = ChartPlotterOverlay.eligibleMouse(client, plugin);
		return m != null && clip.contains(m.getX(), m.getY()) ? m : null;
	}
	private int hoverHeading(WorldView wv, LocalPoint anchor, ChartPlotterWorldMap.State s, Shape clip) {
		Point m = hover(clip);
		if (m == null) return -1;
		double ax = wv.getBaseX() + anchor.getX() / (double) TS;
		double ay = wv.getBaseY() + anchor.getY() / (double) TS;
		double dx = map.worldX(m, s) - ax;
		double dy = map.worldY(m, s) - ay;
		if (dx == 0 && dy == 0) return -1;
		double d = Math.toDegrees(Math.atan2(dy, dx));
		return ChartPlotterMath.norm((int) Math.round((270 - d) / 360 * 16) * 128);
	}
	private static final class StopCache {
		static final StopCache EMPTY = new StopCache();
		final Shape clip;
		final int[] hits;
		final Object stops;
		final float zoom;
		final int x;
		final int y;
		final int width;
		final int height;
		final int px;
		final int py;
		private StopCache() {
			clip = null;
			hits = new int[0];
			stops = null;
			zoom = 0;
			x = y = width = height = px = py = 0;
		}
		private StopCache(ChartPlotterWorldMap.State s, Shape clip, ChartPlotterTrip trip, int[] hits) {
			this.clip = clip;
			this.hits = hits;
			stops = trip.stopKey();
			zoom = s.z;
			x = s.r.x;
			y = s.r.y;
			width = s.r.width;
			height = s.r.height;
			px = s.pos.getX();
			py = s.pos.getY();
		}
		boolean same(ChartPlotterWorldMap.State s, Shape clip, ChartPlotterTrip trip) {return this.clip == clip && stops == trip.stopKey() && Float.floatToIntBits(zoom) == Float.floatToIntBits(s.z) && x == s.r.x && y == s.r.y && width == s.r.width && height == s.r.height && px == s.pos.getX() && py == s.pos.getY();}
	}
	private static boolean pointVisible(ChartPlotterWorldMap.State s, int x, int y, int pad) {
		double minX = s.pos.getX() - s.wt / 2.0 - pad;
		double minY = s.pos.getY() - s.ht / 2.0 - pad;
		double maxX = s.pos.getX() + s.wt / 2.0 + pad;
		double maxY = s.pos.getY() + s.ht / 2.0 + pad;
		return x >= minX && x <= maxX && y >= minY && y <= maxY;
	}
	private static boolean lineVisible(ChartPlotterWorldMap.State s, double ax, double ay, double bx, double by, int pad) {
		double minX = s.pos.getX() - s.wt / 2.0 - pad;
		double minY = s.pos.getY() - s.ht / 2.0 - pad;
		double maxX = s.pos.getX() + s.wt / 2.0 + pad;
		double maxY = s.pos.getY() + s.ht / 2.0 + pad;
		return Math.max(ax, bx) >= minX && Math.min(ax, bx) <= maxX && Math.max(ay, by) >= minY && Math.min(ay, by) <= maxY;
	}
}

package com.chartplotter.route;
import java.util.Arrays;
final class ChartPlotterPathHeap {
	int[] cost;
	int[] tie;
	int[] position;
	int[] nodes;
	int size;
	int peak;
	ChartPlotterPathHeap(int[] cost, int[] tie) {
		this.cost = cost;
		this.tie = tie;
		position = new int[cost.length];
		nodes = new int[Math.min(16384, cost.length)];
	}
	void add(int node) {
		int i = position[node] - 1;
		if (i < 0) {
			if (size == nodes.length) nodes = Arrays.copyOf(nodes, size * 2);
			i = size++;
			peak = Math.max(peak, size);
		}
		while (i > 0) {
			int p = (i - 1) >>> 2;
			if (!less(node, nodes[p])) break;
			nodes[i] = nodes[p];
			position[nodes[i]] = i + 1;
			i = p;
		}
		nodes[i] = node;
		position[node] = i + 1;
	}
	int poll() {
		int node = nodes[0];
		position[node] = 0;
		int last = nodes[--size];
		if (size == 0) return node;
		int i = 0;
		while (i * 4 + 1 < size) {
			int c = i * 4 + 1;
			int end = Math.min(c + 4, size);
			for (int next = c + 1; next < end; next++) if (less(nodes[next], nodes[c])) c = next;
			if (!less(nodes[c], last)) break;
			nodes[i] = nodes[c];
			position[nodes[i]] = i + 1;
			i = c;
		}
		nodes[i] = last;
		position[last] = i + 1;
		return node;
	}
	private boolean less(int a, int b) {return cost[a] != cost[b] ? cost[a] < cost[b] : tie != null && tie[a] != tie[b] ? tie[a] > tie[b] : a < b;}
}

package com.chartplotter.route;
import java.util.Arrays;
final class ChartPlotterPathQueue {
	private final int[] cost;
	private final int[] first;
	private final int[][] links;
	private final int[] active;
	private int[][] free = new int[16][];
	private int freeCount;
	private int allocatedPages;
	private int cursor;
	int size;
	ChartPlotterPathQueue(int[] cost, int step) {
		this.cost = cost;
		int capacity = 1;
		while (capacity <= step) capacity <<= 1;
		first = new int[capacity];
		links = new int[(cost.length + 255) >>> 8][];
		active = new int[links.length];
		Arrays.fill(first, -1);
	}
	void add(int node, int oldCost) {
		if (oldCost != 0) remove(node, oldCost & (first.length - 1));
		cursor = size == 0 ? cost[node] : Math.min(cursor, cost[node]);
		int bucket = cost[node] & (first.length - 1);
		int[] page = links[node >>> 8];
		if (page == null) {
			if (freeCount == 0) {page = new int[512]; allocatedPages++;}
			else {page = free[--freeCount]; free[freeCount] = null;}
			links[node >>> 8] = page;
		}
		active[node >>> 8]++;
		int index = node & 255;
		page[index + 256] = -1;
		page[index] = first[bucket];
		if (page[index] >= 0) links[page[index] >>> 8][256 + (page[index] & 255)] = node;
		first[bucket] = node;
		size++;
	}
	int poll() {
		while (first[cursor & (first.length - 1)] < 0) cursor++;
		int bucket = cursor & (first.length - 1);
		int node = first[bucket];
		remove(node, bucket);
		return node;
	}
	private void remove(int node, int bucket) {
		int[] page = links[node >>> 8];
		int next = page[node & 255];
		int previous = page[256 + (node & 255)];
		if (previous < 0) first[bucket] = next;
		else links[previous >>> 8][previous & 255] = next;
		if (next >= 0) links[next >>> 8][256 + (next & 255)] = previous;
		if (--active[node >>> 8] == 0) {
			if (freeCount == free.length) free = Arrays.copyOf(free, free.length * 2);
			free[freeCount++] = page;
			links[node >>> 8] = null;
		}
		size--;
	}
	long bytes() {return (first.length + active.length) * 4L + (links.length + free.length) * 8L + allocatedPages * 512L * 4;}
}

package com.chartplotter.route;
import com.chartplotter.ChartPlotterRouteEffort;
import com.chartplotter.collision.ChartPlotterCollisionData;
import java.util.function.BooleanSupplier;
public final class ChartPlotterRoute {
	private static final int[] EMPTY = new int[0];
	private static final long[] EMPTY_CONNECTION = new long[0];
	public static final int PENDING = 0;
	public static final int OK = 1;
	public static final int UNCHARTED = 2;
	public static final int NO_ROUTE = 3;
	public static final int COMPLEX = 4;
	public static final int BLOCKED = 5;
	public static final int FAILED = 6;
	public static final int TIMED_OUT = 7;
	public final int status;
	public final boolean recalculating;
	public final int sx;
	public final int sy;
	public final int tx;
	public final int ty;
	public final int[] x;
	public final int[] y;
	public final int n;
	final ChartPlotterRouteTarget source;
	final ChartPlotterRouteTarget target;
	public final long[] departure;
	public final long[] connection;
	final ChartPlotterRouteMotion motion;
	final ChartPlotterRouteHull hull;
	final int heading;
	public final double offsetX;
	public final double offsetY;
	public final int turnBias;
	public final int weight;
	public final ChartPlotterRouteEffort effort;
	public final long time;
	public final long updated;
	private ChartPlotterRoute(int status, int sx, int sy, int tx, int ty, int[] x, int[] y, int n, ChartPlotterRouteTarget source, ChartPlotterRouteTarget target, long[] departure, long[] connection, ChartPlotterRouteMotion motion, ChartPlotterRouteHull hull, int heading, int turnBias, int weight, ChartPlotterRouteEffort effort, long time, long updated, boolean recalculating) {
		this.status = status;
		this.recalculating = recalculating;
		this.sx = sx;
		this.sy = sy;
		this.tx = tx;
		this.ty = ty;
		this.x = x;
		this.y = y;
		this.n = n;
		this.source = source;
		this.target = target;
		this.departure = departure;
		this.connection = connection;
		this.motion = motion;
		this.hull = hull;
		this.heading = heading;
		offsetX = motion == null ? 0.5 : motion.offsetX;
		offsetY = motion == null ? 0.5 : motion.offsetY;
		this.turnBias = turnBias;
		this.weight = weight;
		this.effort = effort;
		this.time = time;
		this.updated = updated;
	}
	private static ChartPlotterRoute empty(int status, int sx, int sy, int tx, int ty, int turnBias, int weight) {
		long now = System.currentTimeMillis();
		return new ChartPlotterRoute(status, sx, sy, tx, ty, EMPTY, EMPTY, 0, null, null, EMPTY_CONNECTION, EMPTY_CONNECTION, null, null, -1, turnBias, weight, null, now, now, false);
	}
	public static ChartPlotterRoute pending(int sx, int sy, int tx, int ty, int turnBias, int weight) {return empty(PENDING, sx, sy, tx, ty, turnBias, weight);}
	public static ChartPlotterRoute uncharted(int sx, int sy, int tx, int ty, int turnBias, int weight) {return empty(UNCHARTED, sx, sy, tx, ty, turnBias, weight);}
	public static ChartPlotterRoute none(int sx, int sy, int tx, int ty, int turnBias, int weight) {return empty(NO_ROUTE, sx, sy, tx, ty, turnBias, weight);}
	public static ChartPlotterRoute complex(int sx, int sy, int tx, int ty, int turnBias, int weight) {return empty(COMPLEX, sx, sy, tx, ty, turnBias, weight);}
	public static ChartPlotterRoute timedOut(int sx, int sy, int tx, int ty, int turnBias, int weight) {return empty(TIMED_OUT, sx, sy, tx, ty, turnBias, weight);}
	public static ChartPlotterRoute blocked(int sx, int sy, int tx, int ty, int turnBias, int weight) {return empty(BLOCKED, sx, sy, tx, ty, turnBias, weight);}
	public static ChartPlotterRoute ok(int sx, int sy, int tx, int ty, int[] x, int[] y, int n, int turnBias, int weight) {
		long now = System.currentTimeMillis();
		return new ChartPlotterRoute(OK, sx, sy, tx, ty, x, y, n, null, null, EMPTY_CONNECTION, EMPTY_CONNECTION, null, null, -1, turnBias, weight, null, now, now, false);
	}
	ChartPlotterRoute plan(ChartPlotterRouteMotion motion, ChartPlotterRouteHull hull, int heading) {return new ChartPlotterRoute(status, sx, sy, tx, ty, x, y, n, source, target, departure, connection, motion, hull, heading, turnBias, weight, effort, time, updated, recalculating);}
	ChartPlotterRoute connect(ChartPlotterCollisionData data, ChartPlotterRouteTarget source, ChartPlotterRouteTarget target) {
		if (status != OK || n == 0 || target == null || target.x != tx || target.y != ty) throw new IllegalArgumentException("Invalid route destination");
		long[] from = source == null ? EMPTY_CONNECTION : connection(data, source, x[0], y[0]);
		for (int i = 0, j = from.length - 1; i < j; i++, j--) {long a = from[i]; from[i] = from[j]; from[j] = a;}
		return new ChartPlotterRoute(status, sx, sy, tx, ty, x, y, n, source, target, from, connection(data, target, x[n - 1], y[n - 1]), motion, hull, heading, turnBias, weight, effort, time, updated, recalculating);
	}
	private long[] connection(ChartPlotterCollisionData data, ChartPlotterRouteTarget target, int x, int y) {
		long[] path = target.path(data, x, y);
		if (offsetX == 0.5 && offsetY == 0.5) return path;
		long[] connected = new long[path.length + 1];
		connected[0] = path[0];
		System.arraycopy(path, 0, connected, 1, path.length);
		return connected;
	}
	public double departureX(int i) {return (int) (departure[i] >> 32) + (i + 1 == departure.length || i == 0 && heading >= 0 ? offsetX : 0.5);}
	public double departureY(int i) {return (int) departure[i] + (i + 1 == departure.length || i == 0 && heading >= 0 ? offsetY : 0.5);}
	public double connectionX(int i) {return (int) (connection[i] >> 32) + (i == 0 ? offsetX : 0.5);}
	public double connectionY(int i) {return (int) connection[i] + (i == 0 ? offsetY : 0.5);}
	public ChartPlotterRoute effort(ChartPlotterRouteEffort effort) {return new ChartPlotterRoute(status, sx, sy, tx, ty, x, y, n, source, target, departure, connection, motion, hull, heading, turnBias, weight, effort, time, updated, recalculating);}
	ChartPlotterRoute recalculate() {return recalculating ? this : new ChartPlotterRoute(status, sx, sy, tx, ty, x, y, n, source, target, departure, connection, motion, hull, heading, turnBias, weight, effort, time, updated, true);}
	public static ChartPlotterRoute failed(int sx, int sy, int tx, int ty, int turnBias, int weight) {return empty(FAILED, sx, sy, tx, ty, turnBias, weight);}
	public boolean start(int x, int y) {return sx == x && sy == y;}
	public ChartPlotterRoute advance(double sx, double sy, int prune, int follow, double lead) {
		if (status != OK || n == 0) return null;
		if (n == 1) return Math.hypot(sx - x[0] - offsetX, sy - y[0] - offsetY) <= follow ? this : null;
		int segment = -1;
		double progress = 0;
		double distance = (double) follow * follow;
		for (int i = 0; i < n - 1; i++) {
			double dx = (double) x[i + 1] - x[i];
			double dy = (double) y[i + 1] - y[i];
			double wx = sx - x[i] - offsetX;
			double wy = sy - y[i] - offsetY;
			double dd = dx * dx + dy * dy;
			double projection = dd == 0 ? 1 : (wx * dx + wy * dy) / dd;
			double t = Math.max(0, Math.min(1, projection));
			double px = wx - dx * t;
			double py = wy - dy * t;
			double d = px * px + py * py;
			if (d < distance || segment < 0 && d == distance) {
				segment = i;
				progress = projection;
				distance = d;
			}
			if (d <= (double) prune * prune && t < 1) break;
		}
		if (segment < 0) return null;
		if (distance > (double) prune * prune || segment == 0 && progress <= 0) return this;
		int dx = x[segment + 1] - x[segment];
		int dy = y[segment + 1] - y[segment];
		int steps = Math.abs(dx);
		int b = Math.abs(dy);
		while (b != 0) {int next = steps % b; steps = b; b = next;}
		int step = steps == 0 ? 0 : Math.max(0, Math.min(steps, (int) Math.ceil(progress * steps + lead * steps / Math.hypot(dx, dy))));
		int px = steps == 0 ? x[segment] : x[segment] + dx / steps * step;
		int py = steps == 0 ? y[segment] : y[segment] + dy / steps * step;
		if (Math.hypot(sx - px - offsetX, sy - py - offsetY) > follow) return this;
		int skip = segment + (step == steps ? 2 : 1);
		if (skip == 1 && px == x[0] && py == y[0]) return this;
		int[] nx = new int[n - skip + 1];
		int[] ny = new int[nx.length];
		nx[0] = px;
		ny[0] = py;
		System.arraycopy(x, skip, nx, 1, n - skip);
		System.arraycopy(y, skip, ny, 1, n - skip);
		int incoming = step == 0 ? segment - 1 : segment;
		int dir = motion == null || incoming < 0 ? -1 : motion.dir(x[incoming + 1] - x[incoming], y[incoming + 1] - y[incoming]);
		int start = dir < 0 ? heading : (ChartPlotterRouteMoves.OR[dir] + (hull.reverse ? 1024 : 0)) & 2047;
		return new ChartPlotterRoute(status, px, py, tx, ty, nx, ny, nx.length, null, target, EMPTY_CONNECTION, connection, motion, hull, start, turnBias, weight, effort, time, System.currentTimeMillis(), recalculating);
	}
	private boolean departureClear(ChartPlotterCollisionData data) {
		if (status != OK || hull == null || motion == null || n == 0) return false;
		if (heading < 0 || x[0] != sx || y[0] != sy) return hull.flag(data, x[0], y[0]) == ChartPlotterCollisionData.OPEN;
		return connected(data, x[0] + offsetX, y[0] + offsetY, heading);
	}
	boolean connected(ChartPlotterCollisionData data, double ax, double ay, int from) {
		if (status != OK || hull == null || motion == null || n == 0) return false;
		int d = n < 2 ? -1 : motion.dir(x[1] - x[0], y[1] - y[0]);
		int to = d < 0 ? from : ChartPlotterRouteMoves.OR[d] + (hull.reverse ? 1024 : 0) & 2047;
		return hull.geometry.sweep(data, ax, ay, from, ax, ay, to) == ChartPlotterCollisionData.OPEN && hull.geometry.sweep(data, ax, ay, to, x[0] + offsetX, y[0] + offsetY, to) == ChartPlotterCollisionData.OPEN;
	}
	boolean valid(ChartPlotterCollisionData data, BooleanSupplier cancel) {
		if (cancel.getAsBoolean() || !departureClear(data) || target == null || !target.contains(x[n - 1], y[n - 1])) return false;
		for (int i = 1; i < departure.length; i++) if (!data.clear(departureX(i - 1), departureY(i - 1), departureX(i), departureY(i))) return false;
		for (int i = 1; i < connection.length; i++) if (!data.clear(connectionX(i - 1), connectionY(i - 1), connectionX(i), connectionY(i))) return false;
		int previous = -1;
		for (int i = 1; i < n; i++) {
			int dx = x[i] - x[i - 1];
			int dy = y[i] - y[i - 1];
			int d = motion.dir(dx, dy);
			if (d < 0) return false;
			if (previous >= 0 && previous != d && hull.circle.flag(data, x[i - 1], y[i - 1]) != ChartPlotterCollisionData.OPEN && hull.turn(previous, d).flag(data, x[i - 1], y[i - 1]) != ChartPlotterCollisionData.OPEN) return false;
			int steps = motion.x[d] != 0 ? dx / motion.x[d] : dy / motion.y[d];
			for (int j = 0; j < steps; j++) {
				if ((j & 31) == 0 && cancel.getAsBoolean()) return false;
				if (hull.move[d].flag(data, x[i - 1] + motion.x[d] * j, y[i - 1] + motion.y[d] * j) != ChartPlotterCollisionData.OPEN) return false;
			}
			previous = d;
		}
		return !cancel.getAsBoolean();
	}
	ChartPlotterRoute refresh(ChartPlotterCollisionData data, BooleanSupplier cancel) {
		if (!valid(data, cancel)) return null;
		ChartPlotterRouteTarget from = source == null || source.matches(data) ? source : ChartPlotterRouteTarget.create(data, source.x, source.y, cancel);
		ChartPlotterRouteTarget to = target.matches(data) ? target : ChartPlotterRouteTarget.create(data, tx, ty, cancel);
		if (to == null || !to.contains(x[n - 1], y[n - 1]) || source != null && (from == null || !from.contains(x[0], y[0])) || cancel.getAsBoolean()) return null;
		return from == source && to == target ? this : new ChartPlotterRoute(status, sx, sy, tx, ty, x, y, n, from, to, departure, connection, motion, hull, heading, turnBias, weight, effort, time, updated, recalculating);
	}
	public String text() {
		if (status == PENDING) return "Charting course";
		if (status == UNCHARTED) return "Uncharted waters";
		if (status == BLOCKED) return "Not enough room for this boat";
		if (status == NO_ROUTE) return "No safe route found";
		if (status == COMPLEX) return "Search limit reached; try a nearer stop";
		if (status == TIMED_OUT) return "Search timed out; try a nearer stop";
		if (status == FAILED) return "Routing failed";
		return null;
	}
}

package com.chartplotter.route;
import com.chartplotter.collision.ChartPlotterCollisionData;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.function.BooleanSupplier;
final class ChartPlotterRouteComponent {
	final ChartPlotterCollisionData data;
	private final LongIntMap chunks;
	private final long[] reached;
	private ChartPlotterRouteComponent(ChartPlotterCollisionData data, LongIntMap chunks, long[] reached) {
		this.data = data;
		this.chunks = chunks;
		this.reached = reached;
	}
	boolean contains(int x, int y) {
		int a = chunks.get(ChartPlotterCollisionData.key(x >> 3, y >> 3));
		return a != LongIntMap.MISS && (reached[a] & 1L << ((x & 7) + ((y & 7) << 3))) != 0;
	}
	long bytes() {return reached.length * 8L + chunks.k.length * 13L;}
	static ChartPlotterRouteComponent create(ChartPlotterCollisionData data, int sx, int sy, BooleanSupplier cancel) {
		if (data.flagAt(sx, sy) != ChartPlotterCollisionData.OPEN) return null;
		LongIntMap seen = new LongIntMap(256);
		long[] keys = new long[Math.min(128, data.size())];
		long[] reached = new long[keys.length];
		boolean[] queued = new boolean[keys.length];
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		keys[0] = ChartPlotterCollisionData.key(sx >> 3, sy >> 3);
		reached[0] = 1L << ((sx & 7) + ((sy & 7) << 3));
		seen.put(keys[0], 0);
		queued[0] = true;
		queue.add(0);
		int count = 1;
		int visited = 0;
		while (!queue.isEmpty()) {
			if ((visited++ & 255) == 0 && cancel.getAsBoolean()) return null;
			int a = queue.remove();
			queued[a] = false;
			int x = (int) (keys[a] >> 32);
			int y = (int) keys[a];
			ChartPlotterCollisionData.Chunk current = data.chunk(x, y);
			if (current == null) continue;
			long open = current.known & ~current.blocked;
			long bits = reached[a];
			while (true) {
				long next = (bits | (bits & 0xfefefefefefefefeL) >>> 1 | (bits & 0x7f7f7f7f7f7f7f7fL) << 1 | bits >>> 8 | bits << 8) & open;
				if (next == bits) break;
				bits = next;
			}
			reached[a] = bits;
			for (int d = 0; d < 4; d++) {
				int nx = x + (d == 0 ? 1 : d == 1 ? -1 : 0);
				int ny = y + (d == 2 ? 1 : d == 3 ? -1 : 0);
				long key = ChartPlotterCollisionData.key(nx, ny);
				long edge = d == 0 ? bits >>> 7 & 0x0101010101010101L : d == 1 ? bits << 7 & 0x8080808080808080L : d == 2 ? bits >>> 56 : bits << 56;
				if (edge == 0) continue;
				ChartPlotterCollisionData.Chunk chunk = data.chunk(nx, ny);
				if (chunk == null) continue;
				edge &= chunk.known & ~chunk.blocked;
				if (edge == 0) continue;
				int b = seen.get(key);
				if (b == LongIntMap.MISS) {
					if (count == keys.length) {
						int capacity = Math.min(data.size(), count * 2);
						keys = Arrays.copyOf(keys, capacity);
						reached = Arrays.copyOf(reached, capacity);
						queued = Arrays.copyOf(queued, capacity);
					}
					b = count++;
					keys[b] = key;
					seen.put(key, b);
				}
				if ((edge & ~reached[b]) == 0) continue;
				reached[b] |= edge;
				if (!queued[b]) {queue.add(b); queued[b] = true;}
			}
		}
		return cancel.getAsBoolean() ? null : new ChartPlotterRouteComponent(data, seen, Arrays.copyOf(reached, count));
	}
}

package com.chartplotter.route;
import java.util.function.BooleanSupplier;
final class ChartPlotterRouteDistances {
	private final ChartPlotterRouteTerrain terrain;
	private final ChartPlotterRouteHull hull;
	private final BooleanSupplier cancel;
	private final int[] distance;
	private final int focusX;
	private final int focusY;
	private final int focusRadius;
	private ChartPlotterPathQueue queue;
	private boolean initialized;
	int expanded;
	ChartPlotterRouteDistances(ChartPlotterRouteTerrain terrain, ChartPlotterRouteHull hull, int gx, int gy, int radius, int focusX, int focusY, int focusRadius, ChartPlotterRouteTarget target, BooleanSupplier cancel) {
		this.terrain = terrain;
		this.hull = hull;
		this.cancel = cancel;
		this.focusX = focusX - terrain.minX;
		this.focusY = focusY - terrain.minY;
		this.focusRadius = focusRadius;
		distance = new int[terrain.clearance.length];
		int step = 0;
		for (int cost : terrain.motion.cost) step = Math.max(step, cost);
		queue = new ChartPlotterPathQueue(distance, Math.max(step * 2, radius * 2 * terrain.motion.cost[2]));
		for (int y = gy - radius; y <= gy + radius; y++) {
			if (cancel.getAsBoolean()) return;
			for (int x = gx - radius; x <= gx + radius; x++) {
				int a = terrain.at(x, y);
				if (a < 0 || target == null || !target.contains(x, y)) continue;
				for (ChartPlotterRouteHull.Mask pose : hull.hull) {
					if (!pose.clear(terrain, a)) continue;
					distance[a] = 1 + potential(x - terrain.minX, y - terrain.minY);
					queue.add(a, 0);
					break;
				}
			}
		}
		initialized = true;
	}
	int get(int target) {
		if (!initialized) return -1;
		if (target < 0 || target >= distance.length || terrain.clearance[target] == 0) return 0;
		if (distance[target] < 0) return -distance[target];
		if (distance[target] == Integer.MAX_VALUE) return 0;
		if (distance[target] == 1 + potential(target % terrain.width, target / terrain.width)) return 1;
		if (queue == null) return 0;
		if (!hull.core.clear(terrain, target)) {distance[target] = Integer.MAX_VALUE; return 0;}
		ChartPlotterRouteMotion motion = terrain.motion;
		while (queue.size > 0) {
			if ((expanded & 255) == 0 && cancel.getAsBoolean()) return -1;
			int a = queue.poll();
			int x = a % terrain.width;
			int y = a / terrain.width;
			int cost = distance[a] - potential(x, y);
			distance[a] = -cost;
			expanded++;
			for (int d = 0; d < 16; d++) {
				int nx = x + motion.x[d];
				int ny = y + motion.y[d];
				if (nx <= 0 || ny <= 0 || nx >= terrain.width - 1 || ny >= terrain.height - 1) continue;
				int b = a + terrain.delta[d];
				if (distance[b] < 0 || distance[b] == Integer.MAX_VALUE || terrain.clearance[b] == 0) continue;
				int next = cost + motion.cost[d];
				if (next > ChartPlotterRouteTerrain.MAX_COST) {terrain.limited = true; continue;}
				next += potential(nx, ny);
				if (distance[b] != 0 && next >= distance[b] || !hull.point[d].clear(terrain, a)) continue;
				if (distance[b] == 0 && !hull.core.clear(terrain, b)) {distance[b] = Integer.MAX_VALUE; continue;}
				int previous = distance[b];
				distance[b] = next;
				queue.add(b, previous);
			}
			if (a == target) break;
		}
		if (queue.size == 0) queue = null;
		return distance[target] < 0 ? -distance[target] : 0;
	}
	private int potential(int x, int y) {return terrain.motion.lowerBound(Math.max(0, Math.abs(x - focusX) - focusRadius), Math.max(0, Math.abs(y - focusY) - focusRadius));}
	long bytes() {return distance.length * 4L + (queue == null ? 0 : queue.bytes());}
}

package com.chartplotter.route;
