		}
		for (int i = 0; i < data.capacity(); i++) {
			if ((i & 255) == 0 && cancel.getAsBoolean()) return;
			ChartPlotterCollisionData.Chunk chunk = data.chunkAt(i);
			if (chunk == null) continue;
			long key = data.keyAt(i);
			int x = ((int) (key >> 32) << 3) - minX;
			int y = ((int) key << 3) - minY;
			if (x < 1 || y < 1 || x + 7 >= width - 1 || y + 7 >= height - 1) continue;
			for (long bits = chunk.known & ~chunk.blocked; bits != 0; bits &= bits - 1) {
				int bit = Long.numberOfTrailingZeros(bits);
				int a = x + (bit & 7) + (y + (bit >>> 3)) * width;
				clearance[a] = 1;
				open[a >>> 6] |= 1L << a;
			}
		}
		for (int y = 1; y < height - 1; y++) {
			if ((y & 31) == 0 && cancel.getAsBoolean()) return;
			for (int a = y * width + 1, end = (y + 1) * width - 1; a < end; a++) {
				if (clearance[a] != 0) clearance[a] = (byte) Math.min(100, 1 + Math.min(Math.min(clearance[a - 1], clearance[a - width]), Math.min(clearance[a - width - 1], clearance[a - width + 1])));
			}
		}
		for (int y = height - 2; y > 0; y--) {
			if ((y & 31) == 0 && cancel.getAsBoolean()) return;
			for (int a = (y + 1) * width - 2, end = y * width; a > end; a--) if (clearance[a] > 1) clearance[a] = (byte) Math.min(clearance[a], 1 + Math.min(Math.min(clearance[a + 1], clearance[a + width]), Math.min(clearance[a + width - 1], clearance[a + width + 1])));
		}
	}
	static ChartPlotterRouteTerrain create(ChartPlotterCollisionData data, ChartPlotterRouteMotion motion, int sx, int sy, BooleanSupplier cancel) {
		if (cancel.getAsBoolean() || data.flagAt(sx, sy) != ChartPlotterCollisionData.OPEN) return null;
		LongIntMap seen = new LongIntMap(Math.max(16, data.size() * 2));
		long[] queue = new long[data.size()];
		queue[0] = ChartPlotterCollisionData.key(sx >> 3, sy >> 3);
		seen.put(queue[0], 1);
		int count = 1;
		int minX = sx >> 3;
		int minY = sy >> 3;
		int maxX = minX;
		int maxY = minY;
		for (int i = 0; i < count; i++) {
			if ((i & 255) == 0 && cancel.getAsBoolean()) return null;
			int x = (int) (queue[i] >> 32);
			int y = (int) queue[i];
			minX = Math.min(minX, x);
			minY = Math.min(minY, y);
			maxX = Math.max(maxX, x);
			maxY = Math.max(maxY, y);
			for (int dx = -1; dx <= 1; dx++) for (int dy = -1; dy <= 1; dy++) {
				if (dx == 0 && dy == 0) continue;
				long key = ChartPlotterCollisionData.key(x + dx, y + dy);
				if (seen.get(key) != LongIntMap.MISS) continue;
				ChartPlotterCollisionData.Chunk chunk = data.chunk(x + dx, y + dy);
				if (chunk == null || (chunk.known & ~chunk.blocked) == 0) continue;
				seen.put(key, 1);
				queue[count++] = key;
			}
		}
		long width = ((long) maxX - minX + 1) * 8 + 2;
		long height = ((long) maxY - minY + 1) * 8 + 2;
		if (width > MAX_AREA || height > MAX_AREA || width * height > MAX_AREA) return null;
		return new ChartPlotterRouteTerrain(data, motion, minX * 8 - 1, minY * 8 - 1, (int) width, (int) height, cancel);
	}
	int at(int x, int y) {
		x -= minX;
		y -= minY;
		return x < 0 || y < 0 || x >= width || y >= height ? -1 : x + y * width;
	}
}

package com.chartplotter.route;

import com.chartplotter.ChartPlotterConfig;
import com.chartplotter.ChartPlotterRouteEffort;
import com.chartplotter.collision.ChartPlotterCollisionCache;
import com.chartplotter.collision.ChartPlotterCollisionData;
import com.chartplotter.collision.ChartPlotterHull;
import com.chartplotter.runtime.ChartPlotterSailing;
import com.chartplotter.util.ChartPlotterMath;
import net.runelite.api.Perspective;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.callback.ClientThread;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.concurrent.Future;
import java.util.concurrent.FutureTask;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BooleanSupplier;


@Singleton
public class ChartPlotterRoutes {
	private static final int TS = Perspective.LOCAL_TILE_SIZE;
	private static final int PRUNE_RADIUS = 20;
	private static final int FOLLOW_RADIUS = 32;
	private static final int PRUNE = 2;
	private static final int CLEAR_RADIUS = 10;
	public static final int MAX_STOPS = 32;
	private static final int ETA_CAP = 600;
	public static final int PV_NONE = 0;
	public static final int PV_OK = 1;
	public static final int PV_SNAP = 2;
	public static final int PV_BAD = 3;
	public static final int PV_PENDING = 4;
	private final ChartPlotterConfig config;
	private final ChartPlotterCollisionCache collisionCache;
	private final ChartPlotterSailing sailing;
	private final ClientThread clientThread;
	private final AtomicReference<ChartPlotterTrip> trip = new AtomicReference<>(ChartPlotterTrip.empty(0));
	private final AtomicInteger seq = new AtomicInteger();
	private volatile boolean activeBusy;
	private volatile boolean paused;
	private volatile long rev;
	private volatile ChartPlotterRouteComponent component;
	private boolean placing;
	private boolean resolvingPreview;
	private ArrayDeque<Runnable> placements;
	ThreadPoolExecutor exec;
	private final AtomicReference<Future<?>> work = new AtomicReference<>();
	private PreviewSlot previewSlot;
	private volatile Start checkedStart;
	@Inject
	protected ChartPlotterRoutes(ChartPlotterConfig config, ChartPlotterCollisionCache collisionCache, ChartPlotterSailing sailing, ClientThread clientThread) {
		this.config = config;
		this.collisionCache = collisionCache;
		this.sailing = sailing;
		this.clientThread = clientThread;
	}
	public void set(int tx, int ty) {
		Start s = startTile();
		if (s == null) return;
		ChartPlotterCollisionData data = collisionCache.snapshot();
		int cx = tx;
		int cy = ty;
		if (resolve(s, data, () -> set(cx, cy))) return;
		long t = target(data, tx, ty, s.x, s.y, CLEAR_RADIUS, component, new ChartPlotterHull(s.config));
		tx = (int) (t >> 32);
		ty = (int) t;
		if (data.flagAt(tx, ty) != ChartPlotterCollisionData.OPEN || component != null && !component.contains(tx, ty)) return;
		int id = cancel();
		ChartPlotterRouteEffort effort = config.routeEffort();
		int turnBias = config.routeShape().bias;
		ChartPlotterRoute pending = ChartPlotterRoute.pending(s.x, s.y, tx, ty, turnBias, effort.weight).effort(effort);
		trip.set(ChartPlotterTrip.single(id, tx, ty, pending));
		paused = false;
		request(s, data, new boolean[]{true}, id, turnBias, effort, false);
	}
	public void append(int tx, int ty) {
		int cx = tx;
		int cy = ty;
		if (placing) {
			if (placements == null) placements = new ArrayDeque<>();
			placements.add(() -> append(cx, cy));
			return;
		}
		Start s = startTile();
		if (s == null) return;
		ChartPlotterTrip old = trip.get();
		if (old.empty()) {
			set(tx, ty);
			return;
		}
		if (old.size() >= MAX_STOPS) return;
		int sx = legStartX(old, old.size(), s.x);
		int sy = legStartY(old, old.size(), s.y);
		ChartPlotterCollisionData data = collisionCache.snapshot();
		if (resolve(s, data, () -> append(cx, cy))) return;
		long t = target(data, tx, ty, sx, sy, CLEAR_RADIUS, component, new ChartPlotterHull(s.config));
		tx = (int) (t >> 32);
		ty = (int) t;
		if (data.flagAt(tx, ty) != ChartPlotterCollisionData.OPEN || component != null && !component.contains(tx, ty)) return;
		if (ChartPlotterMath.chebyshev(old.x(old.size() - 1), old.y(old.size() - 1), tx, ty) <= CLEAR_RADIUS) return;
		int id = cancel();
		ChartPlotterRouteEffort effort = config.routeEffort();
		int turnBias = config.routeShape().bias;
		ChartPlotterRoute pending = ChartPlotterRoute.pending(sx, sy, tx, ty, turnBias, effort.weight).effort(effort);
		int fx = tx;
		int fy = ty;
		boolean reboard = paused;
		ChartPlotterTrip next = trip.updateAndGet(p -> p.append(id, fx, fy, pending));
		paused = false;
		boolean[] selected = reboard ? all(next) : pending(next);
		if (data.rev != rev) merge(selected, failed(next));
		trip.updateAndGet(p -> p.pending(id, s.x, s.y, turnBias, effort.weight, effort, selected));
		request(s, data, selected, id, turnBias, effort, false);
	}
	public void move(int stop, int oldX, int oldY, int tx, int ty) {
		Start s = startTile();
		if (s == null) return;
		ChartPlotterTrip old = trip.get();
		if (stop < 0 || stop >= old.size() || old.x(stop) != oldX || old.y(stop) != oldY) return;
		int sx = legStartX(old, stop, s.x);
		int sy = legStartY(old, stop, s.y);
		ChartPlotterCollisionData data = collisionCache.snapshot();
		int cx = tx;
		int cy = ty;
		if (resolve(s, data, () -> move(stop, oldX, oldY, cx, cy))) return;
		long t = target(data, tx, ty, sx, sy, CLEAR_RADIUS, component, new ChartPlotterHull(s.config));
		tx = (int) (t >> 32);
		ty = (int) t;
		if (data.flagAt(tx, ty) != ChartPlotterCollisionData.OPEN || component != null && !component.contains(tx, ty)) return;
		if (old.x(stop) == tx && old.y(stop) == ty || stop > 0 && ChartPlotterMath.chebyshev(old.x(stop - 1), old.y(stop - 1), tx, ty) <= CLEAR_RADIUS || stop + 1 < old.size() && ChartPlotterMath.chebyshev(old.x(stop + 1), old.y(stop + 1), tx, ty) <= CLEAR_RADIUS) return;
		int id = cancel();
		int fx = tx;
		int fy = ty;
		boolean reboard = paused;
		ChartPlotterTrip next = trip.updateAndGet(p -> p.move(id, stop, fx, fy));
		paused = false;
		boolean[] selected = reboard ? all(next) : pending(next);
		selected[stop] = true;
		if (stop + 1 < selected.length) selected[stop + 1] = true;
		if (data.rev != rev) merge(selected, failed(next));
		ChartPlotterRouteEffort effort = config.routeEffort();
		int turnBias = config.routeShape().bias;
		trip.updateAndGet(p -> p.pending(id, s.x, s.y, turnBias, effort.weight, effort, selected));
		request(s, data, selected, id, turnBias, effort, false);
	}
	public void remove(int stop) {
		ChartPlotterTrip old = trip.get();
		if (stop < 0 || stop >= old.size()) return;
		int id = cancel();
		ChartPlotterTrip next = trip.updateAndGet(p -> p.remove(id, stop));
		if (next.empty()) {
			paused = false;
			idle();
			return;
		}
		Start s = startTile();
		if (s == null) return;
		boolean[] selected = paused ? all(next) : pending(next);
		paused = false;
		if (none(selected)) return;
		ChartPlotterRouteEffort effort = config.routeEffort();
		int turnBias = config.routeShape().bias;
		trip.updateAndGet(p -> p.pending(id, s.x, s.y, turnBias, effort.weight, effort, selected));
		request(s, collisionCache.snapshot(), selected, id, turnBias, effort, false);
	}
	public void remove(int stop, int x, int y) {
		ChartPlotterTrip current = trip.get();
		if (stop < 0 || stop >= current.size() || current.x(stop) != x || current.y(stop) != y) return;
		remove(stop);
	}
	public void truncate(int stop) {
		ChartPlotterTrip old = trip.get();
		if (stop < 0 || stop >= old.size()) return;
		int id = cancel();
		ChartPlotterTrip next = trip.updateAndGet(p -> p.truncate(id, stop));
		if (next.empty()) {
			paused = false;
			idle();
			return;
		}
		Start s = startTile();
		if (s == null) return;
		boolean[] selected = paused ? all(next) : pending(next);
		paused = false;
		if (none(selected)) return;
		ChartPlotterRouteEffort effort = config.routeEffort();
		int turnBias = config.routeShape().bias;
		trip.updateAndGet(p -> p.pending(id, s.x, s.y, turnBias, effort.weight, effort, selected));
		request(s, collisionCache.snapshot(), selected, id, turnBias, effort, false);
	}
	public void truncate(int stop, int x, int y) {
		ChartPlotterTrip current = trip.get();
		if (stop < 0 || stop >= current.size() || current.x(stop) != x || current.y(stop) != y) return;
		truncate(stop);
	}
	public Preview preview(int tx, int ty, boolean append) {
		Start s = startTile();
		if (s == null) return new Preview(PV_NONE, tx, ty);
		ChartPlotterTrip p = trip.get();
		ChartPlotterCollisionData data = collisionCache.snapshot();
		int sx = append && !p.empty() ? legStartX(p, p.size(), s.x) : s.x;
		int sy = append && !p.empty() ? legStartY(p, p.size(), s.y) : s.y;
		ChartPlotterRouteComponent reachable = component;
		long origin = target(data, s.x, s.y, s.x, s.y, 2, null, null);
		if (reachable != null && (reachable.data != data || !reachable.contains((int) (origin >> 32), (int) origin))) reachable = null;
		if (reachable == null && !placing && !resolvingPreview && work.get() == null) resolve(s, data, null);
		PreviewSlot cached = previewSlot;
		if (cached != null && cached.same(tx, ty, append, sx, sy, p, data, reachable, s.config)) return cached.preview;
		ChartPlotterHull hull = new ChartPlotterHull(s.config);
		Preview result;
		if (append && p.size() >= MAX_STOPS) result = new Preview(PV_BAD, tx, ty);
		else {
			long t = reachable == null ? ChartPlotterCollisionData.key(tx, ty) : target(data, tx, ty, sx, sy, CLEAR_RADIUS, reachable, hull);
			int rx = (int) (t >> 32);
			int ry = (int) t;
			result = new Preview(data.flagAt(rx, ry) == ChartPlotterCollisionData.UNKNOWN || reachable != null && !reachable.contains(rx, ry) || append && !p.empty() && ChartPlotterMath.chebyshev(p.x(p.size() - 1), p.y(p.size() - 1), rx, ry) <= CLEAR_RADIUS ? PV_BAD : reachable == null ? PV_PENDING : rx == tx && ry == ty ? PV_OK : PV_SNAP, rx, ry);
		}
		previewSlot = new PreviewSlot(tx, ty, append, sx, sy, p, data, reachable, hull, result);
		return result;
	}
	public void tick(WorldView top, WorldEntity ship, LocalPoint loc) {
		if (placing) return;
		ChartPlotterTrip p = trip.get();
		if (p.empty()) return;
		Start s = start(top, ship, loc);
		Start previous = checkedStart;
		boolean changedStart = previous != null && previous.positionChanged(s);
		checkedStart = s;
		ChartPlotterRoute r = p.active();
		if (paused) {
			paused = false;
			replan(s, all(p));
			return;
		}
		if (r == null) {
			if (!activeBusy) replan(s, missing(p));
			return;
		}
		boolean offRoute = false;
		if (r.status == ChartPlotterRoute.OK) {
			if (sailing.speed() > 0) {
				LocalPoint front = routeLoc(top, ship, loc);
				ChartPlotterRoute nr = r.advance(top.getBaseX() + front.getX() / (double) TS, top.getBaseY() + front.getY() / (double) TS, PRUNE_RADIUS, FOLLOW_RADIUS, PRUNE);
				offRoute = nr == null;
				if (nr != null && nr != r && r.departure.length > 1 && s.heading >= 0 && !nr.connected(collisionCache.snapshot(), s.x + s.offsetX, s.y + s.offsetY, s.heading)) nr = r;
				if (nr != null && nr != r) {
					ChartPlotterTrip next = p.route(0, nr);
					if (!trip.compareAndSet(p, next)) return;
					p = next;
					r = nr;
				}
			}
			if (r.hull != null && r.hull.matches(s.config) && p.reached(s.x, s.y, collisionCache.snapshot())) {
				advance(s);
				return;
			}
		}
		if (activeBusy) return;
		if (r.status == ChartPlotterRoute.PENDING) {
			if (work.get() == null && rev != collisionCache.rev()) {
				boolean[] selected = new boolean[p.size()];
				selected[0] = true;
				replan(s, selected);
			}
			return;
		}
		int turnBias = config.routeShape().bias;
		ChartPlotterRouteEffort effort = config.routeEffort();
		if (r.turnBias != turnBias || r.effort != effort) {
			replan(s, all(p));
			return;
		}
		if (r.status == ChartPlotterRoute.OK && (r.motion == null || r.hull == null) || r.hull != null && !r.hull.matches(s.config)) {
			replan(s, all(p));
			return;
		}
		if (work.get() == null && rev != collisionCache.rev()) {
			int id = cancel();
			trip.updateAndGet(current -> current.generation(id));
			request(s, collisionCache.snapshot(), all(p), id, turnBias, effort, true);
			return;
		}
		if (changedStart && r.status != ChartPlotterRoute.OK || offRoute) {
			boolean[] selected = new boolean[p.size()];
			selected[0] = true;
			replan(s, selected);
		}
	}
	public void clear() {
		int id = cancel();
		trip.set(ChartPlotterTrip.empty(id));
		paused = false;
		rev = 0;
		checkedStart = null;
		idle();
	}
	public void pause() {
		if (!placing && !resolvingPreview && (paused || trip.get().empty())) return;
		int id = cancel();
		trip.updateAndGet(p -> p.generation(id));
		paused = !trip.get().empty();
		rev = 0;
		idle();
	}
	public void scene() {
		int id = cancel();
		trip.updateAndGet(p -> p.generation(id));
		rev = Long.MIN_VALUE;
		checkedStart = null;
		component = null;
	}
	public void stop() {clear();}
	public ChartPlotterRoute route() {return trip.get().active();}
	public ChartPlotterTrip trip() {return trip.get();}
	public boolean canAppend() {return trip.get().size() < MAX_STOPS;}
	public void clearPreview() {
		previewSlot = null;
		if (placing) return;
		if (resolvingPreview) cancel();
		if (trip.get().empty()) idle();
	}
	private LocalPoint routeLoc(WorldView top, WorldEntity ship, LocalPoint loc) {
		WorldEntityConfig wc = ship.getConfig();
		if (wc == null) return loc;
		int o = sailing.heading(ship);
		int x = wc.getBoundsX();
		int y = Math.round(wc.getBoundsY() + (sailing.reversing() ? 1 : -1) * wc.getBoundsHeight() / 2f);
		return new LocalPoint(ChartPlotterMath.rotateX(loc.getX(), o, x, y), ChartPlotterMath.rotateY(loc.getY(), o, x, y), top);
	}
	static long target(ChartPlotterCollisionData data, int tx, int ty, int sx, int sy, int radius, ChartPlotterRouteComponent component, ChartPlotterHull hull) {
		int flag = data.flagAt(tx, ty);
		boolean open = flag == ChartPlotterCollisionData.OPEN && (component == null || component.contains(tx, ty));
		if (flag == ChartPlotterCollisionData.UNKNOWN || open && (hull == null || hull.circle(tx + 0.5, ty + 0.5, data::flagAt) == ChartPlotterCollisionData.OPEN)) return ChartPlotterCollisionData.key(tx, ty);
		int bx = tx;
		int by = ty;
		int distance = Integer.MAX_VALUE;
		long best = Long.MAX_VALUE;
		for (int y = ty - radius; y <= ty + radius; y++) for (int x = tx - radius; x <= tx + radius; x++) {
			if (data.flagAt(x, y) != ChartPlotterCollisionData.OPEN || component != null && !component.contains(x, y)) continue;
			long dx = (long) x - sx;
			long dy = (long) y - sy;
			int d = (x - tx) * (x - tx) + (y - ty) * (y - ty);
			long score = dx * dx + dy * dy;
			if (d > distance || d == distance && score >= best) continue;
			if (hull != null && (open && !data.clear(tx + 0.5, ty + 0.5, x + 0.5, y + 0.5) || hull.circle(x + 0.5, y + 0.5, data::flagAt) != ChartPlotterCollisionData.OPEN)) continue;
			bx = x; by = y; distance = d; best = score;
		}
		return distance == Integer.MAX_VALUE && hull != null ? target(data, tx, ty, sx, sy, radius, component, null) : ChartPlotterCollisionData.key(bx, by);
	}
	private boolean resolve(Start s, ChartPlotterCollisionData data, Runnable action) {
		long origin = target(data, s.x, s.y, s.x, s.y, 2, null, null);
		int sx = (int) (origin >> 32);
		int sy = (int) origin;
		ChartPlotterRouteComponent cached = component;
		if (cached != null && cached.data == data && cached.contains(sx, sy)) return false;
		component = null;
		if (data.flagAt(sx, sy) != ChartPlotterCollisionData.OPEN) return false;
		int id = cancel();
		trip.updateAndGet(p -> p.generation(id));
		placing = action != null;
		resolvingPreview = action == null;
		start();
		AtomicReference<Future<?>> nextRef = new AtomicReference<>();
		FutureTask<Void> next = new FutureTask<>(() -> {
			try {
				ChartPlotterRouteComponent reachable = ChartPlotterRouteComponent.create(data, sx, sy, () -> id != seq.get());
				if (reachable == null || id != seq.get()) return;
				clientThread.invoke(() -> {
					if (id != seq.get()) return;
					component = reachable;
					placing = false;
					resolvingPreview = false;
					previewSlot = null;
					if (action == null) return;
					ArrayDeque<Runnable> queued = placements;
					placements = null;
					action.run();
					if (queued != null) while (!queued.isEmpty()) queued.remove().run();
					if (id != seq.get()) return;
					Start live = startTile();
					if (trip.get().empty()) idle();
					else if (live == null) pause();
					else replan(live, pending(trip.get()));
				});
			} finally {
				work.compareAndSet(nextRef.get(), null);
			}
		}, null) {
			@Override
			protected void setException(Throwable error) {
				super.setException(error);
				LoggerFactory.getLogger(ChartPlotterRoutes.class).warn("Destination placement failed", error);
				clientThread.invoke(() -> {
					if (id != seq.get()) return;
					pause();
				});
			}
		};
		nextRef.set(next);
		work.set(next);
		exec.execute(next);
		return true;
	}
	Start startTile() {
		if (!sailing.boarded()) return null;
		WorldView top = sailing.top();
		WorldEntity ship = sailing.ship();
		if (top == null || ship == null) return null;
		LocalPoint loc = sailing.anchorLoc(ship);
		if (loc == null) return null;
		return start(top, ship, loc);
	}
	private Start start(WorldView top, WorldEntity ship, LocalPoint loc) {
		return new Start(ship.getConfig(), ChartPlotterMath.worldTile(top.getBaseX(), loc.getX()), ChartPlotterMath.worldTile(top.getBaseY(), loc.getY()), Math.max(0.5, sailing.routeSpeed()), Math.floorMod(loc.getX(), TS) / (double) TS, Math.floorMod(loc.getY(), TS) / (double) TS, sailing.heading(ship));
	}
	private void advance(Start s) {
		boolean reboard = paused;
		int id = cancel();
		paused = false;
		ChartPlotterTrip next = trip.updateAndGet(p -> p.advance(id));
		if (next.empty()) {
			idle();
			return;
		}
		boolean[] selected = reboard ? all(next) : pending(next);
		checkedStart = s;
		if (none(selected)) return;
		ChartPlotterRouteEffort effort = config.routeEffort();
		int turnBias = config.routeShape().bias;
		trip.updateAndGet(p -> p.pending(id, s.x, s.y, turnBias, effort.weight, effort, selected));
		request(s, collisionCache.snapshot(), selected, id, turnBias, effort, false);
	}
	private void replan(Start s, boolean[] selected) {
		if (none(selected)) return;
		ChartPlotterCollisionData data = collisionCache.snapshot();
		ChartPlotterTrip current = trip.get();
		if (data.rev != rev) merge(selected, failed(current));
		int id = cancel();
		ChartPlotterRouteEffort effort = config.routeEffort();
		int turnBias = config.routeShape().bias;
		ChartPlotterTrip next = trip.updateAndGet(p -> p.pending(id, s.x, s.y, turnBias, effort.weight, effort, selected));
		if (next.empty()) return;
		request(s, data, selected, id, turnBias, effort, false);
	}
	private void request(Start s, ChartPlotterCollisionData data, boolean[] selected, int id, int turnBias, ChartPlotterRouteEffort effort, boolean validate) {
		ChartPlotterTrip snapshot = trip.get();
		if (snapshot.generation() != id || snapshot.empty() || none(selected)) return;
		if (selected[0] && !validate) checkedStart = s;
		int weight = effort.weight;
		boolean changed = rev != data.rev;
		boolean[] awaiting = selected.clone();
		for (int i = 0; i < awaiting.length; i++) awaiting[i] |= changed && snapshot.route(i) != null && snapshot.route(i).status == ChartPlotterRoute.OK;
		activeBusy = awaiting[0];
		start();
		AtomicReference<Future<?>> nextRef = new AtomicReference<>();
		FutureTask<Void> next = new FutureTask<>(() -> {
			try {
				BooleanSupplier cancelled = () -> id != seq.get() || collisionCache.snapshot().scene != data.scene;
				ChartPlotterRouteComponent reachable = component;
				for (int i = 0; i < selected.length; i++) {
					ChartPlotterTrip current = trip.get();
					if (current.generation() != id || cancelled.getAsBoolean()) return;
					ChartPlotterRoute previous = current.route(i);
					int sx = legStartX(current, i, s.x);
					int sy = legStartY(current, i, s.y);
					if (i == 0 && s.heading < 0) {
						long origin = target(data, sx, sy, sx, sy, 2, null, null);
						sx = (int) (origin >> 32);
						sy = (int) origin;
					}
					boolean connected = previous != null && previous.tx == current.x(i) && previous.ty == current.y(i) && (i == 0 || previous.start(sx, sy));
					if (!awaiting[i] && connected) continue;
					awaiting[i] = true;
					if ((validate || !selected[i]) && connected && !previous.recalculating) {
						ChartPlotterCollisionData latest = collisionCache.snapshot();
						ChartPlotterRoute refreshed = previous.refresh(latest, cancelled);
						if (refreshed != null) {
							ChartPlotterTrip updatedTrip = current.route(i, refreshed);
							if (cancelled.getAsBoolean() || !collisionCache.publish(latest, () -> trip.compareAndSet(current, updatedTrip))) {
								i--;
								continue;
							}
							awaiting[i] = false;
							if (i == 0 && id == seq.get()) activeBusy = false;
							continue;
						}
					}
					if (updateFailed(id, i, ChartPlotterRoute.pending(sx, sy, snapshot.x(i), snapshot.y(i), turnBias, weight).effort(effort), s)) return;
					long started = System.nanoTime();
					ChartPlotterRouteFinder finder = new ChartPlotterRouteFinder(data, s.config, sx, sy, snapshot.x(i), snapshot.y(i), turnBias, s.speed, weight, i == 0 ? s.offsetX : 0.5, i == 0 ? s.offsetY : 0.5, i == 0 ? s.heading : -1, () -> cancelled.getAsBoolean() || System.nanoTime() - started >= effort.nanos);
					finder.component = reachable;
					if (previous != null && previous.source != null && previous.source.x == sx && previous.source.y == sy && previous.source.matches(data)) finder.source = previous.source;
					if (previous != null && previous.target != null && previous.tx == snapshot.x(i) && previous.ty == snapshot.y(i) && previous.target.matches(data)) finder.target = previous.target;
					ChartPlotterRoute r = finder.find().effort(effort);
					reachable = finder.component;
					if (cancelled.getAsBoolean()) return;
					if (r.status == ChartPlotterRoute.PENDING) r = ChartPlotterRoute.timedOut(sx, sy, snapshot.x(i), snapshot.y(i), turnBias, weight).effort(effort);
					if (cancelled.getAsBoolean() || updateFailed(id, i, r, s)) return;
					awaiting[i] = false;
					if (i == 0 && id == seq.get()) activeBusy = false;
				}
				if (id == seq.get()) {
					rev = data.rev;
					ChartPlotterRouteComponent cached = reachable;
					if (cached != null && cached.data == data && cached != component) clientThread.invoke(() -> {
						if (id == seq.get()) component = cached;
					});
				}
			} finally {
				if (id == seq.get()) activeBusy = false;
				work.compareAndSet(nextRef.get(), null);
			}
		}, null) {
			@Override
			protected void setException(Throwable error) {
				super.setException(error);
				if (id != seq.get()) return;
				LoggerFactory.getLogger(ChartPlotterRoutes.class).warn("Routing failed", error);
				trip.updateAndGet(current -> current.failed(id, awaiting));
				if (id == seq.get()) rev = data.rev;
			}
		};
		nextRef.set(next);
		work.set(next);
		exec.execute(next);
	}
	private boolean updateFailed(int id, int i, ChartPlotterRoute route, Start start) {
		while (id == seq.get()) {
			ChartPlotterTrip old = trip.get();
			if (old.generation() != id || i >= old.size()) return true;
			ChartPlotterCollisionData data = collisionCache.snapshot();
			ChartPlotterRoute checked = route.status == ChartPlotterRoute.OK ? route.refresh(data, () -> id != seq.get()) : route;
			if (checked == null) checked = ChartPlotterRoute.pending(route.sx, route.sy, route.tx, route.ty, route.turnBias, route.weight).effort(route.effort);
			Start live = checkedStart;
			if (i == 0 && live != null && checked.status != ChartPlotterRoute.PENDING && checked.status != ChartPlotterRoute.OK && live.positionChanged(start)) {rev = Long.MIN_VALUE; return true;}
			if (i == 0 && checked.status == ChartPlotterRoute.OK && live != null) {
				if (!checked.hull.matches(live.config)) {rev = Long.MIN_VALUE; return true;}
				ChartPlotterRoute remaining = checked.advance(live.x + live.offsetX, live.y + live.offsetY, PRUNE_RADIUS, FOLLOW_RADIUS, PRUNE);
				if (remaining == null) {rev = Long.MIN_VALUE; return true;}
				if (remaining == checked || checked.departure.length <= 1 || live.heading < 0 || remaining.connected(data, live.x + live.offsetX, live.y + live.offsetY, live.heading)) checked = remaining;
			}
			ChartPlotterTrip next = old.route(i, checked);
			if (collisionCache.publish(data, () -> (i != 0 || checkedStart == live) && trip.compareAndSet(old, next))) return false;
		}
		return true;
	}
	private int cancel() {
		int id = seq.incrementAndGet();
		placing = false;
		resolvingPreview = false;
		placements = null;
		Future<?> old = work.getAndSet(null);
		if (old != null) {
			old.cancel(false);
			ThreadPoolExecutor ex = exec;
			if (ex != null && old instanceof Runnable) ex.remove((Runnable) old);
		}
		activeBusy = false;
		return id;
	}
	private void start() {
		if (exec != null) return;
		exec = new ThreadPoolExecutor(1, 1, 5, TimeUnit.SECONDS, new LinkedBlockingQueue<>(), r -> {
			Thread t = new Thread(r, "chart-plotter-route");
			t.setDaemon(true);
			return t;
		});
		exec.allowCoreThreadTimeOut(true);
	}
	private void idle() {
		ThreadPoolExecutor ex = exec;
		if (ex != null) {
			ex.shutdownNow();
			exec = null;
		}
		previewSlot = null;
		component = null;
	}
	private static boolean[] pending(ChartPlotterTrip p) {
		boolean[] selected = new boolean[p.size()];
		for (int i = 0; i < selected.length; i++) selected[i] = p.route(i) == null || p.route(i).status == ChartPlotterRoute.PENDING || p.route(i).recalculating;
		return selected;
	}
	private static boolean[] missing(ChartPlotterTrip p) {
		boolean[] selected = new boolean[p.size()];
		for (int i = 0; i < selected.length; i++) selected[i] = p.route(i) == null;
		return selected;
	}
	private static boolean[] failed(ChartPlotterTrip p) {
		boolean[] selected = new boolean[p.size()];
		for (int i = 0; i < selected.length; i++) selected[i] = p.route(i) == null || p.route(i).status != ChartPlotterRoute.OK && p.route(i).status != ChartPlotterRoute.PENDING;
		return selected;
	}
	private static boolean[] all(ChartPlotterTrip p) {
		boolean[] selected = new boolean[p.size()];
		Arrays.fill(selected, true);
		return selected;
	}
	private static boolean none(boolean[] selected) {
		for (boolean on : selected) if (on) return false;
		return true;
	}
	static int legStartX(ChartPlotterTrip trip, int stop, int live) {
		return stop == 0 ? live : trip.x(stop - 1);
	}
	static int legStartY(ChartPlotterTrip trip, int stop, int live) {
		return stop == 0 ? live : trip.y(stop - 1);
	}
	private static void merge(boolean[] dst, boolean[] src) {for (int i = 0; i < dst.length; i++) dst[i] |= src[i];}
	static final class Start {
		final WorldEntityConfig config;
		final int x;
		final int y;
		final double speed;
		final double offsetX;
		final double offsetY;
		final int heading;
		Start(WorldEntityConfig config, int x, int y, double speed, double offsetX, double offsetY, int heading) {
			this.config = config;
			this.x = x;
			this.y = y;
			this.speed = speed;
			this.offsetX = offsetX;
			this.offsetY = offsetY;
			this.heading = heading;
		}
		boolean positionChanged(Start other) {return x != other.x || y != other.y || offsetX != other.offsetX || offsetY != other.offsetY;}
	}
	private static final class PreviewSlot {
		final int tx;
		final int ty;
		final boolean append;
		final int sx;
		final int sy;
		final Object stops;
		final ChartPlotterCollisionData data;
		final ChartPlotterRouteComponent component;
		final ChartPlotterHull hull;
		final Preview preview;
		private PreviewSlot(int tx, int ty, boolean append, int sx, int sy, ChartPlotterTrip trip, ChartPlotterCollisionData data, ChartPlotterRouteComponent component, ChartPlotterHull hull, Preview preview) {
			this.tx = tx;
			this.ty = ty;
			this.append = append;
			this.sx = sx;
			this.sy = sy;
			stops = trip.stopKey();
			this.data = data;
			this.component = component;
			this.hull = hull;
			this.preview = preview;
		}
		boolean same(int tx, int ty, boolean append, int sx, int sy, ChartPlotterTrip trip, ChartPlotterCollisionData data, ChartPlotterRouteComponent component, WorldEntityConfig config) {return this.tx == tx && this.ty == ty && this.append == append && this.sx == sx && this.sy == sy && stops == trip.stopKey() && this.data == data && this.component == component && hull.matches(config);}
	}
	public static Turn turn(ChartPlotterRoute r, double bx, double by, double speed, double accel, double max, long updated) {
		if (r == null || r.status != ChartPlotterRoute.OK || r.n == 0) return Turn.NONE;
		boolean end = r.n <= 2;
		int cx = end ? r.tx : r.x[1];
		int cy = end ? r.ty : r.y[1];
		double fx = end ? 0.5 : r.offsetX;
		double fy = end ? 0.5 : r.offsetY;
		int ticks = speed > 0 ? eta(Math.hypot(cx + fx - bx, cy + fy - by), speed, accel, max) : -1;
		return new Turn(true, cx, cy, fx, fy, ticks, updated > 0 ? updated : r.updated, end);
	}
	private static int eta(double dist, double speed, double accel, double max) {
		double v = speed;
		double d = 0;
		int t = 0;
		while (d < dist) {
			v += accel;
			if (v > max) v = max;
			if (v <= 0) return -1;
			d += v;
			if (++t > ETA_CAP) return -1;
		}
		return t;
	}
	public static final class Turn {
		public static final Turn NONE = new Turn();
		public final boolean valid;
		public final int x;
		public final int y;
		public final double offsetX;
		public final double offsetY;
		public final int ticks;
		public final long updated;
		public final boolean end;
		private Turn() {this(false, 0, 0, 0, 0, -1, 0, false);}
		private Turn(boolean valid, int x, int y, double offsetX, double offsetY, int ticks, long updated, boolean end) {
			this.valid = valid;
			this.x = x;
			this.y = y;
			this.offsetX = offsetX;
			this.offsetY = offsetY;
			this.ticks = ticks;
			this.updated = updated;
			this.end = end;
		}
	}
	public static final class Preview {
		public final int state;
		public final int x;
		public final int y;
		private Preview(int state, int x, int y) {
			this.state = state;
			this.x = x;
			this.y = y;
		}
	}
}

package com.chartplotter.route;
import com.chartplotter.ChartPlotterRouteEffort;
import com.chartplotter.collision.ChartPlotterCollisionData;
import java.util.Arrays;
public final class ChartPlotterTrip {
	private static final int[] EMPTY_INT = new int[0];
	private static final ChartPlotterRoute[] EMPTY_ROUTE = new ChartPlotterRoute[0];
	private final int generation;
	private final int completed;
	private final int[] x;
	private final int[] y;
	private final ChartPlotterRoute[] routes;
	private ChartPlotterTrip(int generation, int completed, int[] x, int[] y, ChartPlotterRoute[] routes) {
		this.generation = generation;
		this.completed = completed;
		this.x = x;
		this.y = y;
		this.routes = routes;
	}
	static ChartPlotterTrip empty(int generation) {return new ChartPlotterTrip(generation, 0, EMPTY_INT, EMPTY_INT, EMPTY_ROUTE);}
	static ChartPlotterTrip single(int generation, int x, int y, ChartPlotterRoute route) {return new ChartPlotterTrip(generation, 0, new int[]{x}, new int[]{y}, new ChartPlotterRoute[]{route});}
	public int size() {return x.length;}
	public boolean empty() {return x.length == 0;}
	public int stopNumber() {return empty() ? 0 : completed + 1;}
	public int totalStops() {return completed + x.length;}
	public int x(int i) {return x[i];}
	public int y(int i) {return y[i];}
	public double markerX(int i) {return x[i] + 0.5;}
	public double markerY(int i) {return y[i] + 0.5;}
	public ChartPlotterRoute route(int i) {return routes[i];}
	public Object stopKey() {return x;}
	public ChartPlotterRoute active() {return routes.length == 0 ? null : routes[0];}
	boolean reached(int bx, int by, ChartPlotterCollisionData data) {
		ChartPlotterRoute route = active();
		return route != null && route.status == ChartPlotterRoute.OK && !route.recalculating && route.target != null && route.target.contains(bx, by) && route.target.matches(data);
	}
	public double distance(double bx, double by, int stop) {
		if (stop < 0 || stop >= routes.length) return Double.NaN;
		double distance = 0;
		for (int i = 0; i <= stop; i++) {
			ChartPlotterRoute route = routes[i];
			if (route == null || route.status != ChartPlotterRoute.OK || route.n == 0) return Double.NaN;
			if (i > 0) {
				bx = route.sx + 0.5;
				by = route.sy + 0.5;
			}
			for (int j = 1; j < route.departure.length; j++) {
				double x = route.departureX(j);
				double y = route.departureY(j);
				distance += Math.hypot(x - bx, y - by);
				bx = x;
				by = y;
			}
			for (int j = Math.min(1, route.n - 1); j < route.n; j++) {
				double x = route.x[j] + route.offsetX;
				double y = route.y[j] + route.offsetY;
				distance += Math.hypot(x - bx, y - by);
				bx = x;
				by = y;
			}
			for (int j = 1; j < route.connection.length; j++) {
				double x = route.connectionX(j);
				double y = route.connectionY(j);
				distance += Math.hypot(x - bx, y - by);
				bx = x;
				by = y;
			}
		}
		return distance;
	}
	int generation() {return generation;}
	ChartPlotterTrip append(int generation, int tx, int ty, ChartPlotterRoute route) {
		int n = x.length;
		int[] nx = Arrays.copyOf(x, n + 1);
		int[] ny = Arrays.copyOf(y, n + 1);
		ChartPlotterRoute[] nr = Arrays.copyOf(routes, n + 1);
		nx[n] = tx;
		ny[n] = ty;
		nr[n] = route;
		return new ChartPlotterTrip(generation, completed, nx, ny, nr);
	}
	ChartPlotterTrip truncate(int generation, int n) {
		if (n <= 0) return empty(generation);
		return new ChartPlotterTrip(generation, completed, Arrays.copyOf(x, n), Arrays.copyOf(y, n), Arrays.copyOf(routes, n));
	}
	ChartPlotterTrip remove(int generation, int i) {
		if (x.length <= 1) return empty(generation);
		int n = x.length - 1;
		int[] nx = new int[n];
		int[] ny = new int[n];
		ChartPlotterRoute[] nr = new ChartPlotterRoute[n];
		System.arraycopy(x, 0, nx, 0, i);
		System.arraycopy(y, 0, ny, 0, i);
		System.arraycopy(routes, 0, nr, 0, i);
		System.arraycopy(x, i + 1, nx, i, n - i);
		System.arraycopy(y, i + 1, ny, i, n - i);
		System.arraycopy(routes, i + 1, nr, i, n - i);
		if (i < n) nr[i] = null;
		return new ChartPlotterTrip(generation, completed, nx, ny, nr);
	}
	ChartPlotterTrip advance(int generation) {
		if (x.length <= 1) return empty(generation);
		return new ChartPlotterTrip(generation, completed + 1, Arrays.copyOfRange(x, 1, x.length), Arrays.copyOfRange(y, 1, y.length), Arrays.copyOfRange(routes, 1, routes.length));
	}
	ChartPlotterTrip move(int generation, int i, int tx, int ty) {
		int[] nx = x.clone();
		int[] ny = y.clone();
		nx[i] = tx;
		ny[i] = ty;
		return new ChartPlotterTrip(generation, completed, nx, ny, routes);
	}
	ChartPlotterTrip generation(int generation) {return new ChartPlotterTrip(generation, completed, x, y, routes);}
	ChartPlotterTrip pending(int generation, int sx, int sy, int turnBias, int weight, ChartPlotterRouteEffort effort, boolean[] selected) {
		ChartPlotterRoute[] nr = routes.clone();
		for (int i = 0; i < nr.length; i++) {
			if (!selected[i]) continue;
			if (nr[i] != null && nr[i].status == ChartPlotterRoute.OK && nr[i].tx == x[i] && nr[i].ty == y[i] && (i == 0 || nr[i].start(x[i - 1], y[i - 1]))) {
				nr[i] = nr[i].recalculate();
				continue;
			}
			int ax = ChartPlotterRoutes.legStartX(this, i, sx);
			int ay = ChartPlotterRoutes.legStartY(this, i, sy);
			nr[i] = ChartPlotterRoute.pending(ax, ay, x[i], y[i], turnBias, weight).effort(effort);
		}
		return new ChartPlotterTrip(generation, completed, x, y, nr);
	}
	ChartPlotterTrip failed(int id, boolean[] awaiting) {
		if (generation != id) return this;
		ChartPlotterRoute[] next = routes.clone();
		for (int i = 0; i < next.length; i++) {
			ChartPlotterRoute route = next[i];
			if (awaiting[i] && route != null) next[i] = ChartPlotterRoute.failed(route.sx, route.sy, route.tx, route.ty, route.turnBias, route.weight).effort(route.effort);
		}
		return new ChartPlotterTrip(generation, completed, x, y, next);
	}
	ChartPlotterTrip route(int i, ChartPlotterRoute route) {
		ChartPlotterRoute next = route != null && route.status == ChartPlotterRoute.PENDING && routes[i] != null && routes[i].status == ChartPlotterRoute.OK && routes[i].tx == route.tx && routes[i].ty == route.ty ? routes[i].recalculate() : route;
		if (next == routes[i]) return this;
		ChartPlotterRoute[] nr = routes.clone();
		nr[i] = next;
		return new ChartPlotterTrip(generation, completed, x, y, nr);
	}
}

package com.chartplotter.route;
import java.util.Arrays;
final class LongIntMap {
	static final int MISS = Integer.MIN_VALUE;
	long[] k;
	int[] v;
	byte[] u;
	int n;
	int mask;
	byte mark = 1;
	LongIntMap(int size) {init(size);}
	int get(long key) {
		int i = hash(key) & mask;
		while (u[i] == mark) {
			if (k[i] == key) return v[i];
			i = i + 1 & mask;
		}
		return MISS;
	}
	void put(long key, int val) {
		if (n * 2 >= k.length) grow();
		int i = hash(key) & mask;
		while (u[i] == mark) {
			if (k[i] == key) {
				v[i] = val;
				return;
			}
			i = i + 1 & mask;
		}
		u[i] = mark;
		k[i] = key;
		v[i] = val;
		n++;
	}
	void clear() {
		if (++mark == 0) {
			Arrays.fill(u, (byte) 0);
			mark = 1;
		}
		n = 0;
	}
	private void init(int size) {
		int c = 1;
		while (c < size) c <<= 1;
		k = new long[c];
		v = new int[c];
		u = new byte[c];
		mask = c - 1;
		n = 0;
		mark = 1;
	}
	private void grow() {
		long[] ok = k;
		int[] ov = v;
		byte[] ou = u;
		byte om = mark;
		init(k.length << 1);
		for (int i = 0; i < ok.length; i++) {
			if (ou[i] == om) put(ok[i], ov[i]);
		}
	}
	private static int hash(long x) {
		x += 0x9e3779b97f4a7c15L;
		x = (x ^ x >>> 30) * -4658895280553007687L;
		x = (x ^ x >>> 27) * -7723592293110705685L;
		return (int) (x ^ x >>> 31);
	}
}

package com.chartplotter.runtime;
import com.chartplotter.ChartPlotterCacheOverlay;
import com.chartplotter.ChartPlotterConfig;
import com.chartplotter.ChartPlotterEtaMode;
public final class ChartPlotterFeatures {
	public final boolean course;
	public final boolean chart;
	public final boolean routes;
	public final boolean cacheView;
	public final boolean worldOverlay;
