		int x = ax;
		int y = ay;
		int heading = from;
		double steppedSpeed = Double.NaN;
		ChartPlotterSailing.Step step = null;
		for (int i = 0; i < cap; i++) {
			if (cancel.getAsBoolean()) return null;
