			down = true;
			dragged = false;
			downX = e.getX();
			downY = e.getY();
			downCtrl = e.isControlDown();
			downShift = e.isShiftDown();
			downAlt = e.isAltDown();
			boolean blocked = menuBlock || client.isMenuOpen() || e.isAltDown();
			downBlock = blocked || worldMapOverlay.cachedClickBlocked();
			boolean mod = e.isAltDown() || e.isControlDown() || e.isShiftDown();
			if (!downBlock && !mod && features.chart && sailing.boarded()) {
				int[] stop = worldMapOverlay.cachedStop(m);
				if (stop != null) {
					draggedStop = stop[0];
					draggedX = stop[1];
					draggedY = stop[2];
					stopPress = true;
					e.consume();
				}
			}
			if (!e.isConsumed() && !blocked && !mod && features.course && minimapOverlay.overMinimap(m)) {
				int version = sailing.commandVersion();
				clientThread.invoke(() -> sailing.setCourse(m, version));
			}
			return e;
		}
		@Override
		public MouseEvent mouseReleased(MouseEvent e) {
			worldMapOverlay.courseMods(e.isControlDown(), e.isShiftDown());
			boolean moved = dragged || Math.abs(e.getX() - downX) > CLICK_SLOP || Math.abs(e.getY() - downY) > CLICK_SLOP;
			int stop = draggedStop;
			int oldX = draggedX;
			int oldY = draggedY;
			int version = downVersion;
			if (e.getButton() == MouseEvent.BUTTON1 && down && stop >= 0) {
				Point m = new Point(e.getX(), e.getY());
				if (!downBlock) clientThread.invoke(() -> chartStop(m, stop, oldX, oldY, moved, version));
			} else if (e.getButton() == MouseEvent.BUTTON1 && down && !moved && !downBlock && features.chart && !downAlt) {
				Point m = new Point(e.getX(), e.getY());
				boolean active = courseClick();
				boolean shift = downShift;
				clientThread.invokeLater(() -> clientThread.invokeLater(() -> chartCourse(m, active, shift, version)));
			}
			if (e.getButton() == MouseEvent.BUTTON1) {
				if (stop >= 0) e.consume();
				draggedStop = -1;
				worldMapOverlay.clearStopDrag();
				down = false;
				menuBlock = false;
			}
			return e;
		}
		@Override
		public MouseEvent mouseClicked(MouseEvent e) {
			if (e.getButton() == MouseEvent.BUTTON1 && stopPress) {
				stopPress = false;
				e.consume();
			}
			return e;
		}
		@Override
		public MouseEvent mouseMoved(MouseEvent e) {
			worldMapOverlay.courseMods(e.isControlDown(), e.isShiftDown());
			return e;
		}
		@Override
		public MouseEvent mouseDragged(MouseEvent e) {
			if (down && (Math.abs(e.getX() - downX) > CLICK_SLOP || Math.abs(e.getY() - downY) > CLICK_SLOP)) dragged = true;
			if (draggedStop >= 0) {
				if (dragged) worldMapOverlay.dragStop(draggedStop, draggedX, draggedY, new Point(e.getX(), e.getY()));
				e.consume();
			}
			worldMapOverlay.courseMods(e.isControlDown(), e.isShiftDown());
			return e;
		}
		@Override
		public MouseEvent mouseExited(MouseEvent e) {
			down = false;
			cancelStopDrag();
			worldMapOverlay.courseMods(false, false);
			return e;
		}
	};
	private final KeyListener key = new KeyListener() {
		@Override
		public void keyTyped(KeyEvent e) {}
		@Override
		public void keyPressed(KeyEvent e) {mods(e);}
		@Override
		public void keyReleased(KeyEvent e) {mods(e);}
		@Override
		public void focusLost() {clearMods();}
	};
	public void start() {apply();}
	public void stop() {
		clearCourses();
		overlayManager.remove(overlay);
		overlayManager.remove(minimapOverlay);
		overlayManager.remove(worldMapOverlay);
		overlayManager.remove(infoOverlay);
		infoOverlay.clear();
		overlay.clear();
		minimapOverlay.clear();
		worldMapOverlay.clear();
		if (inputRegistered) {
			mouseManager.unregisterMouseListener(mouse);
			keyManager.unregisterKeyListener(key);
			inputRegistered = false;
		}
		clearMods();
		collisionActive = false;
		features = ChartPlotterFeatures.off();
		observedBoat = Integer.MIN_VALUE;
		alertX = Integer.MIN_VALUE;
		alertY = Integer.MIN_VALUE;
		scene.clear();
		collisionCache.stop();
		routes.stop();
		sailing.reset();
		sailing.average(false);
	}
	public void config(ConfigChanged e) {if ("chartplotter".equals(e.getGroup())) apply();}
	public void varbit(VarbitChanged e) {
		if (!features.tracking) return;
		boolean boarded = sailing.boarded();
		sailing.varbit(e);
		if (boarded == sailing.boarded()) return;
		if (sailing.boarded()) {
			updateScene();
			return;
		}
		routes.pause();
		observedBoat = Integer.MIN_VALUE;
		clearCourses();
		collision(false, null);
		sailing.clear();
		scene.clear();
	}
	public void state(GameStateChanged e) {
		if (!features.tracking) return;
		if (e.getGameState() == GameState.LOGGED_IN) {
			sailing.sync();
			updateScene();
			return;
		}
		if (e.getGameState() == GameState.LOADING) {
			clearCourses();
			collisionCache.invalidateScene();
			routes.scene();
			scene.clear();
			return;
		}
		sailing.reset();
		observedBoat = Integer.MIN_VALUE;
		clearCourses();
		routes.clear();
		collision(false, null);
		scene.clear();
	}
	public void loaded(WorldViewLoaded e) {
		if (!features.tracking) return;
		WorldView wv = e.getWorldView();
		if (wv == null || !wv.isTopLevel()) return;
		clearCourses();
		sailing.loaded(wv);
		routes.scene();
		if (features.scene && sailing.boarded()) scene.update(wv);
		capture(wv);
	}
	public void closed(WidgetClosed e) {
		if (e.getGroupId() != InterfaceID.WORLDMAP) return;
		clearMods();
		worldMapOverlay.clear();
		routes.clearPreview();
	}
	public void menu(MenuOpened ignored) {
		Point m = client.getMouseCanvasPosition();
		if (!features.chart) return;
		int stop = worldMapOverlay.stop(m);
		int[] dst = sailing.boarded() ? worldMapOverlay.tile(m) : null;
		if (stop < 0 && dst == null) return;
		menuBlock = true;
		ChartPlotterTrip trip = routes.trip();
		if (!trip.empty()) client.getMenu().createMenuEntry(-1).setOption("Clear trip").setTarget("Chart Plotter").setType(MenuAction.RUNELITE).onClick(me -> routes.clear());
		if (stop >= 0) {
			int x = trip.x(stop);
			int y = trip.y(stop);
			client.getMenu().createMenuEntry(-1).setOption("Remove stop and later").setTarget("Chart Plotter").setType(MenuAction.RUNELITE).onClick(me -> routes.truncate(stop, x, y));
			client.getMenu().createMenuEntry(-1).setOption("Remove stop").setTarget("Chart Plotter").setType(MenuAction.RUNELITE).onClick(me -> routes.remove(stop, x, y));
			return;
		}
		if (!sailing.boarded()) return;
		if (!trip.empty() && routes.canAppend()) client.getMenu().createMenuEntry(-1).setOption("Add stop").setTarget("Chart Plotter").setType(MenuAction.RUNELITE).onClick(me -> routes.append(dst[0], dst[1]));
		client.getMenu().createMenuEntry(-1).setOption("Set destination").setTarget("Chart Plotter").setType(MenuAction.RUNELITE).onClick(me -> routes.set(dst[0], dst[1]));
	}
	public void menu(MenuOptionClicked e) {
		if (!features.course) return;
		WorldView top = sailing.top();
		if (top == null) return;
		sailing.command(ChartPlotterSailing.commandHeading(e.getMenuAction(), e.getId(), e.getMenuEntry().getWorldViewId(), e.isConsumed(), sailing.boarded(), top.getId(), top.getYellowClickAction()), client.getMouseCanvasPosition());
	}
	public void tick() {
		pendingView = null;
		worldMapOverlay.tick();
		if (!features.tracking || !sailing.boarded() || client.getGameState() != GameState.LOGGED_IN) return;
		sailing.tick();
		WorldEntity ship = sailing.ship();
		if (ship == null) {
			sailing.clear();
			scene.clear();
			clearCourses();
			routes.pause();
			collision(false, null);
			return;
		}
		LocalPoint loc = sailing.anchorLoc(ship);
		if (loc == null) {
			sailing.clear();
			scene.clear();
			clearCourses();
			routes.pause();
			collision(false, null);
			return;
		}
		WorldView top = sailing.top();
		boolean sceneChanged = top != null && sailing.sceneChanged(top);
		if (top != null && features.scene) scene.update(top);
		if (sceneChanged) sailing.scene(ship, loc);
		boolean normal = features.cache(sailing.boarded()) && top != null && top.getPlane() == 0 && !top.isInstance();
		boolean started = collision(normal, top);
		if (sceneChanged && normal && !started) capture(top);
		if (normal) collisionCache.refresh(top);
		int boatId = ship.getWorldView().getId();
		if (observedBoat != boatId) {
			observedBoat = boatId;
			sailing.clear();
			sailing.scene(ship, loc);
			routes.scene();
			projection.clear();
			sceneChanged = true;
		}
		sailing.motion(ship, loc, sceneChanged);
		courses(top, ship, loc, client.getTickCount());
		alert(top, loc);
	}
	void courses(WorldView top, WorldEntity ship, LocalPoint loc, int tick) {
		pendingView = top;
		pendingBoat = ship;
		pendingAnchor = loc;
		pendingTick = tick;
		pendingHeading = sailing.heading(ship);
		courses();
		if (features.course && pendingView != null) projection.update(top, ship.getConfig(), loc, pendingHeading);
	}
	public void clientTick() {
		courses();
		if (features.course) projection.refresh(pendingBoat);
	}
	private void clearCourses() {
		pendingView = null;
		pendingBoat = null;
		pendingAnchor = null;
		projection.clear();
	}
	private void courses() {
		WorldView top = pendingView;
		if (top == null) return;
		if (collisionCache.refreshing()) return;
		pendingView = null;
		if (features.course) {
			sailing.observe(pendingTick, collisionCache.snapshot(), pendingBoat.getConfig(), top.getBaseX() * 128 + pendingAnchor.getX(), top.getBaseY() * 128 + pendingAnchor.getY(), pendingHeading);
			projection.update(top, pendingBoat.getConfig(), pendingAnchor, pendingHeading);
		}
		if (features.chart) routes.tick(top, pendingBoat, pendingAnchor);
	}
	public void object(TileObject object, boolean spawned) {if (collisionActive) collisionCache.changed(object, spawned);}
	public void focus(boolean focused) {this.focused = focused;}
	public void message(PluginMessage e) {
		if (!"chartplotter".equals(e.getNamespace())) return;
		if ("clear".equals(e.getName())) {
			clientThread.invoke(routes::clear);
			return;
		}
		if (!"chart".equals(e.getName())) return;
		int x = tile(e.getData().get("x"));
		int y = tile(e.getData().get("y"));
		if (x < 0 || y < 0) return;
		clientThread.invoke(() -> {
			if (features.chart && sailing.boarded()) routes.set(x, y);
		});
	}
	private void alert(WorldView top, LocalPoint loc) {
		ChartPlotterRoute r = routes.route();
		if (!config.courseTurnAlert() || top == null || r == null || sailing.reversing()) {
			alertX = Integer.MIN_VALUE;
			alertY = Integer.MIN_VALUE;
			return;
		}
		if (focused) return;
		double bx = top.getBaseX() + loc.getX() / (double) Perspective.LOCAL_TILE_SIZE;
		double by = top.getBaseY() + loc.getY() / (double) Perspective.LOCAL_TILE_SIZE;
		ChartPlotterRoutes.Turn turn = ChartPlotterRoutes.turn(r, bx, by, sailing.speed(), sailing.accel(), sailing.maxSpeed(), sailing.motionTime());
		if (!turn.valid || turn.end || turn.ticks < 0 || turn.ticks > ALERT_TICKS || turn.x == alertX && turn.y == alertY) return;
		notifier.notify("Sailing: next turn approaching");
		alertX = turn.x;
		alertY = turn.y;
	}
	private void apply() {
		pendingView = null;
		ChartPlotterFeatures prev = features;
		ChartPlotterFeatures next = ChartPlotterFeatures.of(config);
		features = next;
		sailing.average(config.infoTripEta() != ChartPlotterEtaMode.OFF || config.infoStopEta() != ChartPlotterEtaMode.OFF);
		infoOverlay.clear();
		if (next.worldOverlay != prev.worldOverlay) {
			if (next.worldOverlay) overlayManager.add(overlay);
			else {
				overlayManager.remove(overlay);
				overlay.clear();
			}
		}
		if (next.minimapOverlay != prev.minimapOverlay) {
			if (next.minimapOverlay) overlayManager.add(minimapOverlay);
			else {
				overlayManager.remove(minimapOverlay);
				minimapOverlay.clear();
			}
		}
		if (next.worldMapOverlay != prev.worldMapOverlay) {
			if (next.worldMapOverlay) overlayManager.add(worldMapOverlay);
			else {
				overlayManager.remove(worldMapOverlay);
				worldMapOverlay.clear();
			}
		}
		if (next.infoOverlay != prev.infoOverlay) {
			if (next.infoOverlay) overlayManager.add(infoOverlay);
			else overlayManager.remove(infoOverlay);
		}
		if (next.scene && !prev.scene) {
			updateScene();
		} else if (!next.scene && prev.scene) scene.clear();
		if (prev.chart && !next.chart) {
			routes.stop();
			cancelStopDrag();
		}
		if (next.input && !inputRegistered) {
			mouseManager.registerMouseListener(mouse);
			keyManager.registerKeyListener(key);
			inputRegistered = true;
		} else if (!next.input && inputRegistered) {
			mouseManager.unregisterMouseListener(mouse);
			keyManager.unregisterKeyListener(key);
			inputRegistered = false;
			clearMods();
		}
		if (!next.cache(sailing.boarded())) collision(false, null);
		if (prev.course && !next.course) clearCourses();
		if (!next.tracking) sailing.reset();
		else if (!prev.tracking) clientThread.invoke(() -> {
			if (!features.tracking) return;
			sailing.sync();
			updateScene();
		});
	}
	void chartStop(Point m, int stop, int x, int y, boolean moved, int version) {
		if (version != inputVersion.get() || !features.chart || !sailing.boarded()) return;
		if (moved) {
			int[] dst = worldMapOverlay.tile(m);
			if (dst != null) routes.move(stop, x, y, dst[0], dst[1]);
		} else if (worldMapOverlay.stop(m) == stop) routes.remove(stop, x, y);
	}
	void chartCourse(Point m, boolean active, boolean shift, int version) {
		if (version != inputVersion.get() || !features.chart || worldMapOverlay.clickBlocked()) return;
		int stop = worldMapOverlay.stop(m);
		if (stop >= 0) {
			if (shift) routes.truncate(stop);
			else routes.remove(stop);
			return;
		}
		if (!active || !sailing.boarded()) return;
		int[] dst = worldMapOverlay.tile(m);
		if (dst == null) return;
		if (shift) routes.append(dst[0], dst[1]);
		else routes.set(dst[0], dst[1]);
	}
	private boolean courseClick() {
		if (!features.chart || !sailing.boarded() || downAlt) return false;
		ChartPlotterWorldMapClick click = config.worldMapCourseClick();
		return click == ChartPlotterWorldMapClick.CLICK || click == ChartPlotterWorldMapClick.CTRL_CLICK && downCtrl;
	}
	private void mods(KeyEvent e) {
		boolean ctrl = e.isControlDown();
		boolean shift = e.isShiftDown();
		if (e.getID() == KeyEvent.KEY_PRESSED) {
			if (e.getKeyCode() == KeyEvent.VK_CONTROL) ctrl = true;
			if (e.getKeyCode() == KeyEvent.VK_SHIFT) shift = true;
		} else if (e.getID() == KeyEvent.KEY_RELEASED) {
			if (e.getKeyCode() == KeyEvent.VK_CONTROL) ctrl = false;
			if (e.getKeyCode() == KeyEvent.VK_SHIFT) shift = false;
		}
		worldMapOverlay.courseMods(ctrl, shift);
	}
	private void clearMods() {
		inputVersion.incrementAndGet();
		down = false;
		menuBlock = false;
		cancelStopDrag();
		worldMapOverlay.courseMods(false, false);
	}
	private void cancelStopDrag() {
		draggedStop = -1;
		stopPress = false;
		worldMapOverlay.clearStopDrag();
	}
	private boolean collision(boolean active, WorldView top) {
		if (active == collisionActive) return false;
		collisionActive = active;
		if (active) {
			collisionCache.start();
			capture(top);
			return true;
		}
		collisionCache.stop();
		return false;
	}
	private void capture(WorldView top) {
		if (collisionActive) collisionCache.capture(top);
	}
	private void updateScene() {
		if (!features.scene || !sailing.boarded()) return;
		WorldView top = sailing.top();
		if (top != null) scene.update(top);
	}
	private static int tile(Object value) {
		if (!(value instanceof Integer)) return -1;
		int tile = (Integer) value;
		return tile >= 0 && tile <= MAX_WORLD_TILE ? tile : -1;
	}
}

package com.chartplotter.runtime;

import com.chartplotter.collision.ChartPlotterCollisionData;
import com.chartplotter.collision.ChartPlotterHull;
import com.chartplotter.overlay.ChartPlotterOverlay;
import com.chartplotter.util.ChartPlotterMath;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.atomic.AtomicInteger;

@Singleton
public final class ChartPlotterSailing {
	private static final int MOTION_HOLD = 2;
	private static final int COURSE_STALL = 2;
	private final Client client;
	private volatile WorldView top;
	volatile boolean boarded;
	private double baseSpeed;
	private double accel;
	private int speedCap;
	private int boost;
	private int windCharges;
	private int windEnabled;
	private int windPaused;
	private int startOnHeading;
	private long inputs;
	private Observation observation;
	private ChartPlotterHull forecastHull;
	private double estimate = Double.NaN;
	volatile Forecast forecast = Forecast.UNKNOWN;
	private int moveMode;
	private int lastMoveMode = 2;
	private double speed;
	private double lastSpeed;
	private volatile SpeedAverage speedAverage;
	private int motionHold;
	private int courseTicks;
	private int turnDir;
	private int lastAngle;
	private int lastBaseX = Integer.MIN_VALUE;
	private int lastBaseY = Integer.MIN_VALUE;
	private int lastPlane = Integer.MIN_VALUE;
	private int course = -1;
	private final AtomicInteger commandVersion = new AtomicInteger();
	private int potentialX;
	private int potentialY;
	private LocalPoint lastLoc;
	private volatile WorldEntity shipCache;
	private volatile WorldView shipTop;
	private volatile Player shipPlayer;
	private volatile int shipPid = Integer.MIN_VALUE;
	private volatile int shipTick = Integer.MIN_VALUE;
	private long motionTime;
	private boolean potentialBlocked;
	@Inject
	@SuppressWarnings("SameParameterValue")
	ChartPlotterSailing(Client client) {
		this.client = client;
	}
	public void sync() {
		if (client.getGameState() != GameState.LOGGED_IN) return;
		boarded = client.getVarbitValue(VarbitID.SAILING_BOARDED_BOAT) == 1;
		if (boarded) syncTop();
		varbit(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED, client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED));
		varbit(VarbitID.SAILING_SIDEPANEL_BOAT_ACCELERATION, client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_ACCELERATION));
		varbit(VarbitID.SAILING_SIDEPANEL_BOAT_MOVE_MODE, client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_MOVE_MODE));
		varbit(VarbitID.SAILING_SIDEPANEL_BOAT_SPEEDCAP, client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_SPEEDCAP));
		varbit(VarbitID.SAILING_BOAT_SPEEDBOOST_DURATION, client.getVarbitValue(VarbitID.SAILING_BOAT_SPEEDBOOST_DURATION));
		varbit(VarbitID.SAILING_SIDEPANEL_BOAT_WIND_CHARGES, client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_WIND_CHARGES));
		varbit(VarbitID.SAILING_SIDEPANEL_BOAT_WIND_CATCHER_ENABLED, client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_WIND_CATCHER_ENABLED));
		varbit(VarbitID.SAILING_BOAT_WINDS_TIMER_PAUSED, client.getVarbitValue(VarbitID.SAILING_BOAT_WINDS_TIMER_PAUSED));
		varbit(VarbitID.SAILING_START_BOAT_WHEN_SETTING_HEADING, client.getVarbitValue(VarbitID.SAILING_START_BOAT_WHEN_SETTING_HEADING));
	}
	public void varbit(VarbitChanged e) {
		varbit(e.getVarbitId(), e.getValue());
	}
	private void varbit(int id, int value) {
		if (id == VarbitID.SAILING_BOARDED_BOAT) {
			boarded = value == 1;
			if (boarded) syncTop();
			return;
		}
		if (id == VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED) {if (baseSpeed == value / 128.0) return; baseSpeed = value / 128.0;}
		else if (id == VarbitID.SAILING_SIDEPANEL_BOAT_ACCELERATION) {if (accel == value / 128.0) return; accel = value / 128.0;}
		else if (id == VarbitID.SAILING_SIDEPANEL_BOAT_MOVE_MODE) {if (moveMode == value) return; lastMoveMode = moveMode; moveMode = value;}
		else if (id == VarbitID.SAILING_SIDEPANEL_BOAT_SPEEDCAP) {if (speedCap == value) return; speedCap = value;}
		else if (id == VarbitID.SAILING_BOAT_SPEEDBOOST_DURATION) {if (boost == value) return; boost = value;}
		else if (id == VarbitID.SAILING_SIDEPANEL_BOAT_WIND_CHARGES) {if (windCharges == value) return; windCharges = value;}
		else if (id == VarbitID.SAILING_SIDEPANEL_BOAT_WIND_CATCHER_ENABLED) {if (windEnabled == value) return; windEnabled = value;}
		else if (id == VarbitID.SAILING_BOAT_WINDS_TIMER_PAUSED) {if (windPaused == value) return; windPaused = value;}
		else if (id == VarbitID.SAILING_START_BOAT_WHEN_SETTING_HEADING) {if (startOnHeading == value) return; startOnHeading = value;}
		else return;
		inputs++;
		forecast = Forecast.UNKNOWN;
	}
	public void loaded(WorldView wv) {
		if (wv != null && wv.isTopLevel()) {
			top = wv;
			resetShip();
		}
	}
	public void reset() {
		commandVersion.incrementAndGet();
		top = null;
		boarded = false;
		course = -1;
		baseSpeed = 0;
		accel = 0;
		moveMode = 0;
		lastMoveMode = 2;
		potentialBlocked = false;
		lastBaseX = Integer.MIN_VALUE;
		lastBaseY = Integer.MIN_VALUE;
		lastPlane = Integer.MIN_VALUE;
		resetShip();
		resetMotion();
	}
	public void clear() {
		commandVersion.incrementAndGet();
		course = -1;
		potentialBlocked = false;
		resetMotion();
	}
	public void scene(WorldEntity ship, LocalPoint loc) {
		observation = null;
		estimate = Double.NaN;
		resetShip();
		motionHold = MOTION_HOLD;
		lastLoc = loc;
		lastAngle = targetHeading(ship);
	}
	public void motion(WorldEntity ship, LocalPoint loc, boolean skip) {
		motionTime = System.currentTimeMillis();
		if (!skip && lastLoc != null) {
			int vx = loc.getX() - lastLoc.getX();
			int vy = loc.getY() - lastLoc.getY();
			int angle = targetHeading(ship);
			turnDir = ChartPlotterMath.angleDir(lastAngle, angle, 0);
			if (course >= 0) {
				courseTicks = angle == lastAngle ? courseTicks + 1 : 0;
				if (angle == course || courseTicks >= COURSE_STALL) course = -1;
			}
			lastAngle = angle;
			if (vx == 0 && vy == 0 && motionHold > 0 && lastSpeed > 0) motionHold--;
			else {
				motionHold = 0;
				double s = ChartPlotterMath.speed(vx, vy);
				double a = s - lastSpeed;
				if (a < 10) sample(s);
			}
		} else if (!skip) lastAngle = targetHeading(ship);
		lastLoc = loc;
	}
