import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.api.worldmap.WorldMapData;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.awt.geom.Area;

@Singleton
public final class ChartPlotterWorldMap {
	private static final int TS = Perspective.LOCAL_TILE_SIZE;
	private static final int[][] SURFACE = {{3222, 3218}, {3213, 3424}, {2964, 3378}, {2662, 3305}};
	private static final int[] BLOCK = {InterfaceID.Worldmap.OVERVIEW_CONTAINER, InterfaceID.Worldmap.SIDE, InterfaceID.Worldmap.BOTTOM, InterfaceID.Worldmap.MAPLIST_CONTAINER, InterfaceID.Worldmap.CLOSE, InterfaceID.Worldmap.RESIZE_INDICATOR, InterfaceID.Worldmap.RESIZE_GRAPHIC};
	private final Client client;
	private ClipKey clipKey;
	private Shape cachedClip;
	private WorldMapData surfaceData;
	private boolean cachedSurface;
	private volatile boolean cachedClickBlocked = true;
	@Inject
	public ChartPlotterWorldMap(Client client) {
		this.client = client;
	}
	public void clear() {
		clipKey = null;
		cachedClip = null;
		surfaceData = null;
		cachedClickBlocked = true;
	}
	public State state() {
		Widget map = widget();
		WorldMap wm = client.getWorldMap();
		if (map == null || wm == null) {
			cachedClickBlocked = true;
			return null;
		}
		WorldMapData data = wm.getWorldMapData();
		float z = wm.getWorldMapZoom();
		Point pos = wm.getWorldMapPosition();
		boolean blocked = blocked(data);
		cachedClickBlocked = blocked;
		if (blocked || z <= 0 || pos == null) return null;
		Rectangle r = map.getBounds();
		int wt = (int) Math.ceil(r.getWidth() / z);
		int ht = (int) Math.ceil(r.getHeight() / z);
		double c = z - Math.ceil(z / 2.0);
		return new State(data, z, r, wt, ht, pos, c);
	}
	public int[] tile(Point m) {return tile(m, state());}
	public int[] tile(Point m, State s) {
		if (m == null || s == null || !clip(s).contains(m.getX(), m.getY())) return null;
		int wx = (int) Math.floor(worldX(m, s));
		int wy = (int) Math.floor(worldY(m, s));
		return s.data.surfaceContainsPosition(wx, wy) ? new int[]{wx, wy} : null;
	}
	public boolean tile(Point m, State s, int[] out) {
		if (m == null || s == null || out == null || out.length < 2 || !clip(s).contains(m.getX(), m.getY())) return false;
		int wx = (int) Math.floor(worldX(m, s));
		int wy = (int) Math.floor(worldY(m, s));
		if (!s.data.surfaceContainsPosition(wx, wy)) return false;
		out[0] = wx;
		out[1] = wy;
		return true;
	}
	public boolean clickBlocked() {
		WorldMap wm = client.getWorldMap();
		if (wm == null) {
			cachedClickBlocked = true;
			return true;
		}
		WorldMapData data = wm.getWorldMapData();
		boolean blocked = blocked(data);
		cachedClickBlocked = blocked;
		return blocked;
	}
	public boolean cachedClickBlocked() {return cachedClickBlocked;}
	public int pointX(State s, double wx) {
		int halfWidth = s.wt / 2;
		return (int) Math.round(s.r.getX() + (wx + halfWidth - s.pos.getX() - 0.5) * s.z + s.c);
	}
	public int pointY(State s, double wy) {
		int halfHeight = s.ht / 2;
		return (int) Math.round(s.r.getY() + s.r.getHeight() - (wy + halfHeight - s.pos.getY() + 0.5) * s.z + s.c);
	}
	public double worldX(Point m, State s) {
		int halfWidth = s.wt / 2;
		return (m.getX() - s.r.getX() - s.c) / s.z - halfWidth + s.pos.getX() + 0.5;
	}
	public double worldY(Point m, State s) {
		int halfHeight = s.ht / 2;
		return (s.r.getY() + s.r.getHeight() + s.c - m.getY()) / s.z - 0.5 + s.pos.getY() - halfHeight;
	}
	public int mapX(State s, int baseX, int lx) {return pointX(s, baseX + lx / (double) TS);}
	public int mapY(State s, int baseY, int ly) {return pointY(s, baseY + ly / (double) TS);}
	public int pathCap(WorldView wv, LocalPoint anchor, State s) {
		double ax = wv.getBaseX() + anchor.getX() / (double) TS;
		double ay = wv.getBaseY() + anchor.getY() / (double) TS;
		double dx = Math.max(Math.abs(ax - (s.pos.getX() - s.wt / 2.0)), Math.abs(ax - (s.pos.getX() + s.wt / 2.0)));
		double dy = Math.max(Math.abs(ay - (s.pos.getY() - s.ht / 2.0)), Math.abs(ay - (s.pos.getY() + s.ht / 2.0)));
		return (int) Math.ceil(Math.max(dx, dy) * 8) + 64;
	}
	public Shape clip(State s) {
		if (clipKey != null && clipKey.same(client, s)) return cachedClip;
		ClipKey k = new ClipKey(client, s);
		Rectangle r = new Rectangle(s.r.x + 1, s.r.y + 1, Math.max(1, s.r.width - 2), Math.max(1, s.r.height - 2));
		Area a = new Area(r);
		boolean cut = false;
		for (int id : BLOCK) {
			Widget w = client.getWidget(id);
			if (w == null || w.isHidden()) continue;
			a.subtract(new Area(w.getBounds()));
			cut = true;
		}
		clipKey = k;
		cachedClip = cut ? a : r;
		return cachedClip;
	}
	private Widget widget() {
		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		return map == null || map.isHidden() ? null : map;
	}
	private boolean surface(WorldMapData data) {
		if (surfaceData == data) return cachedSurface;
		surfaceData = data;
		for (int[] p : SURFACE) {
			if (!data.surfaceContainsPosition(p[0], p[1])) return cachedSurface = false;
		}
		return cachedSurface = true;
	}
	private boolean blocked(WorldMapData data) {return data == null || !surface(data) || client.getVarcIntValue(VarClientID.WORLDMAP_INTERMAPLINK) > 0;}
	public static final class State {
		public final WorldMapData data;
		public final float z;
		public final Rectangle r;
		public final int wt;
		public final int ht;
		public final Point pos;
		public final double c;
		public State(WorldMapData data, float z, Rectangle r, int wt, int ht, Point pos, double c) {
			this.data = data;
			this.z = z;
			this.r = r;
			this.wt = wt;
			this.ht = ht;
			this.pos = pos;
			this.c = c;
		}
	}
	private static final class ClipKey {
		final int[] v;
		private ClipKey(Client client, State s) {
			v = new int[4 + BLOCK.length * 5];
			int i = 0;
			v[i++] = s.r.x;
			v[i++] = s.r.y;
			v[i++] = s.r.width;
			v[i++] = s.r.height;
			for (int id : BLOCK) {
				Widget w = client.getWidget(id);
				if (w == null || w.isHidden()) {
					v[i++] = 0;
					i += 4;
					continue;
				}
				Rectangle b = w.getBounds();
				v[i++] = 1;
				v[i++] = b.x;
				v[i++] = b.y;
				v[i++] = b.width;
				v[i++] = b.height;
			}
		}
		boolean same(Client client, State s) {
			int i = 0;
			if (v[i++] != s.r.x || v[i++] != s.r.y || v[i++] != s.r.width || v[i++] != s.r.height) return false;
			for (int id : BLOCK) {
				Widget w = client.getWidget(id);
				if (w == null || w.isHidden()) {
					if (v[i] != 0) return false;
					i += 5;
					continue;
				}
				Rectangle b = w.getBounds();
				if (v[i++] != 1 || v[i++] != b.x || v[i++] != b.y || v[i++] != b.width || v[i++] != b.height) return false;
			}
			return true;
		}
	}
}

package com.chartplotter.util;
import java.io.File;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
public final class ChartPlotterFiles {
	private ChartPlotterFiles() {}
	public static boolean replace(File tmp, File dst) {
		try {
			Files.move(tmp.toPath(), dst.toPath(), StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
			return true;
		} catch (AtomicMoveNotSupportedException e) {
			try {
				Files.move(tmp.toPath(), dst.toPath(), StandardCopyOption.REPLACE_EXISTING);
				return true;
			} catch (Exception ignored) {
				return false;
			}
		} catch (Exception ignored) {
			return false;
		}
	}
}

package com.chartplotter.util;
import net.runelite.api.Perspective;
public final class ChartPlotterMath {
	private ChartPlotterMath() {}
	public static int rotateX(int cx, int o, int x, int y) {return cx + (int) (((long) Perspective.COSINE[o] * x + (long) Perspective.SINE[o] * y) >> 16);}
	public static int rotateY(int cy, int o, int x, int y) {return cy + (int) (((long) Perspective.COSINE[o] * y - (long) Perspective.SINE[o] * x) >> 16);}
	public static int worldTile(int base, int local) {return base + Math.floorDiv(local, Perspective.LOCAL_TILE_SIZE);}
	public static int chebyshev(int ax, int ay, int bx, int by) {return Math.max(Math.abs(ax - bx), Math.abs(ay - by));}
	public static double orientationToDegrees(int angle) {return 270 - angle / (2048 / 360.0);}
	public static int angleDir(int start, int target, int current) {
		double d = orientationToDegrees(target) - orientationToDegrees(start);
		if (d < -180) return -1;
		if (d > 180) return 1;
		if (d == 180 || d == -180) return current < 0 ? -1 : 1;
		if (d == 0) return 0;
		return -(int) (d / Math.abs(d));
	}
	public static int norm(int v) {return ((v % 2048) + 2048) % 2048;}
	public static int round(double v) {return (int) (Math.round(Math.abs(v)) * Math.signum(v));}
	public static int snap(int v) {return round(v / 32.0) * 32;}
	public static int velocityX(double speed, int heading) {return snap(round(-Perspective.SINE[heading] * speed / 512.0));}
	public static int velocityY(double speed, int heading) {return snap(round(-Perspective.COSINE[heading] * speed / 512.0));}
	public static double speed(int vx, int vy) {
		double x = vx / 128.0;
		double y = vy / 128.0;
		return Math.round(Math.sqrt(x * x + y * y) / 0.5) * 0.5;
	}
}

package com.chartplotter.util;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public final class ChartPlotterVersions {
	private static final String FILE = "versions.txt";
	private ChartPlotterVersions() {}
	public static synchronized String read(File dir, String key) {
		return readAll(dir).get(key);
	}
	public static synchronized boolean write(File dir, String key, String version) {
		if (!valid(version)) return false;
		Map<String, String> data = readAll(dir);
		File tmp = new File(dir, FILE + ".tmp");
		try {Files.createDirectories(dir.toPath());} catch (Exception ignored) {return false;}
		try {
			try (BufferedWriter out = Files.newBufferedWriter(tmp.toPath(), StandardCharsets.UTF_8)) {
				data.put(key, version);
				for (Map.Entry<String, String> e : data.entrySet()) out.write(e.getKey() + " " + e.getValue() + "\n");
			}
			return ChartPlotterFiles.replace(tmp, file(dir));
		} catch (Exception ignored) {
			return false;
		} finally {
			try {Files.deleteIfExists(tmp.toPath());} catch (IOException ignored) {}
		}
	}
	public static synchronized void remove(File dir, String key) throws IOException {
		File tmp = new File(dir, FILE + ".tmp");
		try {
			List<String> data;
			try {data = Files.readAllLines(file(dir).toPath(), StandardCharsets.UTF_8);}
			catch (NoSuchFileException e) {return;}
			if (!data.removeIf(line -> key.equals(line.trim().split("\\s+", 2)[0]))) return;
			Files.write(tmp.toPath(), data, StandardCharsets.UTF_8);
			if (!ChartPlotterFiles.replace(tmp, file(dir))) throw new IOException("Unable to update dataset versions");
		} finally {Files.deleteIfExists(tmp.toPath());}
	}
	public static boolean newer(String src, String dst) {
		return valid(src) && (!valid(dst) || src.compareTo(dst) > 0);
	}
	private static Map<String, String> readAll(File dir) {
		Map<String, String> data = new TreeMap<>();
		File file = file(dir);
		if (!file.isFile()) return data;
		try (BufferedReader in = new BufferedReader(new InputStreamReader(new FileInputStream(file), StandardCharsets.UTF_8))) {
			String s;
			while ((s = in.readLine()) != null) {
				String[] p = s.trim().split("\\s+");
				if (p.length == 2 && valid(p[1])) data.put(p[0], p[1]);
			}
		} catch (Exception ignored) {
		}
		return data;
	}
	private static boolean valid(String s) {
		if (s == null || s.length() != 10) return false;
		try {LocalDate.parse(s); return true;} catch (DateTimeParseException e) {return false;}
	}
	private static File file(File dir) {return new File(dir, FILE);}
}
